'use strict';
const assert = require('assert');
const { Event, Gate, Axiom, fuseChain, canFuse } = require('../core');
const { unifiedDispatch } = require('../dispatch');
const { PopulationStore, reuseCountPromotionPolicy } = require('../dispatch/population');
const { FlatFileCrystallizer } = require('../plugins/crystallizer-flatfile');
const { scoreDefault } = require('../plugins/scorer-default');
const { runCascade, runTwoStage } = require('../dispatch/cascade');
const { canonicalize, fingerprintKey, similarityScore } = require('../dispatch/canonicalize');
const { preGenerationCheck } = require('../dispatch/pregen');
const { computeDelta, applyDelta, DeltaCrystallizer } = require('../dispatch/deltaCache');

let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log(`  ok — ${name}`); }
  catch (e) { fail++; console.log(`  FAIL — ${name}: ${e.stack}`); }
}
async function testAsync(name, fn) {
  try { await fn(); pass++; console.log(`  ok — ${name}`); }
  catch (e) { fail++; console.log(`  FAIL — ${name}: ${e.stack}`); }
}

console.log('WARP v1.4 tests — canonicalization, pre-generation, population lifecycle, two-stage, fusion, axiom weighting, delta cache');

// ── canonicalize.js ─────────────────────────────────────────────────────────

test('canonicalize strips undefined keys, -0, trailing whitespace', () => {
  const c = canonicalize({ b: 2, a: undefined, c: -0, d: 'hi   ' });
  assert.deepStrictEqual(c, { b: 2, c: 0, d: 'hi' });
});

test('fingerprintKey is identical for same shape, different content', () => {
  const f1 = fingerprintKey({ kind: 'button', label: 'Submit' });
  const f2 = fingerprintKey({ kind: 'button', label: 'Cancel' });
  assert.strictEqual(f1, f2);
});

test('fingerprintKey differs for different shape', () => {
  const f1 = fingerprintKey({ kind: 'button', label: 'Submit' });
  const f2 = fingerprintKey({ kind: 'button', label: 'Submit', disabled: true });
  assert.notStrictEqual(f1, f2);
});

test('similarityScore is 1.0 for identical shape, less than 1 for a shape with an extra field', () => {
  const a = { kind: 'button', label: 'Submit' };
  const b = { kind: 'button', label: 'Cancel' };
  const c = { kind: 'button', label: 'Cancel', disabled: true };
  assert.strictEqual(similarityScore(a, b), 1);
  assert.ok(similarityScore(a, c) < 1);
  assert.ok(similarityScore(a, c) > 0);
});

// ── pregen.js ────────────────────────────────────────────────────────────────

test('preGenerationCheck reuses a population variant above threshold', () => {
  const population = new PopulationStore();
  population.retain('btn', { output: { rendered: true }, fitness: 0.9, digest: 'd1', sourceEventData: { kind: 'button', label: 'Submit' } });
  const result = preGenerationCheck({ eventData: { kind: 'button', label: 'Cancel' }, population, gateClass: 'btn', threshold: 0.87 });
  assert.strictEqual(result.action, 'reuse');
  assert.strictEqual(result.variant.digest, 'd1');
});

test('preGenerationCheck proceeds when nothing is similar enough', () => {
  const population = new PopulationStore();
  population.retain('btn', { output: { rendered: true }, fitness: 0.9, digest: 'd1', sourceEventData: { kind: 'button', label: 'Submit' } });
  const result = preGenerationCheck({ eventData: { kind: 'modal', title: 'Confirm', body: 'Are you sure?' }, population, gateClass: 'btn', threshold: 0.87 });
  assert.strictEqual(result.action, 'proceed');
});

// ── population.js lifecycle ───────────────────────────────────────────────────

test('decay reduces fitness of untouched variants on every retain, not the one just touched', () => {
  const population = new PopulationStore({ decayRate: 0.5 });
  population.retain('c', { output: 1, fitness: 0.8, digest: 'd1', sourceEventData: { a: 1 } });
  population.retain('c', { output: 2, fitness: 0.8, digest: 'd2', sourceEventData: { b: 2 } });
  const stats = population.stats('c');
  const v1 = stats.variants.find(v => v.digest === 'd1');
  const v2 = stats.variants.find(v => v.digest === 'd2');
  assert.ok(v1.fitness < 0.8, 'untouched variant should have decayed');
  assert.strictEqual(v2.fitness, 0.8, 'just-retained variant should not decay this tick');
});

test('pruning removes variants that fall below threshold, never the just-retained one', () => {
  const population = new PopulationStore({ decayRate: 0.9, pruneThreshold: 0.5 });
  population.retain('c', { output: 1, fitness: 0.51, digest: 'd1', sourceEventData: { a: 1 } });
  population.retain('c', { output: 2, fitness: 0.05, digest: 'd2', sourceEventData: { b: 2 } }); // decays d1 to 0.051 -> pruned
  const stats = population.stats('c');
  assert.strictEqual(stats.variants.find(v => v.digest === 'd1'), undefined, 'decayed-below-threshold variant should be pruned');
  assert.ok(stats.variants.find(v => v.digest === 'd2'), 'freshly retained variant survives even below threshold');
});

test('deduplication keeps only the fittest variant per structural fingerprint', () => {
  const population = new PopulationStore();
  population.retain('btn', { output: 'a', fitness: 0.5, digest: 'd1', sourceEventData: { kind: 'button', label: 'Submit' } });
  population.retain('btn', { output: 'b', fitness: 0.9, digest: 'd2', sourceEventData: { kind: 'button', label: 'Cancel' } });
  const stats = population.stats('btn');
  assert.strictEqual(stats.size, 1, 'same-shape variants should collapse to one');
  assert.strictEqual(stats.variants[0].digest, 'd2', 'the fitter of the two should survive');
});

test('reuseCountPromotionPolicy promotes on reuse_count >= 2 and success_rate >= 0.7', () => {
  const population = new PopulationStore({ promotionPolicy: reuseCountPromotionPolicy });
  let promoted = population.retain('c', { output: 1, fitness: 0.4, digest: 'd1', success: true });
  assert.strictEqual(promoted, false, 'first retain: hits=1, not yet promotable');
  promoted = population.retain('c', { output: 1, fitness: 0.4, digest: 'd1', success: true });
  assert.strictEqual(promoted, true, 'second retain: hits=2, success_rate=1.0 -> promotable');
});

// ── cascade.js two-stage ──────────────────────────────────────────────────────

async function main() {

await testAsync('runTwoStage skips refinement when skeleton passes validation cleanly', async () => {
  let calls = 0;
  const result = await runTwoStage({
    skeletonProvider: 'cheap', refinementProvider: 'strong',
    generate: async () => { calls++; return { output: { ok: true }, confidence: 0.95 }; },
    validate: () => ({ ok: true }),
  });
  assert.strictEqual(calls, 1, 'refinement stage must not run when skeleton already passes');
  assert.strictEqual(result.refined, false);
  assert.strictEqual(result.ok, true);
});

await testAsync('runTwoStage escalates to refinement on failed validation', async () => {
  let calls = 0;
  const result = await runTwoStage({
    skeletonProvider: 'cheap', refinementProvider: 'strong',
    generate: async (provider) => {
      calls++;
      if (provider === 'cheap') return { output: { partial: true }, confidence: 0.9 };
      return { output: { ok: true }, confidence: 1 };
    },
    validate: (output) => ({ ok: !!output.ok, failures: output.ok ? [] : ['missing ok field'] }),
  });
  assert.strictEqual(calls, 2, 'refinement stage must run on validation failure');
  assert.strictEqual(result.refined, true);
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.output.ok, true);
});

await testAsync('runTwoStage escalates on low confidence even when validation passes', async () => {
  let calls = 0;
  await runTwoStage({
    skeletonProvider: 'cheap', refinementProvider: 'strong',
    generate: async () => { calls++; return { output: { ok: true }, confidence: 0.2 }; },
    validate: () => ({ ok: true }),
    confidenceThreshold: 0.7,
  });
  assert.strictEqual(calls, 2, 'low confidence must trigger refinement even if validation technically passed');
});

// ── GateFusion ─────────────────────────────────────────────────────────────

test('fuseChain runs two gates as one, producing the final-stage output', () => {
  const a = new Gate('a.raw', { transform: (e) => new Event('a.parsed', { value: e.data.value * 2 }) });
  const b = new Gate('a.parsed', { transform: (e) => new Event('a.done', { value: e.data.value + 1 }) });
  const fused = fuseChain([a, b], 'a.fused');
  assert.strictEqual(fused.matches(new Event('a.raw', { value: 5 })), true);
  const out = fused.transform(new Event('a.raw', { value: 5 }));
  assert.strictEqual(out.length, 1);
  assert.strictEqual(out[0].type, 'a.done');
  assert.strictEqual(out[0].data.value, 11); // (5*2)+1
});

test('fuseChain preserves events that do not match the next stage, instead of dropping them', () => {
  const a = new Gate('a.raw', { transform: (e) => [new Event('a.parsed', { v: 1 }), new Event('unrelated', { v: 2 })] });
  const b = new Gate('a.parsed', { transform: (e) => new Event('a.done', { v: e.data.v }) });
  const fused = fuseChain([a, b], 'a.fused');
  const out = fused.transform(new Event('a.raw', {}));
  const types = out.map(e => e.type).sort();
  assert.deepStrictEqual(types, ['a.done', 'unrelated']);
});

test('canFuse returns true when a sample event type matches gateA', () => {
  const a = new Gate('a.raw', { transform: () => {} });
  assert.strictEqual(canFuse(a, null, ['a.raw']), true);
});

// ── Axiom weighting + soft-skip integration ───────────────────────────────────

await testAsync('hard axioms are never skipped even with skipVerifiedSoftAxioms + a cache-verified digest', async () => {
  const population = new PopulationStore();
  const crystallizer = new FlatFileCrystallizer({});
  const hard = new Axiom('always-fail-hard', { check: () => false, severity: 'hard' });
  let hardChecked = 0;
  const trackedHard = new Axiom('always-fail-hard', { check: () => { hardChecked++; return false; }, severity: 'hard' });
  const result = await unifiedDispatch({
    gateSignature: 'g', gateClass: 'gc', event: new Event('g', { x: 1 }),
    axioms: [trackedHard], crystallizer, population, scorer: scoreDefault,
    skipVerifiedSoftAxioms: true,
    cascade: () => runCascade({ providers: ['p'], generate: async () => ({ ok: true }), validate: () => ({ ok: true }) }),
  });
  assert.strictEqual(result.ok, false);
  assert.ok(hardChecked >= 1, 'hard axiom must always run, never skipped');
});

await testAsync('soft axioms are skipped (and logged) on a repeat of an already-scored digest when skipVerifiedSoftAxioms is true', async () => {
  const population = new PopulationStore();
  const crystallizer = new FlatFileCrystallizer({});
  let softChecked = 0;
  const soft = new Axiom('style-nit', { check: () => { softChecked++; return true; }, severity: 'soft' });
  const skipLogs = [];
  const log = { record: (r) => { if (r.step === 'axiom-gate' && r.result === 'soft-skip') skipLogs.push(r); } };

  const dispatchOnce = () => unifiedDispatch({
    gateSignature: 'g', gateClass: 'gc', event: new Event('g', { x: 1 }),
    axioms: [soft], crystallizer, population, scorer: scoreDefault,
    skipVerifiedSoftAxioms: true, log,
    cascade: () => runCascade({ providers: ['p'], generate: async () => ({ ok: true }), validate: () => ({ ok: true }) }),
  });

  await dispatchOnce(); // first pass — no population variant yet, soft axiom runs
  assert.strictEqual(softChecked, 1);

  // Manually add a second gate-class-digest variant path is awkward since
  // the first dispatch may have promoted straight to exact-cache (which
  // short-circuits before axioms entirely) — assert on whichever happened
  // rather than assuming promotion timing.
  const stats = population.stats('gc');
  if (stats.size > 0) {
    await dispatchOnce();
    assert.ok(skipLogs.length >= 1, 'soft-skip must be logged, never silent');
  }
});

// ── deltaCache.js ────────────────────────────────────────────────────────────

test('computeDelta + applyDelta reconstructs the target from a base', () => {
  const base = { name: 'card', props: { title: 'A', color: 'blue', tags: ['x', 'y'] } };
  const target = { name: 'card', props: { title: 'B', color: 'blue', tags: ['x', 'y'] } };
  const ops = computeDelta(base, target);
  assert.ok(ops.length >= 1);
  const reconstructed = applyDelta(base, ops);
  assert.deepStrictEqual(reconstructed, canonicalize(target));
});

test('computeDelta captures key deletion', () => {
  const base = { a: 1, b: 2 };
  const target = { a: 1 };
  const ops = computeDelta(base, target);
  assert.deepStrictEqual(applyDelta(base, ops), { a: 1 });
});

test('DeltaCrystallizer stores first entry per class in full, later entries as diffs, both reconstruct correctly', () => {
  const inner = new FlatFileCrystallizer({});
  const dc = new DeltaCrystallizer(inner);
  const base = { name: 'card', title: 'A', tags: ['x'] };
  const variant = { name: 'card', title: 'B', tags: ['x'] };
  dc.set('digest-base', base, 'card-class');
  dc.set('digest-variant', variant, 'card-class');

  assert.deepStrictEqual(dc.get('digest-base'), canonicalize(base));
  assert.deepStrictEqual(dc.get('digest-variant'), canonicalize(variant));
  // the second entry is genuinely stored as a diff, not a full copy
  const raw = inner.get('digest-variant');
  assert.strictEqual(raw.__delta, true);
});

console.log(`\n${pass} passed, ${fail} failed\n`);
process.exit(fail > 0 ? 1 : 0);

}

main();

'use strict';
/**
 * SISO vs WARP — same workload, both real implementations, measured not asserted.
 *
 * SISO's actual reference code (siso_ref/SISO (Core)/src/core) is loaded
 * unmodified. WARP is the code just built. Neither is mocked.
 *
 * Scenario: 5 identical "risky" events (a negative value that should never
 * be allowed to execute) sent through both. Then 20 repeated identical
 * "generate" events sent through WARP's unified dispatch to demonstrate
 * the compounding curve SISO has no mechanism for at all.
 *
 * Honesty note: no live LLM call is available in this sandbox, so
 * unifiedDispatch's cascade step uses a deterministic mock generator
 * that always succeeds (a stand-in for a model call). What's measured
 * — the exact-cache hit/miss counts, the cost curve, the axiom rejection
 * behavior — are real, not staged; only the "model" itself is a stub.
 */
const path = require('path');
const SISO_PATH = path.join(__dirname, '..', '..', 'siso_ref', 'SISO (Core)', 'src', 'core');

// SISO reference is ESM (export class ...) — read and eval as CJS-compatible
// since this sandbox runs plain node without an ESM loader configured for
// arbitrary paths. This is the actual reference source, transformed only
// enough to load, not rewritten.
const fs = require('fs');
function loadSisoModule(file) {
  const src = fs.readFileSync(path.join(SISO_PATH, file), 'utf8')
    .replace(/^export /gm, '')
    .replace(/import\s+\{([^}]+)\}\s+from\s+['"](.+)['"];?/g, 'const {$1} = require("$2");');
  const module = { exports: {} };
  const fn = new Function('module', 'exports', 'require', '__filename', '__dirname', src + '\nmodule.exports = { ' +
    (src.match(/class (\w+)/g) || []).map(c => c.replace('class ', '')).join(', ') + ' };');
  fn(module, module.exports, require, file, SISO_PATH);
  return module.exports;
}

const { Event: SisoEvent } = loadSisoModule('Event.js');
const { Gate: SisoGate } = loadSisoModule('Gate.js');
const { Stream: SisoStream } = loadSisoModule('Stream.js');

const { Event, Gate, Axiom, Stream, StreamLog } = require('../core');
const { unifiedDispatch } = require('../dispatch');
const { PopulationStore } = require('../dispatch/population');
const { FlatFileCrystallizer } = require('../plugins/crystallizer-flatfile');
const { scoreDefault } = require('../plugins/scorer-default');
const { runCascade } = require('../dispatch/cascade');

console.log('=== SISO vs WARP — head-to-head, real code, measured ===\n');

// ── Part 1: the axiom-rejection scenario — SISO structurally cannot do this ──
console.log('--- Part 1: reject a bad transform before it runs ---');

class RiskySisoGate extends SisoGate {
  constructor() { super('risky'); this.ranCount = 0; }
  transform(event) {
    this.ranCount++; // SISO has no primitive to stop this from running
  }
}
const sisoStream = new SisoStream({});
const sisoGate = new RiskySisoGate();
sisoStream.register(sisoGate);
for (let i = 0; i < 5; i++) sisoStream.emit(new SisoEvent('risky', String(-5)));
console.log(`SISO: 5 events with a "never allowed" value emitted -> gate ran ${sisoGate.ranCount}/5 times`);
console.log('  (SISO has no Axiom primitive — nothing in the framework can stop this. The paper calls this discipline, not architecture.)');

const warpStream = new Stream();
let warpRan = 0;
warpStream.register(new Gate('risky', { transform: () => { warpRan++; } }));
warpStream.registerAxiom(new Axiom('no-negative-value', {
  severity: 'hard',
  check: (event) => Number(event.data.value ?? 0) >= 0,
}));
for (let i = 0; i < 5; i++) warpStream.emit(new Event('risky', { value: -5 }));
console.log(`WARP: same 5 events -> gate ran ${warpRan}/5 times, ${warpStream.rejected.length} rejected and logged`);
console.log(`  Rejection reason on file: ${JSON.stringify(warpStream.rejected[0].failures)}\n`);

// ── Part 2: the compounding curve — cost over 20 identical requests ──
console.log('--- Part 2: cost curve over 20 identical generate requests ---');

let modelCallCount = 0;
async function mockGenerate(provider, priorFailure) {
  modelCallCount++;
  return { shape: 'valid', filledBy: provider };
}
function validateAlwaysOk(output) {
  return { ok: true };
}

const population = new PopulationStore();
const crystallizer = new FlatFileCrystallizer({}); // in-memory only, no path
const axioms = [new Axiom('shape-check', { severity: 'hard', check: () => true })];
const log = new StreamLog();

const costPerRequest = [];

async function main() {
for (let i = 0; i < 20; i++) {
  modelCallCount = 0; // reset per-request counter to measure marginal cost
  const event = new Event('generate.widget', { kind: 'button', variant: 'primary' });
  const result = await unifiedDispatch({
    gateSignature: 'generate.widget',
    gateClass: 'widget-button',
    event,
    axioms,
    crystallizer,
    population,
    scorer: scoreDefault,
    cascade: ({ event }) => runCascade({
      providers: ['cheap-model', 'strong-model'],
      generate: mockGenerate,
      validate: validateAlwaysOk,
    }),
    expectedShapeKeys: ['shape'],
    log,
  });
  costPerRequest.push({ request: i + 1, modelCalls: modelCallCount, source: result.source });
}

console.log('request# | model calls | source');
for (const r of costPerRequest) {
  console.log(`  ${String(r.request).padStart(2)}      |      ${r.modelCalls}      | ${r.source}`);
}
const firstFree = costPerRequest.findIndex(r => r.modelCalls === 0) + 1;
const totalCalls = costPerRequest.reduce((s, r) => s + r.modelCalls, 0);
console.log(`\nFirst zero-cost (crystal hit) request: #${firstFree}`);
console.log(`Total model calls across 20 identical requests: ${totalCalls} (SISO/naive re-prompt baseline would be 20)`);
console.log(`Population size for this gate-class: ${population.stats('widget-button').size} variant(s) retained`);
}

main();

'use strict';
const assert = require('assert');
const { computeDigest } = require('../dispatch/digest');
const { Axiom } = require('../core');

let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log(`  ok — ${name}`); }
  catch (e) { fail++; console.log(`  FAIL — ${name}: ${e.message}`); }
}

console.log('WARP digest regression tests (fixing the shape-only-hash bug)');

test('REGRESSION: same shape, different content -> different digests (the bug that was found)', () => {
  const axioms = [new Axiom('a1', { check: () => true })];
  const submit = computeDigest({ gateSignature: 'gen.button', axioms, eventData: { kind: 'button', label: 'Submit' } });
  const cancel = computeDigest({ gateSignature: 'gen.button', axioms, eventData: { kind: 'button', label: 'Cancel' } });
  assert.notStrictEqual(submit, cancel, 'BUG: same-shape different-content events must not collide');
});

test('Identical content -> identical digest, regardless of key insertion order', () => {
  const axioms = [new Axiom('a1', { check: () => true })];
  const d1 = computeDigest({ gateSignature: 'g', axioms, eventData: { a: 1, b: 2 } });
  const d2 = computeDigest({ gateSignature: 'g', axioms, eventData: { b: 2, a: 1 } });
  assert.strictEqual(d1, d2, 'key order must not affect the digest');
});

test('Nested object content is canonicalized recursively, not just top level', () => {
  const axioms = [new Axiom('a1', { check: () => true })];
  const d1 = computeDigest({ gateSignature: 'g', axioms, eventData: { meta: { x: 1, y: 2 } } });
  const d2 = computeDigest({ gateSignature: 'g', axioms, eventData: { meta: { y: 2, x: 1 } } });
  assert.strictEqual(d1, d2, 'nested key order must not affect the digest either');
});

test('Axiom version bump changes the digest — old cache entries do not silently survive a rule change', () => {
  const eventData = { v: 1 };
  const v1 = [new Axiom('rule', { check: () => true, version: '1.0.0' })];
  const v2 = [new Axiom('rule', { check: () => true, version: '2.0.0' })];
  const d1 = computeDigest({ gateSignature: 'g', axioms: v1, eventData });
  const d2 = computeDigest({ gateSignature: 'g', axioms: v2, eventData });
  assert.notStrictEqual(d1, d2, 'a changed axiom version must invalidate old cache entries');
});

console.log(`\n${pass} passed, ${fail} failed\n`);
process.exit(fail > 0 ? 1 : 0);

'use strict';
const assert = require('assert');
const { Event, Gate, Axiom, Stream, StreamLog } = require('../core');

let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log(`  ok — ${name}`); }
  catch (e) { fail++; console.log(`  FAIL — ${name}: ${e.message}`); }
}

console.log('WARP core tests');

test('Event is immutable', () => {
  const e = new Event('test.event', { value: 1 });
  assert.throws(() => { e.data.value = 2; }, /* frozen data */);
  assert.strictEqual(e.data.value, 1);
});

test('Event requires a non-empty type', () => {
  assert.throws(() => new Event(''), /type must be a non-empty string/);
});

test('Gate dispatches via signature match by default', () => {
  const g = new Gate('foo.bar', { transform: () => {} });
  assert.strictEqual(g.matches(new Event('foo.bar')), true);
  assert.strictEqual(g.matches(new Event('other')), false);
});

test('Gate.transform is pure — returns events, never touches a stream (testable in total isolation)', () => {
  const g = new Gate('double', { transform: (event) => new Event('doubled', { v: event.data.v * 2 }) });
  const result = g.transform(new Event('double', { v: 21 }));
  assert.strictEqual(result.type, 'doubled');
  assert.strictEqual(result.data.v, 42);
  // No stream object was ever created or passed — this is the whole point.
});

test('Stream signature collision is a hard error', () => {
  const s = new Stream();
  s.register(new Gate('x', { transform: () => {} }));
  assert.throws(() => s.register(new Gate('x', { transform: () => {} })), /Signature collision/);
});

test('Stream depth-first dispatch, matches SISO baseline behavior — gate returns the next event, Stream emits it', () => {
  const s = new Stream();
  const seen = [];
  s.register(new Gate('a', { transform: (e) => { seen.push('a'); return new Event('b'); } }));
  s.register(new Gate('b', { transform: () => { seen.push('b'); } }));
  s.emit(new Event('a'));
  assert.deepStrictEqual(seen, ['a', 'b']);
});

test('Gate returning an array of events emits all of them, depth-first', () => {
  const s = new Stream();
  const seen = [];
  s.register(new Gate('fanout', { transform: () => [new Event('x'), new Event('y')] }));
  s.register(new Gate('x', { transform: () => { seen.push('x'); } }));
  s.register(new Gate('y', { transform: () => { seen.push('y'); } }));
  s.emit(new Event('fanout'));
  assert.deepStrictEqual(seen, ['x', 'y']);
});

test('Unclaimed event lands in pending, same as SISO', () => {
  const s = new Stream();
  s.emit(new Event('unclaimed'));
  assert.strictEqual(s.pending.length, 1);
});

test('Axiom hard failure rejects the transform — never runs, never silent', () => {
  const s = new Stream();
  let ran = false;
  s.register(new Gate('risky', { transform: () => { ran = true; } }));
  s.registerAxiom(new Axiom('no-negative', {
    severity: 'hard',
    check: (event) => (event.data.value ?? 0) >= 0,
  }));
  s.emit(new Event('risky', { value: -5 }));
  assert.strictEqual(ran, false, 'gate must not run on hard axiom failure');
  assert.strictEqual(s.rejected.length, 1);
  assert.strictEqual(s.pending.length, 0, 'rejected is a distinct bucket from pending');
});

test('Axiom soft failure logs but does not block', () => {
  const s = new Stream();
  let ran = false;
  s.register(new Gate('ok', { transform: () => { ran = true; } }));
  s.registerAxiom(new Axiom('style-hint', { severity: 'soft', check: () => false }));
  s.emit(new Event('ok', {}));
  assert.strictEqual(ran, true, 'soft failure must not block execution');
  assert.strictEqual(s.rejected.length, 0);
});

test('StreamLog records every dispatch, including rejections', () => {
