'use strict';
const crypto = require('crypto');
const { canonicalize } = require('./canonicalize');

/**
 * digest.js — content-addressable cache key. Bazel/Buck2's exact pattern:
 * hash(gate signature + versioned axiom set + canonicalized event content)
 * -> deterministic digest.
 *
 * v1.0.1 fix: the original version hashed Object.keys(event.data) only —
 * shape, not content. Two events with identical keys but different values
 * ("label: Submit" vs "label: Cancel") produced the same digest and would
 * wrongly cache-hit with the wrong output. Confirmed by direct code read,
 * not theoretical — fixed here by canonicalizing full content, recursively,
 * with sorted keys at every level so key-order never affects the hash.
 *
 * v1.4: canonicalization now delegates to dispatch/canonicalize.js (the
 * "canonicalization pipeline" from the spec patch) instead of a private
 * local copy, so the exact-cache digest and the fuzzy structural-similarity
 * check in pregen.js are guaranteed to agree on what "the same shape"
 * means. _canonicalize is kept exported under its old name for anything
 * that imported it directly from here.
 */
function computeDigest({ gateSignature, axioms = [], eventData }) {
  // axioms: array of Axiom instances or {id, version} — versioned so a
  // changed axiom (different check logic) invalidates old cache entries
  // instead of silently reusing output verified under an old rule.
  const axiomKeys = axioms
    .map(a => `${a.id}@${a.version || '1.0.0'}`)
    .sort();

  const canonical = JSON.stringify({
    g: gateSignature,
    a: axiomKeys,
    d: canonicalize(eventData),
  });
  return crypto.createHash('sha256').update(canonical).digest('hex');
}

module.exports = { computeDigest, _canonicalize: canonicalize };

'use strict';
/**
 * deltaCache.js — v1.4 "structural delta cache."
 *
 * Correcting scope up front: this is a STORAGE optimization, not a
 * generation-avoidance one. It doesn't reduce model calls — exact-cache
 * (crystallizer) and pre-generation matching (pregen.js) already own
 * that. What it reduces is bytes-at-rest for a population of near-
 * duplicate promoted outputs sharing a gate-class: store one base in
 * full, store every other member as a diff against that base, reconstruct
 * on read. The spec patch filed this under the same "cheaper/faster"
 * heading as the generation-avoidance mechanisms; it isn't the same kind
 * of saving and shouldn't be counted twice against the same multiplier.
 *
 * Diff format is a flat list of {path, op, value} ops (op: 'set'|'delete'),
 * computed by walking both canonicalized structures together — good
 * enough for JSON-shaped Gate outputs, not a general-purpose diff/patch
 * library (no dependency budget for one, per MANIFEST's zero-deps rule).
 */
const { canonicalize } = require('./canonicalize');

function computeDelta(base, target) {
  const b = canonicalize(base);
  const t = canonicalize(target);
  const ops = [];
  _diffWalk(b, t, '$', ops);
  return ops;
}

function _diffWalk(b, t, path, ops) {
  const bIsObj = b !== null && typeof b === 'object';
  const tIsObj = t !== null && typeof t === 'object';

  if (!bIsObj || !tIsObj || Array.isArray(b) !== Array.isArray(t)) {
    if (JSON.stringify(b) !== JSON.stringify(t)) ops.push({ path, op: 'set', value: t });
    return;
  }

  if (Array.isArray(b)) {
    // Arrays: compared element-by-element up to the longer length. Not
    // an LCS-based diff (that's real complexity for a zero-dependency
    // devkit) — a full replace of any array that changed length or
    // whose elements changed is honest and simple, not clever.
    if (b.length !== t.length) { ops.push({ path, op: 'set', value: t }); return; }
    for (let i = 0; i < t.length; i++) _diffWalk(b[i], t[i], `${path}[${i}]`, ops);
    return;
  }

  const bKeys = new Set(Object.keys(b));
  const tKeys = new Set(Object.keys(t));
  for (const k of bKeys) if (!tKeys.has(k)) ops.push({ path: `${path}.${k}`, op: 'delete' });
  for (const k of tKeys) _diffWalk(b[k], t[k], `${path}.${k}`, ops);
}

function applyDelta(base, ops) {
  const result = JSON.parse(JSON.stringify(canonicalize(base)));
  for (const op of ops) {
    const parts = _parsePath(op.path);
    if (op.op === 'delete') {
      _deleteAtPath(result, parts);
    } else {
      _setAtPath(result, parts, op.value);
    }
  }
  return result;
}

function _parsePath(path) {
  // '$.a.b[2].c' -> ['a', 'b', 2, 'c']
  const parts = [];
  const re = /\.([^.\[\]]+)|\[(\d+)\]/g;
  let m;
  while ((m = re.exec(path)) !== null) {
    parts.push(m[1] !== undefined ? m[1] : Number(m[2]));
  }
  return parts;
}

function _setAtPath(obj, parts, value) {
  if (parts.length === 0) return value;
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (cur[parts[i]] === undefined) cur[parts[i]] = typeof parts[i + 1] === 'number' ? [] : {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

function _deleteAtPath(obj, parts) {
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (cur[parts[i]] === undefined) return;
    cur = cur[parts[i]];
  }
  delete cur[parts[parts.length - 1]];
}

/**
 * DeltaCrystallizer — wraps any base crystallizer (must implement
 * get/set), adds a delta layer per gate-class. First entry for a class
 * is stored in full as the base; every subsequent entry is stored as a
 * delta against it. Reconstruction cost (applying a diff) is paid on
 * read instead of on write — a real trade, not a free win, stated as one.
 */
class DeltaCrystallizer {
  constructor(baseStore) {
    if (!baseStore || typeof baseStore.get !== 'function' || typeof baseStore.set !== 'function') {
      throw new Error('[warp/DeltaCrystallizer] baseStore must implement get(key)/set(key,value)');
    }
    this._store = baseStore;
    this._bases = new Map(); // gateClass -> { digest, value }
  }

  get(digest) {
    const entry = this._store.get(digest);
    if (!entry) return null;
    if (entry.__delta) {
      const base = this._bases.get(entry.__baseClass);
      if (!base) return null; // base missing — cannot reconstruct, honest miss rather than a guess
      return applyDelta(base.value, entry.__ops);
    }
    return entry.__full !== undefined ? entry.__full : entry;
  }

  set(digest, value, gateClass = null) {
    if (!gateClass || !this._bases.has(gateClass)) {
      // Canonicalize before storing — computeDelta/applyDelta always work
      // on canonicalized structures, so the base must match that shape
      // too, or a later diff-then-reconstruct round trip won't equal
      // canonicalize(original) even though it's semantically the same
      // value (just different key order / raw non-canonical noise).
      const canonicalValue = canonicalize(value);
      if (gateClass) this._bases.set(gateClass, { digest, value: canonicalValue });
      this._store.set(digest, { __full: canonicalValue });
      return;
    }
    const base = this._bases.get(gateClass);
    const ops = computeDelta(base.value, value);
    this._store.set(digest, { __delta: true, __baseClass: gateClass, __ops: ops });
  }
}

module.exports = { computeDelta, applyDelta, DeltaCrystallizer };

'use strict';
/**
 * cascade.js — model cascading (cheap-first cost pattern) + retry ladder.
 * Generalizes seam-queue.js's context/shorter/forensic strategy shape
 * without any NEXUS-specific naming. Escalates only on real failure,
 * feeds the failure back as context — never a blind identical retry.
 */
async function runCascade({ providers, generate, validate, maxAttempts = 3 }) {
  if (!Array.isArray(providers) || providers.length === 0) {
    throw new Error('[warp/cascade] providers must be a non-empty array, cheapest first');
  }
  const attempts = [];
  let lastFailure = null;

  for (let i = 0; i < maxAttempts; i++) {
    const provider = providers[Math.min(i, providers.length - 1)];
    // §FIX 2026-09-11 — James, from a live manifest: nine chunks assigned
    // to claude/deepseek/gemini all failed with the IDENTICAL error
    // "ollama dispatch failed: huihui_ai/qwen2.5-coder-abliterate:7b
    // timed out after 120000ms" — the exact ollama-path error text, on
    // chunks that never should have touched ollama at all. Root cause:
    // generate() (warp-build-dispatch.js's real implementation) THROWS
    // on a real dispatch failure — that's real, documented behavior,
    // its own header says so. This loop called it with no try/catch,
    // so that throw propagated straight out of runCascade(), out of
    // unifiedDispatch() (warp/dispatch/index.js:91 has the same bare
    // `await cascade(...)`, no catch either), and landed in warp-build-
    // dispatch.js's own outer catch — which returns { ok:false,
    // error: e.message } verbatim. The cascade never reached provider
    // 2 or 3: attempt 1's exception WAS the function exiting, not a
    // recorded failure the loop could act on. providers[0] is always
    // 'ollama' (LAW_I, see warp-cascade.js's providersFor — a separate,
    // real bug fixed alongside this one), so EVERY cascade died on
    // ollama's own 120s timeout before ever trying the chunk's actual
    // requested agent, regardless of what that agent was.
    let output, threw = null;
    try {
      output = await generate(provider, lastFailure); // lastFailure = context on retry
    } catch (e) {
      threw = e;
    }
    if (threw) {
      attempts.push({ attempt: i + 1, provider, passed: false, failures: [], error: threw.message });
      lastFailure = { ok: false, failures: [threw.message] };
      continue;
    }
    const result = validate(output);
    attempts.push({ attempt: i + 1, provider, passed: result.ok, failures: result.failures || [] });

    if (result.ok) {
      return { ok: true, output, attempts };
    }
    lastFailure = result;
  }

  return { ok: false, output: null, attempts, exhausted: true };
}

/**
 * runTwoStage — v1.4 "two-stage generation pipeline." Distinct from
 * runCascade above, which is an N-attempt ladder across providers:
 * two-stage is exactly two phases —
 *
 *   stage 1 (skeleton): cheapest available model, asked for structure
 *     only (whatever "structural_outline_only" means for a given Gate's
 *     schema — WARP doesn't interpret that, the generate function does).
 *   stage 2 (refinement): runs ONLY if stage 1 fails validation or
 *     reports low confidence. Uses a stronger model, fed stage 1's
 *     output as context — refining, not starting over.
 *
 * "low confidence" needs a concrete signal or this condition is
 * unenforceable. WARP does not invent one: the stage-1 generate function
 * must return a `confidence` number (0..1) alongside its output, or the
 * gate is opting out of confidence-gating and only fails_validation
 * triggers stage 2.
 */
async function runTwoStage({
  skeletonProvider, refinementProvider, generate, validate,
  confidenceThreshold = 0.7,
}) {
  if (!skeletonProvider || !refinementProvider) {
    throw new Error('[warp/cascade] runTwoStage requires both skeletonProvider and refinementProvider');
  }

  const stage1 = await generate(skeletonProvider, null);
  const stage1Result = validate(stage1.output ?? stage1);
  const stage1Output = stage1.output ?? stage1;
  const stage1Confidence = typeof stage1.confidence === 'number' ? stage1.confidence : null;

  const lowConfidence = stage1Confidence !== null && stage1Confidence < confidenceThreshold;
  const needsRefinement = !stage1Result.ok || lowConfidence;

  const attempts = [{
    attempt: 1, stage: 'skeleton', provider: skeletonProvider,
    passed: stage1Result.ok, confidence: stage1Confidence, failures: stage1Result.failures || [],
  }];

  if (!needsRefinement) {
    return { ok: true, output: stage1Output, attempts, refined: false };
  }

  const stage2 = await generate(refinementProvider, { previousOutput: stage1Output, reason: !stage1Result.ok ? 'fails_validation' : 'low_confidence', failures: stage1Result.failures });
  const stage2Output = stage2.output ?? stage2;
  const stage2Result = validate(stage2Output);
  attempts.push({
    attempt: 2, stage: 'refinement', provider: refinementProvider,
    passed: stage2Result.ok, failures: stage2Result.failures || [],
  });

  return { ok: stage2Result.ok, output: stage2Result.ok ? stage2Output : null, attempts, refined: true, exhausted: !stage2Result.ok };
}

module.exports = { runCascade, runTwoStage };

'use strict';
/**
 * canonicalize.js — v1.4 addition. Two separate things live here on
 * purpose, because they answer two different questions:
 *
 *   canonicalize(value)     -> "are these two values EXACTLY equal,
 *                               ignoring non-semantic noise?"
 *   fingerprint(value)      -> "are these two values SHAPED alike?"
 *   similarityScore(a, b)   -> "how alike are their shapes, 0..1?"
 *
 * The v1.4 patch doc asked for "deep AST normalization" with steps like
 * normalize_identifiers and flatten_equivalent_structures. Those are real
 * operations on *source code* (an actual AST) — proving two different-
 * looking code trees are semantically identical is a hard, separate
 * problem (constant folding, alpha-renaming, associativity, etc.) that a
 * generic reimplementation here cannot honestly claim to solve for
 * arbitrary languages. What WARP actually has is *event data* — plain
 * JSON-shaped values — so this module canonicalizes at that level:
 * deterministic key order, dropped non-semantic noise (undefined keys,
 * -0, trailing whitespace), nothing more. If a consumer wants real code
 * AST canonicalization, that belongs in a Gate-specific hook, not core.
 */

function canonicalize(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Object.is(value, -0) ? 0 : value;
  if (typeof value === 'string') return value.replace(/\s+$/g, '');
  if (typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(canonicalize);

  const sorted = {};
  for (const k of Object.keys(value).sort()) {
    const v = value[k];
    if (v === undefined) continue; // strip non-semantic "key present but undefined"
    sorted[k] = canonicalize(v);
  }
  return sorted;
}

/**
 * fingerprint(value) — walks the canonical structure and records
 * (path, type) pairs, discarding leaf *content*. Two payloads with the
 * same keys/nesting/types but different string or number values produce
 * the same fingerprint. This is deliberately coarser than the exact-cache
 * digest — it's the basis for fuzzy structural matching, never for a
 * cache hit that skips axiom checks on real content.
 */
function fingerprint(value, prefix = '$', out = new Set()) {
  const c = canonicalize(value);
  if (c === null) {
    out.add(`${prefix}:null`);
  } else if (Array.isArray(c)) {
    out.add(`${prefix}:array[${c.length}]`);
    c.forEach((item, i) => fingerprint(item, `${prefix}[${Math.min(i, 3)}]`, out)); // cap index buckets so long arrays don't blow up the set
  } else if (typeof c === 'object') {
    const keys = Object.keys(c).sort();
    out.add(`${prefix}:object{${keys.join(',')}}`);
    for (const k of keys) fingerprint(c[k], `${prefix}.${k}`, out);
  } else {
    out.add(`${prefix}:${typeof c}`);
  }
  return out;
}

function fingerprintKey(value) {
  return [...fingerprint(value)].sort().join('|');
}

/**
 * similarityScore(a, b) -> Jaccard index over the two fingerprint sets,
 * 0 (nothing alike) .. 1 (identical shape). This is what
 * pre_generation.structural_prediction.threshold compares against —
 * threshold 0.87 means "87% of structural (path,type) pairs match,"
 * a concrete, testable definition instead of an unstated one.
 */
function similarityScore(a, b) {
  const fa = fingerprint(a);
  const fb = fingerprint(b);
  if (fa.size === 0 && fb.size === 0) return 1;
  let intersection = 0;
  for (const item of fa) if (fb.has(item)) intersection++;
  const union = fa.size + fb.size - intersection;
  return union === 0 ? 1 : intersection / union;
}

module.exports = { canonicalize, fingerprint, fingerprintKey, similarityScore };

'use strict';
const { computeDigest } = require('./digest');
const { DEFAULT_PROMOTE_THRESHOLD } = require('./population');
const { preGenerationCheck } = require('./pregen');

/**
 * Version: 1.4.1 — exact cache may be written on first success when a caller
 *   opts in (exactCacheOnFirstSuccess). See docs/warp-devkit-addendum-v1.4.1.spec.
 *   Default behaviour unchanged.
 *
 * unifiedDispatch — the seven steps from warp.spec + the v1.4 patch, as
 * one function. This is the actual merge: not three systems, one path
 * an event takes.
 *
 * 1. exact-cache check      (Bazel CAS pattern)
 * 1.5 pre-generation filter (v1.4 — fuzzy structural reuse, opt-in)
 * 2. population seed        (AlphaEvolve pattern)
 * 3. cascade-generate       (cheap-first cost pattern)
 * 4. axiom-gate             (hard rejection, never silent; v1.4 cost-weighted)
 * 5. score-and-retain       (evolutionary retention + promotion)
 * 6. escalate-on-failure    (context-fed retry, not blind)
 */
async function unifiedDispatch({
  gateSignature, gateClass, event, axioms, crystallizer, population,
  scorer, cascade, expectedShapeKeys = [], tokenBudget = null,
  exploreWidth = 1, log = null,
  // v1.4 additions — both opt-in, both off by default, matching every
  // other addition in this file: new behavior only activates when a
  // caller explicitly asks for it.
  preGeneration = null, // { enabled: true, threshold: 0.87 } to turn on
  skipVerifiedSoftAxioms = false,
  // §COMPOUNDING 2026-07-09 — opt-in, off by default, following this file's
  // own stated law two lines above. When true, a first successful, hard-gate-
  // validated output for an IDENTICAL input (exact digest) is written to the
  // exact cache immediately, instead of waiting for three independent
  // regenerations. See the comment at step 5. exactCacheFitnessMin mirrors
  // population.js's DEFAULT_FITNESS_MIN (0.7), passed rather than imported so
  // this module keeps its zero-coupling to population's internals.
  exactCacheOnFirstSuccess = false,
  exactCacheFitnessMin = 0.7,
}) {
  // v1.0.1: digest now hashes full canonicalized event.data, not just its
  // keys — fixes the collision bug where two different requests with the
  // same shape produced the same cache key. See dispatch/digest.js header.
  const digest = computeDigest({ gateSignature, axioms, eventData: event.data });

  // Step 1 — exact cache
  const cached = crystallizer.get(digest);
  if (cached) {
    log?.record({ step: 'exact-cache', result: 'hit', digest, cost: 0 });
    return { ok: true, output: cached, source: 'crystal', cost: 0, digest };
  }
  log?.record({ step: 'exact-cache', result: 'miss', digest });

  // Step 1.5 — pre-generation filter (v1.4). A fuzzy cousin of step 1:
  // "no exact digest match, but something structurally close enough
  // already exists in the population, reuse it instead of generating."
  // The reused output is NOT returned as-is — it still runs the axiom
  // gate below like any other candidate. Fuzzy reuse skips *generation*,
  // never skips *verification*.
  let pregenReuse = null;
  if (preGeneration?.enabled) {
    const result = preGenerationCheck({
      eventData: event.data, population, gateClass,
      threshold: preGeneration.threshold, log,
    });
    if (result.action === 'reuse') pregenReuse = result.variant;
  }

  // Step 2 — population seed
  const seed = population.seed(gateClass);
  log?.record({ step: 'population-seed', result: seed ? 'found' : 'empty', gateClass });

  // Step 3 — cascade generate, with bounded exploration ("recursive
  // simulation until best method") per exploreWidth. Default 1 = a single
  // attempt, same cost as before. exploreWidth > 1 runs multiple candidates
  // and keeps the one that scores highest — not the first that merely
  // passes — trading extra generation cost now for a better crystal later.
  // This only runs on a miss; once promoted, exploration cost is paid
  // exactly once per gate-class-digest, never repeated.
  //
  // v1.4: if the pre-generation filter found a fuzzy match, that reused
  // output becomes the single candidate instead of invoking cascade() at
  // all — this is the actual "avoid generation" saving. exploreWidth is
  // ignored in this branch: there's nothing to explore, only one thing
  // to verify.
  const candidates = pregenReuse
    ? [{ ok: true, output: pregenReuse.output, attempts: [], reusedFrom: pregenReuse.digest }]
    : await (async () => {
      const out = [];
      for (let i = 0; i < Math.max(1, exploreWidth); i++) out.push(await cascade({ seed, event }));
      return out;
    })();
  log?.record({
    step: 'cascade-generate',
    candidates: candidates.length,
    attempts: candidates.reduce((s, c) => s + (c.attempts?.length ?? (pregenReuse ? 0 : 1)), 0),
    source: pregenReuse ? 'pre-generation-reuse' : 'cascade',
  });

  // Step 4 — axiom gate, applied per-candidate; only passing candidates
  // compete on score.
  //
  // v1.4 cost weighting: axioms are evaluated highest-weight-first (hard
  // before soft by default), so an expensive soft check never delays a
  // cheap hard rejection. A SOFT axiom may be skipped — treated as
  // passed, logged as skipped, never silently dropped — only when
  // skipVerifiedSoftAxioms is true AND this exact digest already has a
  // population variant on record (i.e. this content was seen and scored
  // before). HARD axioms are never skipped, under any option, for any
  // reason — that guarantee is not configurable, on purpose.
  const orderedAxioms = [...axioms].sort((a, b) => (b.weight ?? 0) - (a.weight ?? 0));
  const existingVariant = skipVerifiedSoftAxioms
    ? population.variantsFor(gateClass).find(v => v.digest === digest)
    : null;

  // §fix 2026-07-05: evaluateAxioms() used to close over the outer `event`
  // param only — every candidate in the loop below was checked against the
  // fixed *request* event, never against what cascade() actually produced.
  // The axiom-gate ran, logged a result, and always checked the same
  // thing regardless of which candidate was being scored: a pass/fail that
  // looked like verification but wasn't reading the content it was meant
  // to gate. Same failure shape as the bridge/router.js `.response` bug —
  // matches at the outer call, wrong underneath. Axiom.check's own
  // contract ("predicate the Stream runs against every transform") means
  // "transform" here is the candidate's output, so that's what gets passed.
  function evaluateAxioms(candidateEvent) {
    const axiomFailures = [];
    const skipped = [];
    for (const axiom of orderedAxioms) {
      if (axiom.severity === 'soft' && existingVariant) {
        skipped.push(axiom.id);
        continue; // logged via `skipped`, not silently omitted
      }
      const passed = axiom.check(candidateEvent, { signature: gateSignature }, {});
      if (!passed) axiomFailures.push({ axiomId: axiom.id, severity: axiom.severity });
    }
    if (skipped.length) log?.record({ step: 'axiom-gate', result: 'soft-skip', axioms: skipped, reason: 'cache-verified', digest });
    return axiomFailures;
  }

  // Each candidate is checked against an event carrying ITS OWN output,
  // not the shared request event — this is the actual fix, everything
  // above is unchanged plumbing.
  const candidateEventFor = (cascadeResult) => ({
    ...event,
    data: { ...event.data, output: cascadeResult.output },
  });

  const scored = [];
  for (const cascadeResult of candidates) {
    const axiomFailures = evaluateAxioms(candidateEventFor(cascadeResult));
    const hardFail = axiomFailures.some(f => f.severity === 'hard');
    if (hardFail) continue; // this candidate is out, others may still pass
    const fitness = scorer({ axiomFailures, output: cascadeResult.output, expectedShapeKeys, tokenBudget });
    scored.push({ cascadeResult, axiomFailures, fitness });
  }

  if (scored.length === 0) {
    // Every candidate failed hard axioms — report the failures against the
    // last candidate actually tried (representative), never silently
    // report "nothing happened."
    const last = candidates[candidates.length - 1];
    const axiomFailures = evaluateAxioms(candidateEventFor(last));
    log?.record({ step: 'axiom-gate', result: 'reject-all-candidates', failures: axiomFailures });
    return { ok: false, output: null, source: 'rejected', failures: axiomFailures, digest };
  }

  // Best of the surviving candidates by fitness — "recursive simulation
  // until you find the best method" made concrete: not first-pass, best-pass.
  scored.sort((a, b) => b.fitness - a.fitness);
  const { cascadeResult, fitness } = scored[0];
  log?.record({ step: 'axiom-gate', result: 'pass', survivors: scored.length, chosenFitness: fitness });

  // Step 5 — score and retain (fitness already computed above during
  // selection). sourceEventData is stored alongside so pregen.js can
  // fuzzy-match future events against this shape.
  const readyToPromote = population.retain(gateClass, {
    output: cascadeResult.output, fitness, digest,
    sourceEventData: event.data, success: cascadeResult.ok,
  });
  log?.record({ step: 'score-and-retain', fitness, readyToPromote });

  // §COMPOUNDING 2026-07-09 — WARP did not compound, and its own header said
  // so: "the exact-cache isn't populated after one success ... an identical
  // chunk has to be independently re-generated and retained 3 times."
  //
  // That conflated two different mechanisms:
  //   - POPULATION is generalization. A gateClass variant is promoted only
  //     after DEFAULT_PROMOTE_THRESHOLD (3) independent successes clearing a
  //     fitness floor, because it will be reused for inputs that are SIMILAR,
  //     not identical. Three trials is the right bar for that. Unchanged.
  //   - The EXACT CACHE is memoization. `digest` is content-addressed over the
  //     request event (see dispatch/digest.js): a hit means the input is
  //     IDENTICAL, not similar. Requiring three regenerations of identical
  //     input is three times the tokens for one answer, and means the cache
  //     can never make the next build cheaper than the last.
  //
  // Safety, verified rather than assumed: step 4 returns
  // `{ok:false, source:'rejected'}` on any HARD axiom failure before reaching
  // here, so every output at this point is already hard-gate validated. We
  // additionally require cascadeResult.ok and the same fitness floor the
  // promotion path uses, so a barely-passing variant is never frozen forever.
  //
  // Effect: each successful build makes the identical next one cost 0. That is
  // what compounding means — the value accumulates instead of resetting.
  const exactCacheable = exactCacheOnFirstSuccess
    && cascadeResult.ok
    && cascadeResult.output != null
    && fitness >= exactCacheFitnessMin;

  if (readyToPromote) {
    crystallizer.set(digest, cascadeResult.output);
    log?.record({ step: 'promote', digest, threshold: DEFAULT_PROMOTE_THRESHOLD });
  } else if (exactCacheable) {
    crystallizer.set(digest, cascadeResult.output);
    log?.record({ step: 'exact-cache-write', digest, fitness, reason: 'first-success-identical-input' });
  }

  return {
    ok: cascadeResult.ok,
    output: cascadeResult.output,
    source: pregenReuse ? 'pre-generation-reuse' : 'generated',
    fitness,
    attempts: cascadeResult.attempts?.length ?? 1,
    digest,
  };
}

module.exports = { unifiedDispatch };

