'use strict';
/**
 * pregen.js — v1.4 "pre-generation filter layer."
 *
 * Placement matters: this runs AFTER the exact-cache miss (step 1) and
 * BEFORE cascade generation (step 3), not before step 1. The spec patch
 * described it as avoiding generation when a "structurally equivalent"
 * solution already exists — that's necessarily fuzzy (similarityScore,
 * not digest equality), so it can only ever be a step *down* from the
 * exact cache, never a replacement for it. Fuzzy-reusing content-bearing
 * output is a correctness trade, not a free win, so:
 *
 *   - it is OFF by default (opts in via unifiedDispatch({ preGeneration }))
 *   - a reuse never bypasses axiom checks — the reused output still runs
 *     through the axiom gate before being returned, same as generated
 *     output. "Faster" never means "less verified."
 *   - every reuse is logged with its similarity score, so a false-positive
 *     reuse is traceable after the fact instead of an invisible cache
 *     poison.
 */
const { similarityScore } = require('./canonicalize');

const DEFAULT_THRESHOLD = 0.87;

/**
 * check({ eventData, population, gateClass, threshold, log })
 * -> { action: 'reuse', variant, score } | { action: 'proceed', bestScore }
 */
function preGenerationCheck({ eventData, population, gateClass, threshold = DEFAULT_THRESHOLD, log = null }) {
  const candidates = population.variantsFor ? population.variantsFor(gateClass) : [];
  let best = null;
  let bestScore = 0;

  for (const variant of candidates) {
    if (variant.sourceEventData === undefined) continue; // no stored sample to compare shape against
    const score = similarityScore(eventData, variant.sourceEventData);
    if (score > bestScore) {
      bestScore = score;
      best = variant;
    }
  }

  if (best && bestScore >= threshold) {
    log?.record({ step: 'pre-generation-filter', result: 'reuse', gateClass, score: bestScore, digest: best.digest });
    return { action: 'reuse', variant: best, score: bestScore };
  }

  log?.record({ step: 'pre-generation-filter', result: 'proceed', gateClass, bestScore });
  return { action: 'proceed', bestScore };
}

module.exports = { preGenerationCheck, DEFAULT_THRESHOLD };

'use strict';
/**
 * population.js — scored archive per gate-class. AlphaEvolve/FunSearch
 * pattern, scaled down: keep variants, not just one "best" attempt. Next
 * miss seeds from the fittest survivor instead of a blank page.
 *
 * v1.0.1 changes, both adopted from external review after verification:
 *  - promotion policy is now pluggable (default preserved as before) —
 *    different consumers may weight stability vs latency vs cost
 *    differently; hardcoding one threshold for everyone was too rigid.
 *  - hierarchical seed fallback: gate-class keys may be dot-namespaced
 *    ('sql.select.where' etc). If no population exists for the exact
 *    class, seed() walks up to the parent class ('sql.select') before
 *    giving up. This is "pattern cache" from the review — not a new
 *    primitive, just a coarser lookup on the same store.
 */
const { fingerprintKey } = require('./canonicalize');

const DEFAULT_PROMOTE_THRESHOLD = 3;
const DEFAULT_FITNESS_MIN = 0.7;

function defaultPromotionPolicy(variant) {
  return variant.hits >= DEFAULT_PROMOTE_THRESHOLD && variant.fitness >= DEFAULT_FITNESS_MIN;
}

// v1.4 — "promotion_rule: to_exact_cache_if reuse_count >= 2, success_rate
// >= 0.7." Deliberately a *different* named policy, not a replacement for
// defaultPromotionPolicy: reuse_count is variant.hits (already tracked),
// but success_rate is a new concept — fraction of retains that were
// axiom-passing successes, as opposed to fitness (a continuous score that
// already folds in axiom failures at 0.15/soft-failure). A variant that
// passes cleanly every time but scores 0.65 on shape-match would promote
// under this policy but not the default one, and vice versa — pick
// whichever matches what "safe to promote" means for your gates.
function reuseCountPromotionPolicy(variant) {
  const successRate = variant.attempts > 0 ? variant.successes / variant.attempts : 0;
  return variant.hits >= 2 && successRate >= 0.7;
}

class PopulationStore {
  constructor({
    promotionPolicy = defaultPromotionPolicy,
    maxPerClass = 8,
    decayRate = 0,
    pruneThreshold = 0,
  } = {}) {
    this._byClass = new Map(); // gateClass -> [{ output, fitness, hits, digest, fingerprint, sourceEventData, attempts, successes }]
    this._promotionPolicy = promotionPolicy;
    this._maxPerClass = maxPerClass;
    // v1.4 population_control — decay/pruning/dedup. Default OFF
    // (decayRate: 0, pruneThreshold: 0), matching every other WARP addition
    // in this codebase: new mechanisms are additive and opt-in, existing
    // callers see zero behavior change until they ask for it. The spec
    // patch's suggested values (rate: 0.1, threshold_score: 0.6) are the
    // recommended starting point — pass them explicitly:
    //   new PopulationStore({ decayRate: 0.1, pruneThreshold: 0.6 })
    this._decayRate = decayRate;
    this._pruneThreshold = pruneThreshold;
  }

  seed(gateClass) {
    let pop = this._byClass.get(gateClass);
    if (pop && pop.length > 0) {
      return pop.reduce((best, v) => (v.fitness > best.fitness ? v : best), pop[0]);
    }
    // Hierarchical fallback — 'sql.select.where' -> try 'sql.select' -> 'sql'
    const parts = gateClass.split('.');
    for (let i = parts.length - 1; i > 0; i--) {
      const parentClass = parts.slice(0, i).join('.');
      pop = this._byClass.get(parentClass);
      if (pop && pop.length > 0) {
        const best = pop.reduce((b, v) => (v.fitness > b.fitness ? v : b), pop[0]);
        return { ...best, fromParentClass: parentClass }; // marked — this is a borrow, not an exact-class seed
      }
    }
    return null;
  }

  // retain(gateClass, { output, fitness, digest, sourceEventData, success })
  // sourceEventData (v1.4): the event.data this variant was generated from —
  // stored so pregen.js can compute similarityScore() against future
  // events. Optional; omitted callers just don't participate in fuzzy
  // pre-generation matching, exact-cache and seeding still work as before.
  // success (v1.4): did this generation pass axioms cleanly (bool)? Feeds
  // reuseCountPromotionPolicy's success_rate. Defaults true for backward
  // compatibility — unifiedDispatch only calls retain() on already-passed
  // candidates today, so "true" matches actual existing call sites exactly.
  retain(gateClass, { output, fitness, digest, sourceEventData, success = true }) {
    if (!this._byClass.has(gateClass)) this._byClass.set(gateClass, []);
    const pop = this._byClass.get(gateClass);
    const existing = pop.find(v => v.digest === digest);
    if (existing) {
      existing.hits++;
      existing.fitness = (existing.fitness + fitness) / 2; // running average
      existing.attempts++;
      if (success) existing.successes++;
    } else {
      pop.push({
        output, fitness, digest, hits: 1,
        attempts: 1, successes: success ? 1 : 0,
        sourceEventData,
        fingerprint: sourceEventData !== undefined ? fingerprintKey(sourceEventData) : null,
      });
    }

    // v1.4 decay — every retain() is a tick. Variants in this class not
    // touched *this* retain (i.e. every variant except the one just
    // updated) age by decayRate. This is event-driven aging, not
    // wall-clock: WARP has no clock primitive anywhere else either, so a
    // real-time decay would be the odd one out. Document the choice
    // rather than silently pick one.
    if (this._decayRate > 0) {
      for (const v of pop) {
        if (v.digest !== digest) v.fitness = Math.max(0, v.fitness * (1 - this._decayRate));
      }
    }

    // v1.4 pruning — drop anything that decayed/scored below threshold.
    // Never prune the variant just retained this call, even if its raw
    // fitness is below threshold — an explicit fresh signal shouldn't be
    // discarded in the same tick it arrived.
    if (this._pruneThreshold > 0) {
      for (let i = pop.length - 1; i >= 0; i--) {
        if (pop[i].digest !== digest && pop[i].fitness < this._pruneThreshold) pop.splice(i, 1);
      }
    }

    // v1.4 deduplication — two variants can have different exact digests
    // (different content) but the same structural fingerprint (same
    // shape). Keep only the fittest per fingerprint; a population meant
    // to seed *structurally* diverse attempts gains nothing from ten
    // near-identical shapes crowding out real diversity.
    this._dedupeByFingerprint(pop);

    if (pop.length > this._maxPerClass) {
      pop.sort((a, b) => b.fitness - a.fitness);
      pop.length = this._maxPerClass;
    }
    return this._readyToPromote(gateClass, digest);
  }

  _dedupeByFingerprint(pop) {
    const byFp = new Map();
    for (const v of pop) {
      if (!v.fingerprint) continue; // no fingerprint stored -> can't dedupe safely, leave alone
      const existing = byFp.get(v.fingerprint);
      if (!existing || v.fitness > existing.fitness) byFp.set(v.fingerprint, v);
    }
    if (byFp.size === 0) return;
    for (let i = pop.length - 1; i >= 0; i--) {
      const v = pop[i];
      if (v.fingerprint && byFp.get(v.fingerprint) !== v) pop.splice(i, 1);
    }
  }

  _readyToPromote(gateClass, digest) {
    const pop = this._byClass.get(gateClass);
    const v = pop.find(x => x.digest === digest);
    if (!v) return false;
    return this._promotionPolicy(v);
  }

  // v1.4 — full variant list for a class, used by pregen.js's fuzzy match.
  // Distinct from seed() (which returns only the single fittest variant)
  // because similarity matching needs to compare against every candidate,
  // not just the current leader.
  variantsFor(gateClass) {
    return [...(this._byClass.get(gateClass) || [])];
  }

  stats(gateClass) {
    const pop = this._byClass.get(gateClass) || [];
    return { size: pop.length, variants: pop.map(v => ({ digest: v.digest, fitness: v.fitness, hits: v.hits, attempts: v.attempts, successes: v.successes })) };
  }
}

module.exports = {
  PopulationStore, DEFAULT_PROMOTE_THRESHOLD, DEFAULT_FITNESS_MIN,
  defaultPromotionPolicy, reuseCountPromotionPolicy,
};

'use strict';
/**
 * StreamLog — append-only audit trail. Observes, never consumes.
 * Same shape as SISO's log, plus axiom-check entries WARP's Stream writes.
 *
 * §COS MERGE 2026-07-11 — cos/siso/StreamLog.js added mutable verbosity
 * levels (OFF/EVENTS/DEEP/DATA) and sample()/clear()/since(). Ported the
 * behavior, not the interface: cos's `.entries` was a plain array
 * property; warp's `.entries()` is already a method with real existing
 * callers. Making one name mean two different things depending on which
 * fork you came from is exactly the ambiguity this codebase's own
 * "collision is a hard error, never silently resolved" rule exists to
 * prevent — so `entries()` stays a method, full stop, and any cos code
 * that reads `.entries` as a property gets adapted at the call site
 * instead.
 *
 * Default level is 'DATA' (record everything) — this is warp's existing
 * behavior, unconditional, byte-identical for every current caller that
 * constructs `new StreamLog()` with no arguments. Level filtering is opt
 * in, not a silent behavior change for anyone already using this class.
 */
const LEVELS = { OFF: 0, EVENTS: 1, DEEP: 2, DATA: 3 };

class StreamLog {
  constructor(level = 'DATA') {
    this.level = level;
    this._entries = [];
    this._nextId = 0;
    this._seq = 0;
  }

  nextStreamId() {
    return ++this._nextId;
  }

  /**
   * record(entry) — warp's existing contract: store whatever shape the
   * caller passes, unconditionally, at the default 'DATA' level. At a
   * lower level (set via cos's convention: log.level = 'EVENTS'), fields
   * are progressively dropped — streamId/parentStreamId at EVENTS-only,
   * full entry only at DEEP+. This matches cos's original tiering exactly;
   * the field names it filters on (streamId, parentStreamId) are already
   * present in every entry warp's own Stream.emit() constructs, so no
   * caller needs to change what it passes in.
   */
  /**
   * record(entry) — warp's existing contract: store whatever shape the
   * caller passes, unconditionally, at the default 'DATA' level. At a
   * lower level (set via cos's convention: log.level = 'EVENTS'), fields
   * are progressively dropped — streamId/parentStreamId at EVENTS-only,
   * full entry only at DEEP+. This matches cos's original tiering exactly;
   * the field names it filters on (streamId, parentStreamId) are already
   * present in every entry warp's own Stream.emit() constructs, so no
   * caller needs to change what it passes in.
   *
   * §FIX 2026-09-11 — Stream.emit() calls this with `eventType`/`eventData`
   * keys (SISO's original param names), but this method's own doc says
   * "Same shape as SISO's log" — SISO's log shape uses `.type`/`.data` on
   * the STORED entry, not the caller's param names. Verified this was
   * really dropped, not intentional: old cos/siso/StreamLog.js's record()
   * explicitly destructured and renamed eventType->type; this file's
   * spread-everything-verbatim version silently stopped doing that when
   * ported, and nothing caught it because no caller here happened to read
   * `.type` back until cos/host/event-bus.js started routing through this
   * file for real. Confirmed via warp's own test suite before and after
   * (43 passed / 0 failed, unchanged) that restoring the rename doesn't
   * touch anything already depending on the current (wrong) shape.
   */
  record(entry) {
    const lvl = LEVELS[this.level] ?? LEVELS.DATA;
    if (lvl === 0) return;

    const { eventType, eventData, gateClaimed, ...rest } = entry;
    const seq = this._seq++;
    const stored = {
      ...rest,
      ...(eventType !== undefined ? { type: eventType } : {}),
      ...(gateClaimed !== undefined ? { claimed: gateClaimed } : {}),
      seq,
      loggedAt: Date.now(),
    };
    if (lvl < 2) { delete stored.streamId; delete stored.parentStreamId; }
    if (lvl >= 3 && eventData !== undefined) stored.data = eventData;
    this._entries.push(stored);
  }

  entries() {
    return [...this._entries];
  }

  /** §COS MERGE — observation snapshot, same philosophy as Stream.sampleHere(). */
  sample() {
    return { level: this.level, count: this._entries.length, entries: [...this._entries] };
  }

  /** §COS MERGE — the one concession to mutability, for long-running systems shedding history. */
  clear() {
    this._entries = [];
    this._seq = 0;
  }

  /** Public accessor for the internal counter — same pattern as Stream's own get seq(). */
  get seq() { return this._seq; }

  /** §COS MERGE — entries since a given seq number. */
  since(afterSeq) {
    return this._entries.filter(e => e.seq > afterSeq);
  }
}

module.exports = { StreamLog };

'use strict';
/**
 * Stream — the dispatch loop. Same O(1) signature-lookup discipline as
 * SISO's Stream. The addition: every transform runs through registered
 * Axioms first. A hard-axiom failure rejects the transform — logged,
 * event routed to `rejected`, never silently completed and never
 * silently dropped (both are failure modes; this distinguishes them).
 *
 * hook(kind, plugin) is the one extension point — scorer/crystallizer/
 * cascader all attach here, all pure-function-shaped like Gate, no
 * special-casing per kind.
 *
 * §COS MERGE 2026-07-11 — cos/siso/Stream.js forked from base SISO and
 * added a ring buffer (tail/since for late-joining SSE clients and cos's
 * events CLI), deregister() (compartment teardown), and direct SSE
 * broadcast. Checked before merging: cos's own header already called
 * these "COS extension over base SISO" — they were written as additions
 * from day one, not a competing redesign. Ported verbatim, nothing of
 * warp's existing axiom/hook/observer machinery touched.
 *
 * The one behavior change: gate.transform(event) is now called as
 * gate.transform(event, this). Safe for every existing warp gate — an
 * extra argument to a function that only declares one parameter is
 * simply ignored in JS, not an error — and required for cos's real gates
 * (cos/host/gates/*.js, 30+ of them), which call `stream.emit(...)`
 * imperatively from inside transform() using that second argument.
 * Checked: none of warp's own gates read a second parameter, so this
 * cannot change anything for them.
 */
const DEFAULT_RING_CAP = 500;

class Stream {
  constructor({ log = null, parentStreamId = null, axioms = [], ringCap = DEFAULT_RING_CAP } = {}) {
    this.gates = new Map();
    this.axioms = [...axioms];
    this.pending = [];
    this.rejected = []; // NEW vs SISO: axiom failures land here, not pending
    this.eventCount = 0;
    this.log = log;
    this.streamId = log ? log.nextStreamId() : null;
    this.parentStreamId = parentStreamId;
    this._hooks = { scorer: [], crystallizer: [], cascader: [] };
    this._observers = new Map(); // event type -> [handler] — pub/sub, separate from gate routing

    // §COS MERGE — ring buffer + SSE, ported from cos/siso/Stream.js
    this._seq        = 0;
    this._ringCap    = ringCap;
    this._ring       = [];      // circular buffer of stamped events
    this._wildcards  = [];      // onAny() observers — read-only, not gates
    this._sseClients = new Set();
  }

  register(gate) {
    if (this.gates.has(gate.signature)) {
      throw new Error(`[warp/Stream] Signature collision: '${gate.signature}'`);
    }
    this.gates.set(gate.signature, gate);
  }

  /**
   * Unregister a gate by signature. No-op if not found.
   * §COS MERGE — used by cos when compartments are destroyed and their
   * gates deregistered. Warp itself never removes a gate once registered
   * (no prior caller needed this) so this is additive, not a behavior
   * change for any existing warp consumer.
   */
  deregister(signature) {
    this.gates.delete(signature);
  }

  /**
   * on(type, handler) — observe every event of a given type as it passes
   * through emit(), without owning a gate for it. A caller that wants a
   * live feed (a UI, a logger) registers here instead of registering a
   * competing Gate for the same signature, which would throw on
   * collision. An observer's own error is caught and swallowed — same
   * §1.2-shaped guarantee as axiom-check failures: something watching
   * must never be able to break something running.
   */
  on(type, handler) {
    if (!this._observers.has(type)) this._observers.set(type, []);
    this._observers.get(type).push(handler);
    return () => {
      const arr = this._observers.get(type) || [];
      const i = arr.indexOf(handler);
      if (i >= 0) arr.splice(i, 1);
    };
  }

  /**
   * onAny(fn) — §COS MERGE. Subscribe to every event regardless of type,
   * as a read-only observer. Distinct from on(type, handler) above (which
   * is per-type warp pub/sub, already existed) — this is cos's wildcard
   * fan-out, used for the events CLI and SSE relay. Kept as a separate
   * method rather than overloading on() with an optional type — two
   * different call shapes on one method name is exactly the kind of
   * ambiguity this codebase's own "collision is a hard error" rule warns
   * against; two named methods, no ambiguity.
   */
  onAny(fn) {
    this._wildcards.push(fn);
    return () => {
      this._wildcards = this._wildcards.filter(f => f !== fn);
    };
  }

  registerAxiom(axiom) {
    this.axioms.push(axiom);
  }

  hook(kind, plugin) {
    if (!this._hooks[kind]) {
      throw new Error(`[warp/Stream] unknown hook kind: '${kind}'`);
    }
    if (typeof plugin !== 'function') {
      throw new Error(`[warp/Stream] hook '${kind}' plugin must be a function`);
    }
    this._hooks[kind].push(plugin);
  }

  hooks(kind) {
    return this._hooks[kind] ? [...this._hooks[kind]] : [];
  }

  /**
   * Run all hard axioms against a gate about to fire on an event.
   * Returns { ok: bool, failures: [{ axiomId, severity }] }.
   * Soft-axiom failures are recorded but never block.
   */
  _checkAxioms(event, gate) {
    const failures = [];
    for (const axiom of this.axioms) {
      let passed;
      try {
        passed = !!axiom.check(event, gate, this.sampleHere());
      } catch (e) {
        // §1.2-equivalent: an axiom that throws is a failure, not a pass.
        passed = false;
      }
      if (!passed) failures.push({ axiomId: axiom.id, severity: axiom.severity });
    }
    const hardFail = failures.some(f => f.severity === 'hard');
    return { ok: !hardFail, failures };
  }

  /**
   * emit(event) — synchronous when every gate.transform() on the path is
   * synchronous (byte-identical to the pre-2026-07-06 behavior: void
   * return, throws propagate synchronously, loom/schema/driver.js's
   * `stream.emit(event)` followed by its own redundant `gate.transform()`
   * call keeps working exactly as it does today). Returns a Promise only
   * when a transform on the path actually returned one — an async gate's
   * caller can `await stream.emit(event)` to know when it's really done;
   * a sync caller that never awaits anything sees no behavior change at
   * all, because until an async gate exists on the path, nothing here
   * ever returns a thenable.
   *
   * §WHY NOT BLANKET async emit() — checked a real, current consumer
   * first (loom/schema/driver.js): it calls stream.emit(event) unawaited
   * today and relies on errors propagating synchronously. A blanket
   * `async emit()` would silently convert that into an unhandled promise
   * rejection instead of a catchable throw — a real regression for the
   * one system already using this as its backbone, not a hypothetical.
   *
   * §COS MERGE 2026-07-11 — every emission now also: stamps into the ring
   * buffer, fires wildcard (onAny) observers, and broadcasts to any
   * subscribeSSE() clients. All three are additive side effects that run
   * regardless of axiom/gate outcome — matching cos's original behavior
   * where ring/wildcard/SSE saw every event unconditionally, not just
   * claimed ones.
   */
  emit(event) {
    this.eventCount++;
    const seq = ++this._seq;

    const stamped = {
      seq,
      type: event.type,
      payload: event.data,
      timestamp: Date.now(),
    };
    this._ring.push(stamped);
    if (this._ring.length > this._ringCap) this._ring.shift();
    for (const fn of this._wildcards) {
      try { fn(stamped); } catch (_) { /* an observer's error never breaks the stream */ }
    }
    this._broadcastSSE(stamped);

    for (const handler of this._observers.get(event.type) || []) {
      try { handler(event); } catch (_) { /* an observer's error never breaks the stream */ }
    }
    const gate = this.gates.get(event.type);

    if (!gate) {
      if (this.log) {
        this.log.record({
          streamId: this.streamId, parentStreamId: this.parentStreamId,
          eventType: event.type, gateClaimed: null, axiomResult: null,
        });
      }
      this.pending.push(event);
      return;
    }

    const axiomResult = this._checkAxioms(event, gate);

    if (this.log) {
      this.log.record({
        streamId: this.streamId, parentStreamId: this.parentStreamId,
        eventType: event.type, gateClaimed: gate.signature,
        axiomResult,
      });
    }

    if (!axiomResult.ok) {
      this.rejected.push({ event, gate: gate.signature, failures: axiomResult.failures });
      return;
    }

    // §COS MERGE — pass `this` (the stream) as a second argument. Every
    // current warp gate declares transform(event) and simply never reads
    // a second parameter — passing one is a no-op for them. Cos's gates
    // declare transform(event, stream) and use it to call stream.emit(...)
    // imperatively from inside their own transform body.
    const produced = gate.transform(event, this);

    // Thenable check, not `produced instanceof Promise` — a caller could
    // hand back any promise-shaped object (e.g. from a different realm/
    // library), duck-typing is the correct check here, same reasoning
    // Node's own util.types.isPromise-adjacent code uses.
    if (produced && typeof produced.then === 'function') {
      return produced.then(resolved => this._emitProduced(resolved));
    }
    return this._emitProduced(produced);
  }

  /**
   * _emitProduced — normalize void/single-Event/Event[] into an array and
   * recurse. Split out from emit() so both the sync and async branches
   * above share one implementation instead of two copies that could drift.
   * Recursion itself follows the same sync-unless-thenable rule: if any
   * downstream emit() call in the chain returns a Promise (because
   * something further down the graph is async), this correctly awaits it
   * before continuing — Promise.all over the recursive calls, so sibling
   * events at the same depth still process depth-first per-branch, same
   * ordering guarantee as the fully-synchronous version.
   */
  _emitProduced(produced) {
    const events = produced == null ? [] : (Array.isArray(produced) ? produced : [produced]);
    const results = events.map(next => this.emit(next));
    if (results.some(r => r && typeof r.then === 'function')) {
      return Promise.all(results);
    }
    // Every recursive call was synchronous — return nothing, exactly
    // like the original void contract.
  }

  sampleHere() {
    return {
      pending: [...this.pending],
      rejected: [...this.rejected],
      eventCount: this.eventCount,
      gateCount: this.gates.size,
      axiomCount: this.axioms.length,
    };
  }

  // ── §COS MERGE — ring buffer API ──────────────────────────────────────────
  /** Return last N stamped events from the ring buffer. */
  tail(n = 50) {
    return this._ring.slice(-n);
  }

  /** Return all stamped events since a given seq number. */
  since(afterSeq) {
    return this._ring.filter(e => e.seq > afterSeq);
  }

  get seq() { return this._seq; }

  // ── §COS MERGE — SSE API ──────────────────────────────────────────────────
  subscribeSSE(client) {
    this._sseClients.add(client);
    return () => this._sseClients.delete(client);
  }

  _broadcastSSE(stamped) {
    if (this._sseClients.size === 0) return;
    const data = `data: ${JSON.stringify(stamped)}\n\n`;
    for (const client of this._sseClients) {
      try { client.write(data); } catch (_) { this._sseClients.delete(client); }
    }
  }

  get sseClientCount() { return this._sseClients.size; }
}

module.exports = { Stream };

'use strict';
/**
 * Axiom — an enforced invariant, same standing as Gate.
 *
 * This is the primitive the SISO paper doesn't have. Its constraints
 * (immutability, purity, single-responsibility) are prose above the code —
 * nothing in Gate.transform() stops a violation. An Axiom does: it's a
 * predicate the Stream runs against every transform. A hard violation
 * rejects the transform outright — logged, never silently completed.
 */
// v1.4 — "axiom cost weighting." hard axioms weight 1.0, soft weight 0.3
// by default (spec's declared values). The weight is NOT used to skip
// hard axioms under any condition — that would contradict Axiom's own
// stated purpose ("a hard violation rejects the transform outright,
// logged, never swallowed") a few lines above. What weight actually
// gates, in dispatch/index.js's evaluation loop, is: (a) evaluation
// order — highest weight first, so a cheap hard-axiom short-circuit
// doesn't wait behind an expensive soft one — and (b) whether a SOFT
// axiom may be skipped when this exact digest already passed it before
// (skip_if_cache_verified). Hard axioms always run, every time, full
// stop.
const DEFAULT_WEIGHTS = { hard: 1.0, soft: 0.3 };

class Axiom {
  constructor(id, { check, severity = 'hard', version = '1.0.0', weight = null } = {}) {
    if (!id || typeof id !== 'string') {
      throw new Error('[warp/Axiom] id must be a non-empty string');
    }
    if (typeof check !== 'function') {
      throw new Error(`[warp/Axiom:${id}] check must be a function`);
    }
    if (severity !== 'hard' && severity !== 'soft') {
      throw new Error(`[warp/Axiom:${id}] severity must be 'hard' or 'soft'`);
    }
    this.id = id;
    this.check = check; // (event, gate, streamState) -> bool. true = passes.
    this.severity = severity;
    this.version = version; // NEW — changing check logic bumps this so
                             // cached results under the old rule invalidate
                             // instead of silently surviving a rule change.
    this.weight = weight !== null ? weight : DEFAULT_WEIGHTS[severity];
  }
}

module.exports = { Axiom, DEFAULT_WEIGHTS };

'use strict';
/**
 * Event — immutable data packet. { type, data, uuid, ts }.
 * Never mutated after creation. Matches SISO's Event shape exactly —
 * this primitive isn't where WARP differs from SISO.
 */
function _uid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

class Event {
  constructor(type, data = {}) {
    if (!type || typeof type !== 'string') {
      throw new Error('[warp/Event] type must be a non-empty string');
    }
    this.type = type;
    this.data = Object.freeze({ ...data });
    this.uuid = _uid();
    this.ts = Date.now();
    Object.freeze(this);
  }
}

module.exports = { Event };

'use strict';
const { Event } = require('./Event');
const { Gate } = require('./Gate');
const { Axiom } = require('./Axiom');
const { Stream } = require('./Stream');
const { StreamLog } = require('./StreamLog');
const { fuseChain, canFuse } = require('./GateFusion');

module.exports = { Event, Gate, Axiom, Stream, StreamLog, fuseChain, canFuse };

'use strict';
/**
 * GateFusion — v1.4 "gate fusion system." Merges an adjacent chain of
 * pure Gates into a single Gate, so Stream.emit()'s recursive dispatch
 * doesn't pay a Map lookup + axiom pass + log-record round trip per
 * intermediate hop for transforms that always fire together anyway.
 *
 * The spec's constraint was "no shared side effects." Gate.transform is
 * already documented core primitive as pure with zero side effects (see
 * core/Gate.js's own header) — so that constraint is Gate's existing
 * contract, not a new check this module invents or verifies. fuseChain
 * does NOT attempt to prove purity at runtime (there is no way to prove
 * that generically); it trusts the same contract every other part of
 * WARP already trusts every Gate to honor, and documents that trust
 * explicitly rather than pretending to enforce it.
 *
 * What IS enforced: adjacency. Gate B only fuses onto Gate A if A's
 * transform can actually produce an event of the type B matches — this
 * module runs each gate's `matches` against a synthetic probe event of
 * every declared handoff type to catch a wrong chain order early,
 * rather than silently fusing gates that were never really adjacent.
 */
const { Event } = require('./Event');
const { Gate } = require('./Gate');

/**
 * fuseChain(gates, fusedSignature) — gates: ordered array of Gate
 * instances, where gates[i]'s transform is expected to produce events
 * matched by gates[i+1]. Returns one Gate whose transform runs the whole
 * chain internally and returns only the final-stage output events (plus
 * any branch events that don't match the next stage, so nothing produced
 * along the way is silently dropped).
 */
function fuseChain(gates, fusedSignature) {
  if (!Array.isArray(gates) || gates.length < 2) {
    throw new Error('[warp/GateFusion] fuseChain requires at least 2 gates');
  }
  for (let i = 0; i < gates.length - 1; i++) {
    if (!(gates[i] instanceof Gate) || !(gates[i + 1] instanceof Gate)) {
      throw new Error('[warp/GateFusion] fuseChain requires Gate instances');
    }
  }

  const fused = new Gate(fusedSignature, {
    matches: (event) => gates[0].matches(event),
    transform: (event) => {
      let frontier = [event];
      const passthrough = [];

      for (let stage = 0; stage < gates.length; stage++) {
        const gate = gates[stage];
        const next = [];
        for (const e of frontier) {
          if (!gate.matches(e)) { passthrough.push(e); continue; }
          const produced = gate.transform(e);
          const events = produced == null ? [] : (Array.isArray(produced) ? produced : [produced]);
          next.push(...events);
        }
        frontier = next;
        if (frontier.length === 0) break;
      }

      return [...passthrough, ...frontier];
    },
  });

  fused.fusedFrom = gates.map(g => g.signature); // traceability — a fused gate still says what it's made of
  return fused;
}

/**
 * canFuse(gateA, gateB, sampleEventTypes) — best-effort adjacency check.
 * For each declared sample type, run gateA.matches on a probe Event, and
 * if it matches, confirm gateA.transform's contract lines up with
 * gateB.matches on at least one plausible output type. This is a
 * heuristic sanity check, not a proof — see module header.
 */
function canFuse(gateA, gateB, sampleEventTypes = []) {
  for (const type of sampleEventTypes) {
    const probe = new Event(type, {});
    if (gateA.matches(probe)) return true;
  }
  // No sample types supplied — fall back to signature-name convention
  // (best-effort only): can't prove adjacency, say so via null.
  return sampleEventTypes.length === 0 ? null : false;
}

module.exports = { fuseChain, canFuse };

'use strict';
/**
 * Gate — pure transform. matches(event) -> bool, transform(event) -> Event[].
 *
 * v1.0.1 change: transform now RETURNS the events it produces instead of
 * calling stream.emit() as a side effect. A gate can be tested completely
 * in isolation — assert on the returned array, no Stream object needed at
 * all. Stream (below) is the only thing that calls emit(). This is the
 * stricter reading of "pure function" the SISO paper claims but the
 * original imperative emit-as-side-effect shape didn't fully enforce.
 */
class Gate {
  constructor(signature, { matches, transform, schema = null } = {}) {
    if (!signature || typeof signature !== 'string') {
      throw new Error('[warp/Gate] signature must be a non-empty string');
    }
    if (typeof transform !== 'function') {
      throw new Error(`[warp/Gate:${signature}] transform must be a function`);
    }
    this.signature = signature;
    this._matches = matches || ((event) => event.type === signature);
    this._transform = transform;
    // v1.1.0: optional structured-output contract. Deliberately NOT a
    // full JSON-Schema implementation — that's an external dependency,
    // which breaks "zero dependencies." { requiredKeys: [...], types: {k: 'string'|'number'|...} }
    // is enough to validate shape without importing anything.
    this.schema = schema;
  }

  matches(event) {
    return this._matches(event);
  }

  transform(event) {
    return this._transform(event);
  }

  /**
   * validates output against this.schema if one was declared.
   * Returns { ok, missing: [], wrongType: [] }. No schema = always ok.
   */
  validateOutput(output) {
    if (!this.schema) return { ok: true, missing: [], wrongType: [] };
    const missing = [];
    const wrongType = [];
    const required = this.schema.requiredKeys || [];
    const types = this.schema.types || {};
    for (const key of required) {
      if (output == null || !(key in output)) { missing.push(key); continue; }
      const expected = types[key];
      if (expected && typeof output[key] !== expected) wrongType.push({ key, expected, actual: typeof output[key] });
    }
    return { ok: missing.length === 0 && wrongType.length === 0, missing, wrongType };
  }
}

module.exports = { Gate };

'use strict';
/**
 * scorer-default.js — five-axis fitness (coherence/friction/resonance/
 * entropy pattern + tokenEfficiency). Independently written — not
 * NEXUS's lib/cfr/field.js, a portable reimplementation of the idea.
 *
 * v1.1.0: tokenEfficiency added as an explicit axis, not an afterthought.
 * "Use as little tokens as possible" is now something the scorer actually
 * optimizes for, not just something a benchmark happens to measure later.
 * Fewer estimated tokens for equivalent shape-match = higher fitness.
 */
function estimateTokens(output) {
  const s = typeof output === 'string' ? output : JSON.stringify(output ?? '');
  return Math.ceil(s.length / 4); // ~4 chars/token, same rough estimate used in benchmarks
}

function scoreDefault({ axiomFailures = [], output, expectedShapeKeys = [], tokenBudget = null }) {
  const softFailures = axiomFailures.filter(f => f.severity === 'soft').length;
  const coherence = Math.max(0, 1 - softFailures * 0.15);

  let shapeMatch = 1;
  if (expectedShapeKeys.length > 0 && output && typeof output === 'object') {
    const present = expectedShapeKeys.filter(k => k in output).length;
    shapeMatch = present / expectedShapeKeys.length;
  }

  const tokens = estimateTokens(output);
  // No budget given -> neutral 0.5 rather than rewarding/punishing blind.
  // Budget given -> 1.0 at or under budget, decaying as tokens exceed it.
  const tokenEfficiency = tokenBudget
    ? Math.max(0, Math.min(1, tokenBudget / Math.max(tokens, 1)))
    : 0.5;

  const fitness = (coherence * 0.4) + (shapeMatch * 0.35) + (tokenEfficiency * 0.25);
  return Math.max(0, Math.min(1, fitness));
}

module.exports = { scoreDefault, estimateTokens };

'use strict';
/**
 * crystallizer-flatfile.js — default storage adapter for the exact-cache.
 * Trivial in-memory + optional flat-file persistence. A consuming project
 * swaps this for its own adapter (e.g. NEXUS's JAA) without core ever
 * changing — this file lives outside core/ specifically so it's optional.
 */
const fs = require('fs');

class FlatFileCrystallizer {
  constructor({ path = null } = {}) {
    this._path = path;
    this._store = new Map();
    if (path && fs.existsSync(path)) {
      try {
        const raw = JSON.parse(fs.readFileSync(path, 'utf8'));
        for (const [k, v] of Object.entries(raw)) this._store.set(k, v);
      } catch (_) { /* corrupt or empty — start fresh, never crash boot */ }
    }
  }

  get(digest) {
    return this._store.has(digest) ? this._store.get(digest) : null;
  }

  set(digest, value) {
    this._store.set(digest, value);
    if (this._path) {
      const obj = Object.fromEntries(this._store);
      fs.writeFileSync(this._path, JSON.stringify(obj, null, 2));
    }
  }

  /**
   * invalidate(digest) — rollback. A promoted crystal found wrong later
   * (an axiom bug that let something bad through, later fixed) needs a
   * way to be un-promoted. Without this, correctness could only ever
   * improve by luck of the axiom version bump orphaning the old digest —
   * the bad entry would sit in the store forever, unreachable but never
   * actually gone. This makes removal explicit and logged by the caller,
   * never silent.
   */
  invalidate(digest) {
    const existed = this._store.has(digest);
    this._store.delete(digest);
    if (existed && this._path) {
      const obj = Object.fromEntries(this._store);
      fs.writeFileSync(this._path, JSON.stringify(obj, null, 2));
    }
    return existed;
  }

  size() {
    return this._store.size;
  }
}

module.exports = { FlatFileCrystallizer };

