      <div class="brain-card-meta">
        ${(b.tags||[]).map(t=>`<span class="ic-tag">#${escapeHtml(t)}</span>`).join('')}
        <span class="brain-ts">${new Date(b.ts).toLocaleString()}</span>
      </div>
