check('idea.linkedSpec set', linkedIdea.linkedSpec === createdSpec.uuid);

console.log('\n── Stage 3: real .spec import (chunk-engine) ──');
const specText = fs.readFileSync(specPath, 'utf8');
const result = se.importSpec({ name: `e2e-${path.basename(specPath, '.spec')}`, specText });
check('import completed', result.manifest.status === 'complete', `${result.sectionsFilled.length} chunks`);
check('byte-fidelity verified', result.byteFidelity.verified, `${result.byteFidelity.sourceBytes}b`);

console.log('\n── Stage 4: structural profiling ──');
const manifest = se.loadSpec(result.manifest.uuid);
const anyChunkWithProfile = manifest.chunks.find(c => c.structuralProfile);
check('structuralProfile attached to chunks', !!anyChunkWithProfile);

console.log('\n── Stage 5: promote → repo ──');
const repoLayer = new RepoLayer({ ideaOS: os, specEngine: se });
const promoted = repoLayer.ingest({ name: manifest.name, specUuid: manifest.uuid, source: 'promote:emerge', promotedFromSpec: result.manifest.uuid });
check('promote succeeded', !promoted.error, promoted.error || promoted.repo.uuid);
const repoUuid = promoted.repo?.uuid;

console.log('\n── Stage 6: repo read-back (file CRUD) ──');
const repoView = repoLayer.get(repoUuid);
check('repo resolves via spec-engine', repoView && repoView.hasSpec, `${repoView?.fileCount} files`);
if (repoView && repoView.files.length) {
  const firstFile = repoView.files[0];
  const rf = repoLayer.readFile(repoUuid, firstFile.path);
  check('readFile works', !rf.error && rf.content.length > 0, firstFile.path);
  const wf = repoLayer.writeFile(repoUuid, firstFile.path, rf.content + '\n<!-- e2e touch -->');
  check('writeFile works (edit)', wf.ok, wf.path);
  const rootHashAfterEdit = repoLayer.get(repoUuid).rootHash;
  check('rootHash changed after edit', rootHashAfterEdit !== repoView.rootHash);
  repoLayer.writeFile(repoUuid, firstFile.path, rf.content); // revert, keep repeated runs clean

  console.log('\n── Stage 7: materialize to real files on disk ──');
  // §FIXED 2026-09-06 — same real isolation fix as elsewhere in this
  // session's pass: respects IDEARIUM_DATA_DIR when a caller (like
  // run-e2e-pipeline-isolated.cjs) sets it, so this scratch output lands
  // in a real, disposable temp dir during an isolated run instead of
  // always inside the real idearium/ tree.
  const outDir = process.env.IDEARIUM_DATA_DIR
    ? path.join(process.env.IDEARIUM_DATA_DIR, '.e2e-materialized-tmp')
    : path.join(IDEARIUM_ROOT, '.e2e-materialized-tmp');
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(outDir, { recursive: true });
  let written = 0;
  for (const f of repoLayer.get(repoUuid).files) {
    const r = repoLayer.readFile(repoUuid, f.path);
    if (r.error) continue;
    const dest = path.join(outDir, f.path);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, r.content, 'utf8');
    written++;
  }
  check('materialized all files', written === repoLayer.get(repoUuid).fileCount, `${written} files -> ${outDir}`);
}

console.log('\n── Stage 8: repo index persisted to cortex DB (not just in-memory) ──');
const repoLayer2 = new RepoLayer({ ideaOS: os, specEngine: se }); // fresh instance, forces reload
const reloaded = repoLayer2.get(repoUuid);
check('repo survives reload via cortex table', reloaded && reloaded.uuid === repoUuid);

console.log('\n── Stage 9: CLI reflects the same state ──');
const cliOut = execSync('node cli/index.js status', { cwd: IDEARIUM_ROOT }).toString();
check('CLI status runs clean', cliOut.includes('Idearium Status'));

console.log('\n' + '='.repeat(60));
if (FAIL.length === 0) {
  console.log('ALL 9 STAGES PASSED');
} else {
  console.log(`FAILED: ${FAIL.join(', ')}`);
  process.exitCode = 1;
}

/**
 * jaa-store.js — Guardian v8 Pure-JS Relational Store
 *
 * Zero native dependencies. Works on any platform, any Node version.
 * Jaa-inspired: tables-as-Maps, SISO-compliant, flat-file persistence.
 *
 * Persistence model:
 *   Each table → memory_store/<table>.json  (full snapshot on debounced write)
 *   On boot: load all tables from disk → rebuild in-memory Maps
 *
 * API (mirrors better-sqlite3 call shapes so server.js diff is minimal):
 *   store.run(table, op, row, where?)   → { changes, lastInsertRowid }
 *   store.get(table, where)             → row | null
 *   store.all(table, where, opts?)      → row[]
 *   store.insert(table, row)            → row
 *   store.upsert(table, row, keyField?) → row
 *   store.update(table, where, values)  → count
 *   store.delete(table, where)          → count
 *   store.count(table, where?)          → number
 *   store.exec(sql)                     → void  (ignored — compat shim)
 *   store.pragma(p)                     → void  (ignored — compat shim)
 *
 * Where clause: plain object { field: value, ... } — all fields must match (AND).
 * Opts: { orderBy, order: 'ASC'|'DESC', limit, offset }
 *
 * Settings table bootstrapped from schema defaults on first run.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Default settings (mirrors schema.sql INSERT OR IGNORE INTO settings) ──────

const DEFAULT_SETTINGS = {
  session_greeting_enabled: 'true',
  session_greeting_text:    'Guardian session initialising. Please ask me: "What are we calling this session?" — then wait for my answer before we begin.',
  scan_debounce_ms:         '1500',
  artifact_max:             '500',
  gap_min_score:            '0.25',
  gap_taxonomy_version:     '3.0.0',
  pa_enabled:               'true',
  memory_auto_push:         'true',
  dropzone_auto_upload:     'true',
  stream_log_level:         'EVENTS',
  lan_host:                 '0.0.0.0',
  greeting_delay_ms:        '1200',
  poll_interval_ms:         '500',
  stable_count_threshold:   '5',
};

// ── JaaStore ───────────────────────────────────────────────────────────────────

class JaaStore {
  /**
   * @param {string} dir  Directory for .json files (memory_store/)
   * @param {object} [opts]
   * @param {string} [opts.tablePrefix]  §MULTI-TENANT 2026-07-18 — when
   *   multiple systems share one directory (see cortex/memory/jaa-db.js and
   *   guardian/server.js both constructing a JaaStore), an unprefixed
   *   instance's _loadAll() would blindly load every .json file in the
   *   directory as its own table — including another system's same-named
   *   table ('settings' exists in both cortex's and guardian's table lists
   *   today; without this, pointing guardian at cortex's directory would
   *   silently merge two unrelated 'settings' tables). Prefix is applied
   *   only at the disk-file layer (_file/_loadAll) — every caller keeps
   *   using bare table names ('settings', not 'guardian_settings'); the
   *   in-memory Maps and every existing insert/query/update call site are
   *   untouched. Same pattern idearium/lib/db.js already uses at the
   *   application level, pushed down into the store itself so a second
   *   consumer doesn't have to reimplement it.
   */
  constructor(dir, opts = {}) {
    this.dir         = dir;
    this.tablePrefix = opts.tablePrefix || '';
    this._tables  = new Map();  // table name → Map<id, row>
    this._dirty   = new Set();  // tables needing flush
    this._timers  = new Map();  // table → setTimeout handle
    this._pendingDeletes = new Map(); // table → Set<id> deleted by this process since its last flush
    this._closed  = false;
    // §2026-07-24 — optional selective-load allowlist. See _loadAll(). Omitted
    // = load everything (unchanged behavior). Declared = preload only these;
    // anything else lazily loads on first access with a warning.
    this._only = Array.isArray(opts.tables) && opts.tables.length
      ? new Set(opts.tables) : null;
    // §2026-07-24 — the inverse: skip named tables at preload. For a SHARED
    // singleton store (cortex/memory/jaa-db.js serves every process) no fixed
    // allowlist could be correct for all of them, but an exclusion of known
    // heavy single-consumer tables is. Excluded tables still lazy-load on
    // first access via _table(), so the one real consumer is unaffected.
    this._skip = Array.isArray(opts.skipTables) && opts.skipTables.length
      ? new Set(opts.skipTables) : null;

    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    this._loadAll();
    this._bootstrapSettings();
    console.log('[jaa] Store ready —', dir, this.tablePrefix ? `(prefix: ${this.tablePrefix})` : '');
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  PUBLIC API
  // ══════════════════════════════════════════════════════════════════════════

  /** INSERT a row. row.id must exist (caller provides UUID). */
  insert(table, row) {
    const tbl = this._table(table);
    const id  = row.id || row.key || _uuid();
    const r   = { ...row, id };
    tbl.set(id, r);
    this._schedule(table);
    return r;
  }

  /** INSERT OR REPLACE — upserts by keyField (default 'id'). */
  upsert(table, row, keyField = 'id') {
    const tbl = this._table(table);
    const key = row[keyField];
    if (key) {
      // find existing by keyField value
      for (const [id, existing] of tbl) {
        if (existing[keyField] === key) {
          const updated = { ...existing, ...row, id };
          tbl.set(id, updated);
          this._schedule(table);
          return updated;
        }
      }
    }
    return this.insert(table, row);
  }

  /** SELECT one row matching where. */
  get(table, where = {}) {
    const tbl = this._table(table);
    for (const row of tbl.values()) {
      if (_matches(row, where)) return { ...row };
    }
    return null;
  }

  /** SELECT all rows matching where with optional orderBy/limit. */
  all(table, where = {}, opts = {}) {
    const tbl  = this._table(table);
    let   rows = [];
    for (const row of tbl.values()) {
      if (_matches(row, where)) rows.push({ ...row });
    }
    if (opts.orderBy) {
      const dir = (opts.order || 'ASC').toUpperCase() === 'DESC' ? -1 : 1;
      rows.sort((a, b) => {
        const va = a[opts.orderBy], vb = b[opts.orderBy];
        if (va == null && vb == null) return 0;
        if (va == null) return dir;
        if (vb == null) return -dir;
        return (va < vb ? -1 : va > vb ? 1 : 0) * dir;
      });
    }
    if (opts.offset) rows = rows.slice(opts.offset);
    if (opts.limit)  rows = rows.slice(0, opts.limit);
    return rows;
  }

  /**
   * query(table, where?, opts?) — alias of all(), identical semantics.
   *
   * §MCO17 2026-09-14 — a real contract bug, found by a test rather than by
   * reading. `all()` has always been this class's real read method, and
   * cortex/memory/jaa-db.js's wrapper exposes the same thing under the name
   * `query` — so `query` is the name used at essentially every real call site
   * in this codebase, and `all` is the name on the class those call sites
   * actually end up in.
   *
   * That divergence was harmless while the wrapper was the only way in. It
   * stopped being harmless when lib/node-index.js was generalized (2026-09-12)
   * to accept an injected store, with its own header instructing a per-system
   * caller to pass exactly this:
   *
   *     new (require('../guardian/jaa-store').JaaStore)(
   *       path.join(systemDir, 'data', 'node-index'))
   *
   * ...while node-index.js's own body calls `jaa.query(...)`. Following the
   * documented instruction throws `jaa.query is not a function`. Nothing had
   * ever followed it, so nothing had ever found out — §1.1, a path nobody has
   * walked is not a path that works.
   *
   * Fixed here rather than at the caller (§5.3 — no monkey patches): adapting
   * one consumer would leave the documented usage broken for the next one, and
   * the root cause is that this class is missing the name its own ecosystem
   * uses. An alias, not a rename: `all()` keeps working byte-for-byte, so every
   * existing call site is untouched (§5.14 — the contract widens, nothing
   * breaks).
   */
  query(table, where = {}, opts = {}) {
    return this.all(table, where, typeof opts === 'number' ? { limit: opts } : opts);
  }

  /** UPDATE rows matching where with values object. Returns changed count. */
  update(table, where, values) {
    const tbl = this._table(table);
    let   n   = 0;
    for (const [id, row] of tbl) {
      if (_matches(row, where)) {
        tbl.set(id, { ...row, ...values });
        n++;
      }
    }
    if (n > 0) this._schedule(table);
    return n;
  }

  /** DELETE rows matching where. Returns deleted count. */
  delete(table, where) {
    const tbl = this._table(table);
    let   n   = 0;
    for (const [id, row] of tbl) {
      if (_matches(row, where)) {
        tbl.delete(id);
        n++;
        // §MULTI-PROCESS FIX 2026-07-18 — remember what THIS process
        // deleted, so the pre-flush merge (see _flush) can reload fresh
        // disk state without resurrecting a row this process just
        // legitimately removed. See _flush's own comment for why the
        // reload has to happen this late in the first place.
        if (!this._pendingDeletes.has(table)) this._pendingDeletes.set(table, new Set());
        this._pendingDeletes.get(table).add(id);
      }
    }
    if (n > 0) this._schedule(table);
    return n;
  }

  /** COUNT rows matching where. */
  count(table, where = {}) {
    const tbl = this._table(table);
    if (!Object.keys(where).length) return tbl.size;
    let n = 0;
    for (const row of tbl.values()) if (_matches(row, where)) n++;
    return n;
  }

  // ── better-sqlite3 compat shims (so server.js dbRun/dbGet/dbAll still work) ─

  exec()   { /* schema DDL — no-op */ }
  pragma() { /* WAL/FK pragmas — no-op */ }

  // ── Settings helpers ──────────────────────────────────────────────────────────

  getSetting(key, fallback = null) {
    const row = this.get('settings', { key });
    return row ? row.value : fallback;
  }

  setSetting(key, value) {
    const ts  = Date.now();
    const row = this.get('settings', { key });
    if (row) {
      this.update('settings', { key }, { value: String(value), updated_ts: ts });
    } else {
      this.insert('settings', { id: _uuid(), key, value: String(value), updated_ts: ts });
    }
  }

  getAllSettings() {
    return this.all('settings').reduce((m, r) => { m[r.key] = r.value; return m; }, {});
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  FULL-TEXT SEARCH
  // ══════════════════════════════════════════════════════════════════════════

  /**
   * Search across artifacts, gaps, and ledger for query string.
   * Returns { artifacts[], gaps[], ledger[] }
   */
  search(q, limit = 50) {
    if (!q) return { artifacts: [], gaps: [], ledger: [] };
    const ql = q.toLowerCase();
    const match = (row, fields) => fields.some(f => (row[f] || '').toLowerCase().includes(ql));
    return {
      artifacts: this.all('artifacts')
        .filter(r => match(r, ['name', 'content', 'lang', 'account', 'chat_id']))
        .slice(0, limit),
      gaps: this.all('gaps')
        .filter(r => match(r, ['description', 'type', 'domain']))
        .slice(0, limit),
      ledger: this.all('ledger_entries')
        .filter(r => match(r, ['msg', 'category']))
        .slice(0, limit),
    };
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  STATS
  // ══════════════════════════════════════════════════════════════════════════

  stats() {
    return {
      artifacts:   this.count('artifacts'),
      gaps:        this.count('gaps'),
      ledger:      this.count('ledger_entries'),
      sessions:    this.count('sessions'),
      jobs:        this.count('jobs'),
      downloads:   this.count('downloads'),
      pa_sessions: this.count('pa_sessions'),
      settings:    this.count('settings'),
      dbFile:      path.join(this.dir, '*.json'),
      dbExists:    true,
    };
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  PERSISTENCE
  // ══════════════════════════════════════════════════════════════════════════

  /** Force flush all dirty tables to disk. */
  flushAll() {
    for (const table of this._dirty) this._flush(table);
  }

  /** Graceful shutdown — flush all and stop timers. */
  close() {
    this._closed = true;
    for (const [, timer] of this._timers) clearTimeout(timer);
    this.flushAll();
    console.log('[jaa] Store closed — all tables flushed.');
  }

  // ══════════════════════════════════════════════════════════════════════════
  //  PRIVATE
  // ══════════════════════════════════════════════════════════════════════════

  _table(name) {
    if (!this._tables.has(name)) {
      // §FIX 2026-07-24 — SAFETY for the `tables` allowlist. Previously this
      // created an empty Map for any unknown table, which is correct when the
      // table genuinely doesn't exist yet. But with a selective-load allowlist,
      // a process that under-declares would read a table that EXISTS ON DISK as
      // empty — silently losing data, the worst failure class in this codebase
      // (§1.2: fail loudly, never silently). So: if we skipped this table at
      // load time and a file for it exists, load it now, on first access.
      // Worst case is a slower first read; never a wrong answer.
      if ((this._only && !this._only.has(name)) || (this._skip && this._skip.has(name))) {
        try {
          if (fs.existsSync(this._file(name))) {
            // Warn ONCE per table, not per access. Without this guard the
            // message fires on every _table() call — thousands of lines in a
            // single run, which would drown the boot log it's meant to inform.
            if (!this._warnedTables) this._warnedTables = new Set();
            if (!this._warnedTables.has(name)) {
              this._warnedTables.add(name);
              console.warn(`[jaa] '${name}' was not in this store's declared tables — loading on demand. Add it to the tables list to preload.`);
            }
            // §FIX 2026-07-24b — create the slot BEFORE loading. _loadTable()
            // calls this._table(name) internally to get the Map to populate;
            // without this line that call re-enters this same lazy-load branch
            // (map still doesn't exist, skip-list still matches) and recurses
            // forever, re-reading and re-parsing the whole file at every level
            // since none of the stack frames ever return — that's the exact
            // heap-OOM idearium hit on first access to a skip-listed table.
            // Pre-setting an empty Map here means _loadTable's this._table()
            // call hits the has(name) branch and returns immediately instead.
            this._tables.set(name, new Map());
            this._loadTable(name);
          }
        } catch (_) { /* fall through to empty map */ }
      }
      if (!this._tables.has(name)) this._tables.set(name, new Map());
    }
    return this._tables.get(name);
  }

  _file(table) {
    return path.join(this.dir, `${this.tablePrefix}${table}.json`);
  }

  _loadAll() {
    // Load any existing JSON files in the store dir that belong to THIS
    // instance's namespace. Unprefixed instances (tablePrefix='') keep
    // exactly the old behavior — every .json file in the dir is theirs,
    // same as before this change. Prefixed instances only ever see their
    // own files; a shared directory's other tenants are invisible to them.
    //
    // §FIX 2026-07-24 — MEASURED memory finding, not a theory: the store is
    // 14MB on disk and NINE processes each load all of it (cortex, guardian,
    // orchestrator, loom, copilot, diagnostic, idearium, healer, agents).
    // Parsed to JS objects that is roughly 400-600MB of RAM holding nine
    // copies of the same tables — the driver behind the recurring
    // "free memory < 20%" pressure, the 0xC0000409 crashes, and the
    // ERR_NO_BUFFER_SPACE socket exhaustion in the 2026-07-24 log.
    // 77% of it is two tables (idearium_spec_chunks 5.4MB +
    // idearium_spec_manifests 5.4MB) that ONLY idearium reads — verified by
    // grep: idearium/spec-engine/index.js and idearium/lib/cortex-listeners.js
    // are the sole consumers. Eight processes hold 10.8MB each of data they
    // never touch.
    //
    // `tables` is an OPT-IN allowlist. Omitted → every table loads, exactly
    // as before, so no existing caller changes behavior (§5.14 — same
    // contract, replaceable implementation). A process that declares its
    // tables loads only those; anything it later asks for still works,
    // because _table() lazily loads on first access (see below).
    let files;
    try { files = fs.readdirSync(this.dir); }
    catch (_) { return; }
    for (const f of files) {
      if (!f.endsWith('.json')) continue;
      const stem = f.slice(0, -5);
      if (this.tablePrefix) {
        if (!stem.startsWith(this.tablePrefix)) continue;
        const name = stem.slice(this.tablePrefix.length);
        if (this._only && !this._only.has(name)) continue;
        if (this._skip && this._skip.has(name)) continue;
        this._loadTable(name);
      } else {
        if (this._only && !this._only.has(stem)) continue;
        if (this._skip && this._skip.has(stem)) continue;
        this._loadTable(stem);
      }
    }
  }

  /**
   * reloadTable(name) — force-refresh this table's in-memory Map from
   * whatever is currently on disk, merging in any rows written by another
   * process since this instance last read them.
   *
   * §BUG FOUND AND FIXED 2026-07-18 — this file's own header claims
   * "single writer, multiple readers, zero duplication," but that was
   * never actually enforced: nothing stops two processes (idearium's own
   * API server and a concurrent CLI invocation both call getIdeaOS(),
   * each opening its own JaaStore pointed at the same directory) from
   * both holding this table open. Proven, not theorized: reproduced
   * directly — two processes each wrote 2 real rows to the same table,
   * final state had only 2 of the 4, the other process's writes were
   * silently destroyed by a plain overwrite that never saw them. The
   * root cause: query()/all() always read the in-process Map, populated
   * once at construction and never refreshed — a caller diffing "current
   * vs new" before a sync-style write was diffing against data that was
   * already stale the moment a second process existed. This method is
   * the fix's other half — callers doing a read-diff-write cycle (see
   * idearium/lib/db.js's syncTable) call this immediately before reading,
   * so the diff is against real current disk state, not a memory of what
   * disk looked like at boot.
   *
   * Known remaining limitation, not silently papered over: this ADDS/
   * UPDATES from disk into memory, it does not remove rows that exist in
   * memory but were deleted from disk by another process — _loadTable's
   * own behavior, inherited here deliberately rather than reimplemented,
   * since idearium's own rows are essentially never hard-deleted (§M1 —
   * archived in place, not removed). A consumer relying on real deletes
   * propagating correctly across processes would need more than this.
   */
  reloadTable(name) {
    this._loadTable(name);
  }

  _loadTable(name) {
    const file = this._file(name);
    if (!fs.existsSync(file)) return;
    try {
      const rows = JSON.parse(fs.readFileSync(file, 'utf8'));
      const tbl  = this._table(name);
      if (Array.isArray(rows)) {
        for (const row of rows) {
          const id = row.id || row.key || _uuid();
          tbl.set(id, { ...row, id });
        }
        console.log(`[jaa] Loaded ${tbl.size} rows — ${name}`);
      }
    } catch (e) {
      console.error(`[jaa] Load error (${name}): ${e.message}`);
    }
  }

  _schedule(table, delay = 1500) {
    this._dirty.add(table);
    if (this._timers.has(table)) clearTimeout(this._timers.get(table));
    this._timers.set(table, setTimeout(() => {
      this._flush(table);
      this._timers.delete(table);
    }, delay));
  }

  _flush(table) {
    if (!this._dirty.has(table)) return;
    this._dirty.delete(table);
    const tbl  = this._tables.get(table);
    if (!tbl) return;

    // §MP-001 ROOT-CAUSE FIX 2026-07-24 — cross-process lock around the
    // whole read-merge-write cycle. Third occurrence of this bug class
    // (first closed 2026-07-15 with atomic rename, second 2026-07-18 with
    // the pre-flush merge below) — §17.7 says the third occurrence
    // promotes to architecture, and the 2026-07-18 comment below already
    // named the missing primitive itself: "not eliminated by anything
    // short of true cross-process locking." This is that primitive.
    //
    // PROVEN, not theorized, before building: deterministic reproduction
    // (frozen interleaving: B reads disk → A's entire flush lands → B
    // writes) destroys A's WHOLE BATCH, not just same-id collisions — the
    // old comment's "only way to lose a row is two writes to the SAME id
    // in the same few-millisecond window" claim was wrong, and matches
    // the whole-batch loss the (previously orphaned) MP-001 test showed
    // intermittently.
    //
    // Mechanism: O_EXCL lock file per table. 'wx' open is atomic at the
    // OS level (fails if the file exists) — the standard zero-dependency
    // cross-process mutex on every platform including Windows. Holder
    // writes its pid; a lock older than LOCK_STALE_MS is presumed
    // abandoned (holder crashed mid-flush) and broken loudly, not
    // silently. If the lock can't be acquired within LOCK_WAIT_MS, we
    // re-schedule this flush rather than proceeding unlocked — a delayed
    // write is recoverable, a clobbered one is not (§16.3: an invalid
    // state is refused, not passed through). Data stays safe in this
    // process's in-memory map + _dirty flag the entire time.
    //
    // §BUGFIX 2026-08-24 — _acquireFlushLock() now returns the real,
    // specific string 'gone' (not just falsy) when the lock file's own
    // parent directory is permanently missing — distinct from ordinary
    // lock contention (another process mid-flush), which is genuinely
    // transient and worth retrying. Without this distinction, a
    // permanently deleted directory (a test's own torn-down temp dir,
    // with a flush still pending) caused a real, confirmed-live infinite
    // retry loop — every 250ms, forever, since the directory never
    // comes back — which kept the whole Node process alive indefinitely.
    const lockResult = this._acquireFlushLock(table);
    if (lockResult === 'gone') {
      this._dirty.delete(table); // §1.2 — honest: the storage location is gone, there is nowhere left to write this to; not silently pretending it was saved
      return;
    }
    if (!lockResult) {
      this._dirty.add(table);        // keep it flagged
      this._schedule(table, 250);    // retry soon — lock holder's flush is ms-scale
      return;
    }

    try {
      const deletedByMe = this._pendingDeletes.get(table);
      try {
        const file = this._file(table);
        if (fs.existsSync(file)) {
          const onDisk = JSON.parse(fs.readFileSync(file, 'utf8'));
          if (Array.isArray(onDisk)) {
            for (const row of onDisk) {
              const id = row.id || row.key;
              if (id == null) continue;
              if (deletedByMe && deletedByMe.has(id)) continue; // respect this process's own pending delete
              if (!tbl.has(id)) tbl.set(id, { ...row, id }); // only fill in what THIS process doesn't already know about — do not clobber an in-flight local edit with an older on-disk copy
            }
          }
        }
      } catch (e) {
        console.error(`[jaa] pre-flush merge error (${table}): ${e.message} — flushing this process's own view only`);
      }
      this._pendingDeletes.delete(table);

      const rows = [...tbl.values()];
      const file = this._file(table);
      // §MULTI-PROCESS FIX 2026-07-15 — write to a temp file then rename over
      // the target, instead of writeFileSync-ing the target directly. A rename
      // is atomic at the filesystem level where an in-place write is not — a
      // second process reading this file mid-write can never observe a
      // truncated/corrupt partial JSON.
      //
      // §UPDATE 2026-07-18 — pre-flush merge added (above).
      // §UPDATE 2026-07-24 — the residual race that comment left open
      // ("two processes flushing the same table at the same instant both
      // merge against the same pre-write disk state") is now closed by the
      // flush lock wrapping this whole section: read-merge-write is a
      // critical section, exactly one process at a time.
      const tmpFile = `${file}.${process.pid}.${Date.now()}.tmp`;
      try {
        fs.writeFileSync(tmpFile, JSON.stringify(rows, null, 0), 'utf8');
        fs.renameSync(tmpFile, file);
      } catch (e) {
        console.error(`[jaa] Flush error (${table}): ${e.message}`);
        try { fs.unlinkSync(tmpFile); } catch (_) {} // best-effort cleanup, don't mask the real error
      }
    } finally {
      this._releaseFlushLock(table);
    }
  }

  // ── §MP-001 cross-process flush lock ────────────────────────────────────────
  // O_EXCL ('wx') create is the atomic primitive; everything else is policy:
  //   - spin briefly (LOCK_WAIT_MS) — flushes are milliseconds, contention rare
  //   - a stale lock (holder crashed mid-flush) is broken LOUDLY after
  //     LOCK_STALE_MS, never silently (§1.2)
  //   - failure to acquire → caller re-schedules; never proceeds unlocked

  _lockFile(table) { return this._file(table) + '.lock'; }

  _acquireFlushLock(table) {
    const LOCK_WAIT_MS  = 200;   // total time to spin before giving up this attempt
    const LOCK_STALE_MS = 10000; // a flush takes ms — 10s means the holder died
    const lockPath = this._lockFile(table);
    const deadline = Date.now() + LOCK_WAIT_MS;

    for (;;) {
      try {
        const fd = fs.openSync(lockPath, 'wx'); // atomic create-or-fail
        fs.writeSync(fd, String(process.pid));
        fs.closeSync(fd);
        return true;
      } catch (e) {
        if (e.code !== 'EEXIST') {
          // §BUGFIX 2026-08-24 — found while running the full real test
          // suite: this branch treated EVERY non-EEXIST error as
          // "transient, retry soon," including ENOENT from the lock
          // file's own PARENT DIRECTORY being gone (a test's temp dir,
          // torn down after the test finished, with a flush still
          // pending on a debounce timer). That's not transient — it's
          // permanent. The caller (_flush(), above) used to reschedule
          // on ANY falsy return, creating a real, genuine infinite
          // retry loop: every 250ms, forever, since the directory never
          // comes back. Confirmed live — 216+ identical errors in under
          // 15s, and the Node process never exited on its own (a real,
          // live-leaked process, not just noisy logs). Real fix: return
          // the distinct string 'gone' so the caller can tell "give up,
          // permanently" from "retry soon, this is normal contention."
          // §1.2 still applies — loud, not silent — but "loud once,
          // then give up" is the honest response to a permanently gone
          // directory; "loud forever" is not.
          console.error(`[jaa] flush-lock error (${table}): ${e.code} ${e.message}`);
          if (e.code === 'ENOENT' && !fs.existsSync(path.dirname(lockPath))) {
            console.error(`[jaa] flush-lock (${table}): parent directory is gone — this is permanent, not transient. Dropping this flush rather than retrying forever.`);
            return 'gone';
          }
          return false;
        }
        // Lock held. Stale?
        try {
          const st = fs.statSync(lockPath);
          if (Date.now() - st.mtimeMs > LOCK_STALE_MS) {
            const holder = (() => { try { return fs.readFileSync(lockPath, 'utf8'); } catch (_) { return '?'; } })();
            console.error(`[jaa] BREAKING STALE FLUSH LOCK (${table}) — held by pid ${holder} for >${LOCK_STALE_MS}ms, presumed crashed mid-flush. (§1.2 — loud, never silent.)`);
            try { fs.unlinkSync(lockPath); } catch (_) {}
            continue; // retry the atomic create immediately
          }
        } catch (_) { /* lock vanished between EEXIST and stat — retry */ continue; }

        if (Date.now() >= deadline) return false;
        // Synchronous ms-scale busy-wait, deliberately: _flush is already a
        // synchronous fs function on a debounce timer, its callers hold no
        // locks of their own, and the expected hold time is single-digit ms.
        const until = Date.now() + 5;
        while (Date.now() < until) { /* spin 5ms */ }
      }
    }
  }

  _releaseFlushLock(table) {
    try { fs.unlinkSync(this._lockFile(table)); }
    catch (e) {
      // ENOENT here means someone broke our lock as stale mid-flush (we
      // held it >10s — shouldn't happen, worth hearing about). Anything
      // else is a real FS problem. Either way: loud, not swallowed.
      if (e.code !== 'ENOENT') console.error(`[jaa] flush-lock release error (${table}): ${e.code} ${e.message}`);
      else console.error(`[jaa] flush lock (${table}) was already gone at release — a peer broke it as stale; this process's flush exceeded the ${10000}ms stale threshold`);
    }
  }

  _bootstrapSettings() {
    const tbl = this._table('settings');
    for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
      let exists = false;
      for (const row of tbl.values()) { if (row.key === key) { exists = true; break; } }
      if (!exists) {
        this.insert('settings', { id: _uuid(), key, value, updated_ts: Date.now() });
      }
    }
  }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function _matches(row, where) {
  // §the systemic fix — `where` arrives as a predicate function at the
  // overwhelming majority of real call sites across this codebase
  // (raid/snr-filter.js, cortex/intelligence, lib/replay-engine.js,
  // lib/constitutional-ai.js, orchestrator/request-handler.js, and others).
  // Object.entries() on a function returns [], so the loop below never ran
  // and every one of those calls silently matched every row in the table,
  // ignoring the predicate entirely — reproduced directly: querying `gaps`
  // for a type that doesn't exist anywhere still returned rows. Object-shape
  // where clauses (the other real convention — fault-taxonomy.js, fix-map.js)
  // are unaffected by this branch.
  if (typeof where === 'function') return !!where(row);
  // Third sibling, same family, also reproduced before fixing: update(table,
  // someUuidString, values) — the convention copilot/lib/user-model.js and
  // orchestrator/lib/spec-drift.js both use. Object.entries() on a string
  // yields indexed characters ([['0','m'],...]), so it matched nothing and
  // every such update was a silent no-op. A string where matches by id or uuid.
  if (typeof where === 'string') return row.id === where || row.uuid === where;
  for (const [k, v] of Object.entries(where)) {
    if (v === null || v === undefined) {
      if (row[k] != null) return false;
    } else if (row[k] !== v) {
      return false;
    }
  }
  return true;
}

let _uuidCounter = 0;
function _uuid() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  const t = Date.now().toString(16);
  const r = Math.random().toString(16).slice(2);
  const c = (++_uuidCounter).toString(16).padStart(4, '0');
  return `${t.slice(0,8)}-${t.slice(8,12)}-4${r.slice(0,3)}-${(8+Math.random()*4|0).toString(16)}${r.slice(4,7)}-${r.slice(7,19)}${c}`;
}

module.exports = { JaaStore };

// ==UserScript==
// @name         NEXUS — Cortex Memory Observer v1.0
// @namespace    nexus.cortex.memory
// @version      1.0.0
// @description  Passive conversation observer. Watches all AI chats and routes
//               conversation turns directly into cortex working/short-term memory.
//               Separate from Guardian — does not inject, does not claim tabs.
//               Runs on all claude.ai and chatgpt.com tabs simultaneously.
//               Extracts ?REMEMBER: signals for long-term crystal candidates.
// @author       James Brooks / Nexus
// @match        https://claude.ai/*
// @match        https://chatgpt.com/*
// @match        https://chat.openai.com/*
// @grant        GM_xmlhttpRequest
// @connect      127.0.0.1
// @run-at       document-idle
// ==/UserScript==

(function () {
'use strict';

// ── Constants ─────────────────────────────────────────────────────────────────
const CORTEX_URL  = 'http://127.0.0.1:3748';
const VERSION     = '1.0.0';
const PROVIDER    = location.hostname.includes('claude') ? 'claude' : 'chatgpt';

// Scan interval — observe DOM every 2s for new turns
const SCAN_MS     = 2000;
// Flush working memory to cortex every 30s
const FLUSH_MS    = 30 * 1000;
// Heartbeat to prove we're alive
const HB_MS       = 60 * 1000;

// ── Session identity ──────────────────────────────────────────────────────────
function chatId() {
  const m = location.pathname.match(/\/chat\/([a-zA-Z0-9_-]+)/);
  return m ? m[1] : 'home';
}
function sessionId() {
  // Stable session key: hostname + chatId
  return `${PROVIDER}:${chatId()}`;
}

// ── Turn tracking ─────────────────────────────────────────────────────────────
// We track which turn content we've already seen by a simple hash.
// Only write a turn once per conversation — don't re-fire on re-scans.
const _seenHashes = new Set();
let   _turnIndex  = 0;
let   _pendingFlush = []; // turns buffered before flush to cortex

function simpleHash(s) {
  let h = 0;
  for (let i = 0; i < Math.min(s.length, 500); i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(16).slice(0, 10);
}

// ── DOM selectors per provider ────────────────────────────────────────────────
const SELECTORS = PROVIDER === 'claude' ? {
  userTurns:      '[data-testid="human-message"]',
  assistantTurns: '[data-testid="assistant-message"]',
} : {
  userTurns:      '[data-message-author-role="user"]',
  assistantTurns: '[data-message-author-role="assistant"]',
};

// ── Cortex write ─────────────────────────────────────────────────────────────
function _toCortex(type, payload) {
  try {
    fetch(`${CORTEX_URL}/api/event`, {
      method:    'POST',
      headers:   { 'Content-Type': 'application/json' },
      keepalive: true,
      body: JSON.stringify({
        type,
        payload: { ...payload, _provider: PROVIDER, _chatUrl: location.href },
        source:  'userscript-memory',
        causedBy: payload.jobId || null,
        ts:       Date.now(),
      }),
    }).catch(() => {});
  } catch (_) {}
}

// ── Signal extraction — ?REMEMBER:, ?FLAG:, code blocks ──────────────────────
// Scans a completed assistant response for lines that should persist
// beyond the working memory decay window.
function extractSignals(text, sid) {
  const signals = [];

  // ?REMEMBER: <content> — explicit long-term signal from the AI
  const rememberLines = text.split('\n').filter(l => /^\?REMEMBER:/i.test(l.trim()));
  for (const l of rememberLines) {
    const content = l.replace(/^\?REMEMBER:/i, '').trim();
    if (content.length > 3) {
      signals.push({ kind: 'remember', content, sessionId: sid });
    }
  }

  // ?FLAG: <content> — explicit flag for human review
  const flagLines = text.split('\n').filter(l => /^\?FLAG:/i.test(l.trim()));
  for (const l of flagLines) {
    const content = l.replace(/^\?FLAG:/i, '').trim();
    if (content.length > 3) {
      signals.push({ kind: 'flag', content, sessionId: sid });
    }
  }

  // Code blocks — note language and first line as a signal
  const codeMatches = [...text.matchAll(/```(\w+)?\n([^\n]+)/g)];
  for (const m of codeMatches.slice(0, 3)) {
    const lang    = m[1] || 'unknown';
    const preview = (m[2] || '').trim().slice(0, 80);
    if (preview.length > 10) {
      signals.push({ kind: 'code', content: `${lang}: ${preview}`, sessionId: sid });
    }
  }

  return signals;
}

// ── Scan DOM for new conversation turns ───────────────────────────────────────
function scanTurns() {
  const sid = sessionId();

  // User turns
  const userEls = document.querySelectorAll(SELECTORS.userTurns);
  for (const el of userEls) {
    const text = (el.innerText || el.textContent || '').trim();
    if (!text || text.length < 2) continue;
    const h = simpleHash(text);
    if (_seenHashes.has(h)) continue;
    _seenHashes.add(h);

    const turn = {
      sessionId: sid,
      role:      'user',
      content:   text.slice(0, 8000),
      provider:  PROVIDER,
      chatUrl:   location.href,
      turnIndex: _turnIndex++,
      ts:        Date.now(),
    };
    _pendingFlush.push({ type: 'turn', ...turn });
  }

  // Assistant turns — only capture stable ones (not mid-stream)
  const assistantEls = document.querySelectorAll(SELECTORS.assistantTurns);
  for (const el of assistantEls) {
    const text = (el.innerText || el.textContent || '').trim();
    if (!text || text.length < 10) continue;
    const h = simpleHash(text);
    if (_seenHashes.has(h)) continue;

    // Stability check — don't capture while streaming
    // A turn is stable if it hasn't changed in the last 1.5s
    if (!el._stableTs) {
      el._lastText = text;
      el._stableTs = 0;
      setTimeout(() => {
        const current = (el.innerText || el.textContent || '').trim();
        if (current === el._lastText) {
          el._stableTs = Date.now();
        } else {
          el._stableTs = 0;
        }
      }, 1500);
      continue;
    }
    if (el._stableTs === 0) continue; // still changing

    _seenHashes.add(h);

    const turn = {
      sessionId: sid,
      role:      'assistant',
      content:   text.slice(0, 8000),
      provider:  PROVIDER,
      chatUrl:   location.href,
      turnIndex: _turnIndex++,
      ts:        el._stableTs || Date.now(),
    };
    _pendingFlush.push({ type: 'turn', ...turn });

    // Extract signals from this assistant turn
    const signals = extractSignals(text, sid);
    for (const sig of signals) {
      _pendingFlush.push({ type: 'signal', ...sig });
    }
  }
}

// ── Flush pending turns to cortex ─────────────────────────────────────────────
// Batches all pending turns into individual cortex events.
// Working memory turns use type 'working.memory.turn'.
// Signals use type 'working.memory.signal'.
// Both route to working_memory table via the WELL_KNOWN router.
function flush() {
  if (!_pendingFlush.length) return;

  const batch = _pendingFlush.splice(0, _pendingFlush.length);

  for (const entry of batch) {
    if (entry.type === 'turn') {
      _toCortex('working.memory.turn', entry);
    } else if (entry.type === 'signal') {
      _toCortex('working.memory.signal', entry);
      // Also push ?REMEMBER: signals as crystal candidates to long-term memory
      if (entry.kind === 'remember') {
        _toCortex('cortex.crystal.candidate', {
          sessionId: entry.sessionId,
          content:   entry.content,
          source:    'userscript-remember-protocol',
          provider:  PROVIDER,
        });
      }
    }
  }
}

// ── Navigation tracking ───────────────────────────────────────────────────────
let _lastChatId = chatId();

function checkNavigation() {
  const current = chatId();
  if (current !== _lastChatId) {
    // Chat changed — flush pending from old session, reset turn index
    flush();
    _lastChatId  = current;
    _turnIndex   = 0;
    // Don't clear _seenHashes — prevent re-ingesting turns if returning to same chat
    console.log(`[nexus-memory] navigated to ${current}`);
  }
}

// ── Session context write ─────────────────────────────────────────────────────
// Periodically write a context snapshot so cortex knows the current session state.
function writeContextSnapshot() {
  _toCortex('working.memory.context', {
    sessionId:   sessionId(),
    provider:    PROVIDER,
    chatUrl:     location.href,
    turnsSeen:   _turnIndex,
    pendingFlush: _pendingFlush.length,
    ts:          Date.now(),
  });
}

// ── Heartbeat ─────────────────────────────────────────────────────────────────
function heartbeat() {
  _toCortex('memory.observer.heartbeat', {
    provider: PROVIDER,
    sessionId: sessionId(),
    turnsSeen: _turnIndex,
    version:   VERSION,
  });
}

// ── Init ──────────────────────────────────────────────────────────────────────
function init() {
  // Observe DOM for new turns
  setInterval(scanTurns, SCAN_MS);
  // Flush to cortex
  setInterval(flush, FLUSH_MS);
  // Navigation
  setInterval(checkNavigation, 800);
  // Context snapshot
  setInterval(writeContextSnapshot, 5 * 60 * 1000);
  // Heartbeat
  setInterval(heartbeat, HB_MS);

  // MutationObserver for faster capture on active chats
  const target = document.querySelector('main') || document.body;
  if (target) {
    let debounceTimer = null;
    const obs = new MutationObserver(() => {
      if (debounceTimer) clearTimeout(debounceTimer);
      debounceTimer = setTimeout(scanTurns, 800);
    });
    obs.observe(target, { childList: true, subtree: true, characterData: true });
  }

  // Initial scan
  setTimeout(scanTurns, 1500);

  console.log(`[nexus-memory v${VERSION}] observer started on ${PROVIDER} — session: ${sessionId()}`);
  _toCortex('memory.observer.started', { provider: PROVIDER, sessionId: sessionId(), version: VERSION });
}

// Boot after DOM is ready
if (document.readyState === 'complete') {
  setTimeout(init, 1000);
} else {
  window.addEventListener('load', () => setTimeout(init, 1000));
}

})();

'use strict';
/**
 * lib/contract-handshake.js — Interaction Contract Verification Layer
 * UUID: nexus-contract-hs-v1-0000-4000-0000-000000000001
 * Status: pre-release
 *
 * When a system boots and registers with the orchestrator, the orchestrator
 * fetches that system's /api/contract endpoint and verifies:
 *
 *   1. The contract has the expected system id
 *   2. All declared routes are actually reachable (health check)
 *   3. The schema hash matches what the orchestrator has on file
 *      (or records it as the new canonical if first time)
 *
 * This turns the interaction contract from documentation into a live
 * enforcement mechanism. A system that doesn't publish a valid contract
 * cannot be trusted by the orchestrator — it's registered but flagged
 * as UNVERIFIED and proxied with a warning header.
 *
 * Trust states:
 *   UNVERIFIED  — registered but contract not yet checked
 *   VERIFIED    — contract fetched, schema matches, routes reachable
 *   DEGRADED    — contract fetched but some routes unreachable
 *   MISMATCH    — contract schema differs from on-file (breaking change)
 *   UNREACHABLE — /api/contract returned non-200
 *
 * §1.1  Nothing is trusted until proven
 * §1.2  Every verification failure is logged to event_log with reason
 * §5.2  Contract IS the bridge — every system implements it
 */

const http   = require('http');
const crypto = require('crypto');

const MODULE_ID = 'contract-handshake';

// In-memory trust registry — survives within a process lifetime
// Persisted to JAA event_log on every state change
const _registry = new Map(); // systemId → ContractEntry

const TRUST = {
  UNVERIFIED:  'UNVERIFIED',
  VERIFIED:    'VERIFIED',
  DEGRADED:    'DEGRADED',
  MISMATCH:    'MISMATCH',
  UNREACHABLE: 'UNREACHABLE',
};

// ── Per-system contract paths ─────────────────────────────────────────────────
// Each system serves its interaction contract at a different path.
// This is the canonical mapping. §A-4: append-only, never remove.
const CONTRACT_PATHS = {
  cortex:       '/contract',
  guardian:     '/contract',
  idearium:     '/api/contract',
  bridge:       '/bridge/contract',
  architect:    '/api/contract',
  emerge:       '/api/contract',
  orchestrator: '/api/contract',
  diagnostic:   '/health',
  // Sovereign systems added 2026-06-27
  eravos:         '/contract',
  ollama:         '/contract',
  copilot:        '/contract',
  'clear-glass':  '/contract',
  'nexus-wire':   '/contract',
  // §BUGFIX 2026-07-04: loom added as a sovereign system this session
  // (loom/server.js, :3752) with a real GET /contract route, matching this
  // same bare-path convention — but never added here, so every poll fell
  // through to the '/api/contract' default and 404'd.
  loom:           '/contract',
  // §FIXED 2026-09-02 — James, live, from a real boot log: "[orch]
  // contract.unreachable — versionium (invalid JSON: Unexpected token
  // 'N', "Not found" is not valid JSON)". Exact same real bug class as
  // loom's own comment right above — versionium/routes/system.js's real
  // GET /contract route (built this session, VS1) was simply never
  // added here, so this poller fell through to '/api/contract' and hit
  // a real, honest 404 whose plain-text body ("Not found") isn't valid
  // JSON, hence the parse error James saw.
  versionium:     '/contract',
};

function contractPathFor(systemId) {
  return CONTRACT_PATHS[systemId] || '/api/contract';
}

// ── Fetch a system's contract over HTTP ───────────────────────────────────────
async function fetchContract(systemId, host, port, timeoutMs = 5000) {
  const contractPath = contractPathFor(systemId);

  // Retry up to 3× on socket hang-up — system may still be binding its HTTP server
  for (let _attempt = 1; _attempt <= 3; _attempt++) {
    const _result = await _fetchOnce(contractPath, host, port, timeoutMs);
    if (_result.ok) return _result;
    const err = (_result.error || '').toLowerCase();
    const isHangup = err.includes('socket hang up') || err.includes('econnreset') || err.includes('epipe');
    if (!isHangup || _attempt === 3) return { ..._result, attempts: _attempt };
    await new Promise(r => setTimeout(r, 1500 * _attempt));
  }
}

async function _fetchOnce(contractPath, host, port, timeoutMs) {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: host || '127.0.0.1',
      port,
      path:     contractPath,
      method:   'GET',
      headers:  { 'Accept': 'application/json', 'X-Requester': 'orchestrator-contract-hs' },
    }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        try {
          const body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
          resolve({ ok: res.statusCode === 200, status: res.statusCode, body });
        } catch(e) {
          resolve({ ok: false, status: res.statusCode, error: 'invalid JSON: ' + e.message });
        }
      });
    });
    req.setTimeout(timeoutMs, () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
    req.on('error', (e) => resolve({ ok: false, error: e.message }));
    req.end();
  });
}

// ── Hash a contract for drift detection ──────────────────────────────────────
function hashContract(contractBody) {
  const canonical = JSON.stringify(contractBody, Object.keys(contractBody).sort());
  return crypto.createHash('sha256').update(canonical).digest('hex').slice(0, 16);
}

// ── Verify a system's contract ────────────────────────────────────────────────
async function verifySystem(systemId, host, port, opts = {}) {
  const { expectedHash = null, jaaInsert = null, onResult = null } = opts;
  const t0 = Date.now();

  // Fetch
  const result = await fetchContract(systemId, host, port);
  if (!result.ok) {
    const entry = {
      systemId, host, port,
      trust:     TRUST.UNREACHABLE,
      error:     result.error || `HTTP ${result.status}`,
      checkedAt: Date.now(),
      latencyMs: Date.now() - t0,
    };
    _registry.set(systemId, entry);
    _log(jaaInsert, 'contract.unreachable', { systemId, error: entry.error });
    onResult?.(entry);
    return entry;
  }

  // Handle both flat contract { id, routes, ... } and
  // nested contract { contract: { id, routes, ... } } shapes
  let raw = result.body?.contract || result.body;
  // Orchestrator wraps in { ok, contract: { systems: { ... } } }
  // Individual system contracts are flat: { id, routes, ... }
  // If it has a 'systems' key and no 'id', look for the system's entry
  if (raw?.systems && !raw?.id && raw?.systems?.[systemId]) {
    raw = raw.systems[systemId];
  }
  const contract = raw;
  const hash     = hashContract(contract);

  // Check system id matches
  const idMatch = !contract.id || contract.id.includes(systemId) || contract.namespace?.includes(systemId);

  // Check for schema drift
  let trust = TRUST.VERIFIED;
  let driftReason = null;

  if (expectedHash && expectedHash !== hash) {
    trust       = TRUST.MISMATCH;
    driftReason = 'schema hash ' + hash + ' ≠ expected ' + expectedHash;
  }

  // Route count — handle various contract shapes
  const routes   = contract.routes || contract.channels || [];
  const hasCli   = Array.isArray(contract.cli);
  const hasContent = routes.length > 0 || contract.siso?.emits?.length > 0 || contract.namespace;

  const entry = {
    systemId,
    host:       host || '127.0.0.1',
    port,
    trust,
    hash,
    idMatch,
    routeCount: routes.length,
    cliCount:   hasCli ? contract.cli.length : 0,
    driftReason,
    checkedAt:  Date.now(),
    latencyMs:  Date.now() - t0,
  };

  _registry.set(systemId, entry);
  _log(jaaInsert, `contract.${trust.toLowerCase()}`, {
    systemId, hash, trust, driftReason, latencyMs: entry.latencyMs,
  });

  onResult?.(entry);
  return entry;
}

// ── Verify all known systems ──────────────────────────────────────────────────
async function verifyAll(systems, opts = {}) {
  // systems: [{ id, host, port }]
  const results = await Promise.allSettled(
    systems.map(s => verifySystem(s.id, s.host, s.port, opts))
  );
  return results.map((r, i) =>
    r.status === 'fulfilled' ? r.value : { systemId: systems[i].id, trust: TRUST.UNREACHABLE, error: r.reason?.message }
  );
}

// ── Get current trust state ───────────────────────────────────────────────────
function getEntry(systemId)  { return _registry.get(systemId) || null; }
function getAllEntries()      { return [..._registry.values()]; }
function getTrustMap()       {
  const map = {};
  for (const [id, e] of _registry) map[id] = { trust: e.trust, hash: e.hash, checkedAt: e.checkedAt };
  return map;
}

// ── Log helper ────────────────────────────────────────────────────────────────
function _log(jaaInsert, type, payload) {
  if (jaaInsert) {
    try {
      jaaInsert('event_log', {
        uuid:    require('crypto').randomUUID(),
        type:    `${MODULE_ID}.${type}`,
        payload, source: MODULE_ID, ts: Date.now(), causedBy: null,
      });
    } catch(_) {}
  }
}

module.exports = { verifySystem, verifyAll, getEntry, getAllEntries, getTrustMap, TRUST, MODULE_ID, CONTRACT_PATHS };

'use strict';
/**
 * cortex/memory/table-deduplicator.js — generic duplicate-row removal for
 * JAA tables, same shared-mechanism shape as table-compactor.js (§10.3 —
 * one real tool, not a bespoke copy per table).
 *
 * §BUILT 2026-09-12 — James: "clear all duplicates from each table."
 *
 * Two real, distinct kinds of duplicate, handled differently on purpose:
 *
 * 1. EXACT UUID COLLISION — two live rows sharing the same real uuid.
 *    Confirmed via guardian/jaa-store.js: mutation-journal replay already
 *    merges same-uuid lines into one row at load time (open()'s own
 *    `{_mutation:true, uuid, ...patch}` handling) — so two SEPARATE rows
 *    with the same uuid surviving into a live query() result is always a
 *    real bug somewhere upstream (a raw insert() that should have been an
 *    update/upsert — the exact class of bug already found and fixed once
 *    this session in guardian/server.js's session-naming double-write).
 *    Because this can never be legitimate, it is the ALWAYS-ON default
 *    for every table, no opt-in required — same safety reasoning
 *    table-compactor.js gives for its own undatable-row rule (§1.2: never
 *    guess), just the opposite direction (never NOT fix an unambiguous
 *    case).
 *
 * 2. CONTENT-LEVEL DUPLICATE — two rows with different real uuids that
 *    represent the same real-world fact (e.g. the same chat message
 *    logged twice under two different uuids, matching the class of bug
 *    already found in guardian's chat_log writes earlier this session).
 *    This is NOT generalizable safely without knowing what "the same
 *    real thing" means for a given table's actual shape — so this is
 *    opt-in only, via a caller-supplied fingerprint(row) function passed
 *    per table. No default fingerprint is guessed for any table (§1.2 —
 *    same honest-scope discipline as table-compactor.js's own tables[]
 *    list: silence, not a guessed default, when nothing is configured).
 *
 * §0.3 — nothing lost silently. Every real batch of removed duplicates is
 * recorded in dedup_log (table, kind, removedCount, keptUuid per group,
 * ts) BEFORE the delete — same ordering table-compactor.js's own
 * compaction_log already proved.
 *
 * Tie-break rule when a group of duplicates is found: the row with the
 * LATEST real timestamp (ts ?? crystallisedAt ?? createdAt) is kept, all
 * others in that group are removed — "most recent real state wins",
 * matching the mutation-journal's own semantics (later entries represent
 * newer state). A row with no real timestamp at all is never chosen as
 * the keeper over one that has one, and is never removed on a guess
 * either if every member of its group is equally undatable — see
 * _pickKeeper below.
 */

const MODULE_ID = 'cortex.memory.table-deduplicator';

function _rowTs(row) {
  const ts = row.ts ?? row.crystallisedAt ?? row.createdAt;
  return typeof ts === 'number' ? ts : null;
}

// Given a group of >=2 rows considered duplicates of each other, pick the
// one to keep. Prefers a real, later timestamp; falls back to keeping the
// LAST one encountered (closest to current/most-recently-appended, same
// natural-Map-insertion-order reasoning jaa-db.js's own tail() relies on)
// when timestamps can't distinguish them.
function _pickKeeper(group) {
  let keeper = group[0];
  let keeperTs = _rowTs(keeper);
  for (let i = 1; i < group.length; i++) {
    const r = group[i];
    const t = _rowTs(r);
    if (t !== null && (keeperTs === null || t >= keeperTs)) { keeper = r; keeperTs = t; }
  }
  return keeper;
}

/**
 * dedupeTable(jaa, table, opts) — one real pass over one real table.
 * opts.fingerprint(row) => string|null — optional, content-level dedup.
 * Returns { table, removed, groups } — groups is the number of distinct
 * duplicate-sets found (for a real, honest report, not just a count that
 * hides whether this was one giant collision or many small ones).
 */
function dedupeTable(jaa, table, opts = {}) {
  let rows;
  try { rows = jaa.query(table, () => true, 10000000) || []; }
  catch (e) { return { table, removed: 0, skipped: true, reason: `query failed: ${e.message}` }; }
  if (!rows.length) return { table, removed: 0, groups: 0 };

  // Pass 1 — exact uuid collision, always on.
  const byUuid = new Map();
  for (const r of rows) {
    if (!r.uuid) continue; // can't identify a row with no uuid at all — leave alone, not a guess target
    if (!byUuid.has(r.uuid)) byUuid.set(r.uuid, []);
    byUuid.get(r.uuid).push(r);
  }

  const toRemove = []; // { uuid, kind, group }
  for (const [uuid, group] of byUuid) {
    if (group.length < 2) continue;
    const keeper = _pickKeeper(group);
    for (const r of group) if (r !== keeper) toRemove.push({ row: r, kind: 'uuid_collision', keptUuid: uuid });
  }

  // Pass 2 — content-level, only if the caller explicitly opted in.
  if (typeof opts.fingerprint === 'function') {
    const removedAlready = new Set(toRemove.map(x => x.row));
    const byFp = new Map();
    for (const r of rows) {
      if (removedAlready.has(r)) continue;
      let fp;
      try { fp = opts.fingerprint(r); } catch (_) { fp = null; }
      if (fp == null) continue; // fingerprint declined to classify this row — never guessed
      if (!byFp.has(fp)) byFp.set(fp, []);
      byFp.get(fp).push(r);
    }
    for (const [fp, group] of byFp) {
      if (group.length < 2) continue;
      const keeper = _pickKeeper(group);
      for (const r of group) if (r !== keeper) toRemove.push({ row: r, kind: 'content_duplicate', keptUuid: keeper.uuid || null });
    }
  }

  if (!toRemove.length) return { table, removed: 0, groups: 0 };

  const groupCount = new Set(toRemove.map(x => x.keptUuid)).size;

  // §0.3 — audit entry BEFORE the delete, same ordering as compaction_log.
  try {
    jaa.insert('dedup_log', {
      uuid: require('crypto').randomUUID(), table, removedCount: toRemove.length, groups: groupCount,
      kinds: [...new Set(toRemove.map(x => x.kind))], ts: Date.now(),
    });
  } catch (e) {
    console.warn(`[${MODULE_ID}] dedup_log write failed for ${table} (real delete below still proceeds): ${e.message}`);
  }

  // §FIXED 2026-09-12 — this used to match by object reference
  // (removeRefs.has(r), r being the actual row object), which only ever
  // worked against this module's own mock tests (which reuse the same
  // objects across query/delete calls). The real store
  // (guardian/jaa-store.js) returns a fresh {...row} spread copy on
  // every query() — confirmed directly — so reference equality can
  // never match a second query or the live Map iteration delete()
  // itself walks. uuid alone can't be the fix here specifically (unlike
  // table-compactor.js's capTable, which was the same bug but IS fixed
  // with uuid, since capTable's rows have distinct real uuids) — a
  // uuid_collision group's members share the SAME uuid by definition,
  // so matching on uuid would delete the keeper too. The real, stable,
  // per-row identifier that survives copying AND still disambiguates
  // same-uuid rows is the store's own internal `id` field (confirmed:
  // insert() does `{ ...row, id }`, so id ends up on every real row
  // exactly like uuid does, just store-assigned and unique per stored
  // row regardless of what the row's own uuid field says).
  const removeIds = new Set(toRemove.map(x => x.row.id).filter(Boolean));
  let removed = 0;
  try {
    removed = jaa.delete(table, (r) => removeIds.has(r.id)) || 0;
  } catch (e) {
    console.warn(`[${MODULE_ID}] delete failed for ${table}: ${e.message}`);
    return { table, removed: 0, skipped: true, reason: `delete failed: ${e.message}` };
  }

  console.log(`[${MODULE_ID}] ${table}: removed ${removed} duplicate row(s) across ${groupCount} group(s)`);
  return { table, removed, groups: groupCount };
}

/**
 * dedupeAll(jaa, tables, fingerprints) — one real pass across an explicit
 * list of tables. `fingerprints` (optional): { tableName: fingerprintFn }
 * — same explicit, no-default-guessed opt-in as dedupeTable's own opts.
 */
function dedupeAll(jaa, tables, fingerprints = {}) {
  if (!Array.isArray(tables) || !tables.length) {
    throw new Error(`[${MODULE_ID}] dedupeAll() requires a real, explicit tables[] list`);
  }
  const results = [];
  for (const table of tables) {
    try { results.push(dedupeTable(jaa, table, { fingerprint: fingerprints[table] })); }
    catch (e) {
      console.warn(`[${MODULE_ID}] dedup failed for ${table}: ${e.message}`);
      results.push({ table, removed: 0, skipped: true, reason: e.message });
    }
  }
  return results;
}

let _timer = null;

/**
 * start(jaa, tables, intervalMs, fingerprints) — periodic sweep, same
 * real shape as table-compactor.js's own start()/stop() — deliberately
 * a separate timer/module, not folded into compaction's own tick, since
 * dedup and decay-compaction are different real operations (removing
 * duplicate live rows vs. aging out old-but-unique ones) that happen to
 * share a storage layer, not one operation with two names.
 */
function start(jaa, tables, intervalMs = 15 * 60 * 1000, fingerprints = {}) {
  if (!Array.isArray(tables) || !tables.length) throw new Error(`[${MODULE_ID}] start() requires a real, explicit tables[] list`);
  function sweep() {
    try { dedupeAll(jaa, tables, fingerprints); }
    catch (e) { console.warn(`[${MODULE_ID}] dedup tick failed: ${e.message}`); }
  }
  sweep(); // boot dedup clears any accumulated backlog immediately, same as table-compactor.js
  _timer = setInterval(sweep, intervalMs);
  if (_timer.unref) _timer.unref();
  console.log(`[${MODULE_ID}] v1.0.0 — real duplicate-removal for [${tables.join(', ')}], every ${intervalMs / 60000}min`);
  return { ok: true };
}

function stop() {
  if (_timer) { clearInterval(_timer); _timer = null; }
}

/**
 * insertDeduped(jaa, table, row, fingerprint) — James: "have a hash or id
 * for each entry, and each time it logs to a table again, just logs the
 * id and date, so we don't waste space." Write-time prevention, the
 * other half of this tool: dedupeTable/dedupeAll clean up duplicates
 * already written; this stops a REPEAT of the same real fact from ever
 * being written in full a second time.
 *
 * Deliberately NOT wired into jaaDB.insert() itself — that function has
 * real callers across every process in this tree (checked: cortex,
 * guardian, orchestrator, intelligence, copilot, and more), none of
 * which asked for this behavior change, and a table where the same
 * fingerprint legitimately recurring is meaningful (most of them —
 * event_log entries are usually NOT "the same event happening again is
 * noise", they're real distinct occurrences) would silently lose real
 * data if this ran unconditionally. This is opt-in, per call site, per
 * table — the caller decides a given table's writes are genuinely
 * "the same fact restated" before using it.
 *
 * fingerprint(row) => string — required, no default guessed (§1.2, same
 * discipline as dedupeTable's own content-level opt-in). The FIRST real
 * occurrence of a fingerprint gets the real, full row, inserted
 * normally. Every SUBSEQUENT occurrence of that same fingerprint writes
 * a real, tiny reference row instead: { uuid, ts, refOf: <original
 * uuid>, fingerprint } — not the full original payload — recording only
 * that the same fact recurred, and when, never re-storing what it was.
 */
function insertDeduped(jaa, table, row, fingerprint) {
  if (typeof fingerprint !== 'function') {
    throw new Error(`[${MODULE_ID}] insertDeduped() requires a real fingerprint(row) function — no default is guessed`);
  }
  const fp = fingerprint(row);
  if (fp == null) return jaa.insert(table, row); // fingerprint declined to classify — insert normally, not a guess

  const existing = jaa.query(table, (r) => r.fingerprint === fp && !r.refOf, 1) || [];
  if (!existing.length) {
    // First real occurrence of this fingerprint — store it in full, tagged
    // so future occurrences can find it.
    return jaa.insert(table, { ...row, fingerprint: fp });
  }
  // A repeat of an already-seen fact — log the reference only, not the
  // full row a second time.
  return jaa.insert(table, {
    uuid: row.uuid || require('crypto').randomUUID(),
    ts: row.ts ?? Date.now(),
    refOf: existing[0].uuid,
    fingerprint: fp,
  });
}

module.exports = { MODULE_ID, dedupeTable, dedupeAll, insertDeduped, start, stop };

'use strict';
/**
 * cortex/core/raid/snr-filter.js — RAID SNR Pre-Gate
 * UUID: nexus-raid-snr-filter-v1-0000-2026-0706-jamesbrooks-001
 * spec: docs/raid-snr-filter.spec (v1.1.0)
 *
 * Built 2026-07-06. This file did not exist anywhere in the tree — only
 * the spec and tests/modules/test-snr-filter.js (10 pinned cases) did.
 * The spec's own footer claimed "10/10 PASSING" against a module that
 * could not have run. Built directly against the pinned test fixtures,
 * not guessed — every branch below is load-bearing for a specific T-00N.
 *
 * Resolution order (docs/raid-snr-filter.spec):
 *   1. Known invariant   — forge_patches, status:verified, successRate>0.7  → tokens:0
 *   2. Crystallised pattern — bep_patterns, crystallised, cluster match +
 *      genuine signature/intent overlap (cluster alone is NOT enough —
 *      see note below) → tokens:0
 *   3. Open loop — fault_taxonomy friction above threshold for this faultClass
 *      → dispatch, context injected
 *   4. Genuine unknown — dispatch, context injected (v1.1 fix: tier 4 used
 *      to dispatch blind; every tier now forwards causedBy/sessionId/jobId)
 *
 * §Note on tier 2 matching: an earlier reading of the spec would let ANY
 * crystallised pattern in the same cluster match ANY call in that cluster,
 * regardless of what the call is actually about. Checked against the pinned
 * fixtures: pat1 is cluster:'code', and T-004/T-005 pin cluster:'code' calls
 * to resolve as tier-3 open_loop, not tier-2 pattern — cluster-only matching
 * would silently misfire in exactly the case the tests are pinning against.
 * Tier 2 requires a real overlap between the pattern's signature and the
 * call's intent text, not just a shared cluster.
 */

const { jaaDB, uid } = require('../../memory/jaa-db');
const tunables = require('./tunables');

const MODULE_ID = 'cortex/core/raid/snr-filter';
const VERSION   = '1.1.0';

const SNR = { invariant: 1.0, open_loop: 0.5, unknown: 0.0 };

// In-memory counters — reset on process restart, same lifecycle as RAID's
// own _health/_weights (this module has no independent persistence beyond
// the per-call event_log write; stats() reflects this process's own view).
const _stats = { total: 0, byType: { invariant: 0, pattern: 0, open_loop: 0, unknown: 0 } };

// ── Tier 1 — known invariant ─────────────────────────────────────────────────
function checkInvariant(intent, cluster, faultClass) {
  if (!faultClass) return null;
  const hits = jaaDB.query(
    'forge_patches',
    row => row.faultClass === faultClass && row.status === 'verified' && row.successRate > tunables.get('invariantThreshold'),
    1
  );
  if (!hits.length) return null;
  const patch = hits[0];
  return {
    type:   'invariant',
    dispatch: false,
    tokens: 0,
    snr:    SNR.invariant,
    reason: `known invariant for faultClass '${faultClass}' (patch ${patch.uuid}, successRate ${patch.successRate})`,
    patch,
  };
}

// ── Tier 2 — crystallised pattern, real signature overlap required ──────────
function _checkPattern(intent, cluster) {
  const candidates = jaaDB.query(
    'bep_patterns',
    row => row.crystallised === true && row.cluster === cluster,
    10
  );
  const text = String(intent || '').toLowerCase();
  for (const pat of candidates) {
    const sigParts = String(pat.signature || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
    const overlap = sigParts.some(part => part.length > 2 && text.includes(part));
    if (overlap) {
      return {
        type:   'pattern',
        dispatch: false,
        tokens: 0,
        snr:    typeof pat.confidence === 'number' ? pat.confidence : SNR.invariant,
        reason: `crystallised pattern '${pat.signature}' matched (pattern ${pat.uuid}, confidence ${pat.confidence})`,
        pattern: pat,
      };
    }
  }
  return null;
}

// ── Tier 3 — open loop (elevated friction) ───────────────────────────────────
function _checkOpenLoop(faultClass) {
  if (!faultClass) return null;
  const hits = jaaDB.query(
    'fault_taxonomy',
    row => row.faultClass === faultClass && row.friction > tunables.get('frictionThreshold'),
    1
  );
  if (!hits.length) return null;
  const rec = hits[0];
  return {
    type:   'open_loop',
    dispatch: true,
    tokens: null, // real dispatch — token count is the caller's to report, not this gate's
    snr:    SNR.open_loop,
    reason: `elevated friction (${rec.friction}) for faultClass '${faultClass}' (${rec.uuid})`,
    friction: rec,
  };
}

// ── filter — the pre-gate, runs before every RAID dispatch ─────────────────
function filter(call = {}) {
  const { intent, cluster, faultClass, causedBy, sessionId, jobId } = call;
  const ctx = { causedBy, sessionId, jobId };

  let result =
    checkInvariant(intent, cluster, faultClass) ||
    _checkPattern(intent, cluster) ||
    _checkOpenLoop(faultClass);

  if (!result) {
    result = {
      type:   'unknown',
      dispatch: true,
      tokens: null,
      snr:    SNR.unknown,
      reason: 'no known invariant, pattern, or open loop — genuine unknown',
    };
  }

  // v1.1 fix — every tier forwards context now, not just open_loop/unknown
  // (the bug the spec names: tier 4 used to dispatch blind). Tier 1/2
  // resolve locally (dispatch:false) so this doesn't change their behavior,
  // it just means the causal chain is attached honestly on every result
  // instead of only the tiers that happen to dispatch.
  result.injectContext = true;
  result.context = ctx;

  _stats.total += 1;
  _stats.byType[result.type] = (_stats.byType[result.type] || 0) + 1;

  jaaDB.insert('event_log', {
    uuid: uid(),
    type: 'raid.snr.filter',
    payload: { intent, cluster, faultClass, resultType: result.type, snr: result.snr, dispatch: result.dispatch },
    causedBy,
    ts: Date.now(),
  });

  return result;
}

// ── stats — total calls, breakdown by tier, resolved-without-dispatch rate ──
function stats() {
  const resolvedLocally = (_stats.byType.invariant || 0) + (_stats.byType.pattern || 0);
  const pct = _stats.total > 0 ? ((resolvedLocally / _stats.total) * 100).toFixed(1) : '0.0';
  return {
    total: _stats.total,
    byType: { ..._stats.byType },
    efficiency: `${pct}% resolved without dispatch`,
  };
}

module.exports = {
  MODULE_ID, VERSION,
  filter, checkInvariant, stats,
};

