    outcome: 'pass',
    producedHooks: [
      { id: 'nexus.renderer.hook.tokens-in', name: 'tokens-in', type: 'direct', direction: 'in', uuid: 'demo-renderer-hook-in-uuid-001' },
    ],
  });
