    _lastPath = location.pathname;
    _sessionId = null; // reset session chain on navigation
    if (currentJobId) stopWatch();
    _log('sys', `Nav → ${chatId()}`);
    setTimeout(() => sendDOMMap(), 1000);
  }
}, 800);

