  } else if (result.failures?.some(f => f.axiomId === 'loom.unique-id')) {
    alreadySeeded++;
    console.log(`  · ${kind} ${payload.id} (already seeded)`);
  } else {
    failed++;
    console.error(`  ✗ ${kind} ${payload.id} — ${JSON.stringify(result)}`);
  }
  return result;
}

