  ECDH:    'prime256v1',   // P-256
  AES_GCM: 'aes-256-gcm',
  HMAC:    'sha256',
  HASH256: 'sha256',
  HASH512: 'sha512',
};

const SIZES = {
  IV:       16,   // AES-GCM IV bytes
  TAG:      16,   // GCM auth tag bytes
  SALT:     32,   // scrypt salt bytes
