  HKDF_OUT: 32,   // HKDF output bytes
  TOKEN:    32,   // random token bytes
};

// ─── Result helpers ───────────────────────────────────────────────────────────
const ok  = (data)  => ({ ok: true,  ...data });
const err = (msg, detail = null) => ({ ok: false, error: msg, detail });

