try { ora    = require("ora"); }           catch { ora    = (t) => ({ start() { process.stdout.write(t + '...\n'); return this; }, succeed(m){ console.log('✓', m||''); }, fail(m){ console.error('✗', m||''); } }); }
try { qrcode = require("qrcode"); }        catch { qrcode = null; }
