  try {
    const { jaaDB } = require('../cortex/memory/jaa-db');
    const { TABLE_TIERS } = require('../cortex/memory/tiers.js');
    require('../cortex/memory/table-deduplicator').start(jaaDB, Object.keys(TABLE_TIERS));
