// history with near-duplicate snapshots.
const COOLDOWN_MS = parseInt(process.env.VERSIONIUM_AUTOCOMMIT_COOLDOWN_MS || '300000', 10);

let _lastAutoCommitAt = 0;
let _subscribed = false;
let _bus = null;

function _getBus() {
  if (_bus) return _bus;
