      ctx.dir = ctx.file ? require('path').dirname(ctx.file) : null;
      ctx.detail = gapRow.body || gapRow.detail || null;
    }
    const why = await gapField.explainWhy(gapUuid, {});
    if (why?.ok && why.why?.available) {
      ctx.root = why.why.root || null;
      ctx.conditions = why.why.conditions || [];
    }
    if (ctx.system) {
      ctx.siblingDanglingHooks = gapField.openGaps({ domain: 'system', limit: 10000 })
        .filter(g => g.type === 'dangling-hook' && (g.source === ctx.system))
        .map(g => ({ hookId: g.meta?.hookId || null, direction: g.meta?.direction || null, detail: g.body || null }));
    }
  } catch (e) {
    ctx.gatherError = e.message; // honest: partial/no context is reported as such below, never silently omitted
  }
  if (ctx.system) {
    try {
      const specPath = require('path').join(__dirname, '../../docs', `${ctx.system}.spec`);
      if (require('fs').existsSync(specPath)) {
        const raw = require('fs').readFileSync(specPath, 'utf8');
        const purpose = (raw.match(/purpose:\s*(.+)/) || [])[1];
        ctx.expected = purpose ? purpose.trim() : '(spec exists but has no purpose: line)';
      } else {
        ctx.expected = `(no docs/${ctx.system}.spec exists — LM1 living-model phasemap tracks this)`;
      }
    } catch (e) { ctx.expected = `(spec lookup failed: ${e.message})`; }
  }
  return ctx;
}

function _formatFailureContext(ctx) {
  const lines = [];
  lines.push(`SYSTEM: ${ctx.system || '(unknown — gap row had no source/system field)'}`);
  lines.push(`FILE/DIR: ${ctx.file || '(none recorded)'}${ctx.dir ? ` (dir: ${ctx.dir})` : ''}`);
  lines.push(`SUPPOSED TO DO: ${ctx.expected || '(not looked up)'}`);
  lines.push(`DOING INSTEAD: ${ctx.detail || '(no detail on the gap row)'}`);
  if (ctx.root || ctx.conditions.length) {
    lines.push(`EVENTS LEADING UP TO IT (real causal chain, not a guess):`);
    if (ctx.root) lines.push(`  root: ${JSON.stringify(ctx.root)}`);
    for (const c of ctx.conditions.slice(0, 10)) lines.push(`  - ${JSON.stringify(c)}`);
  } else {
    lines.push(`EVENTS LEADING UP TO IT: none available (no causal chain traced for this gap — do not assume there was no precursor, only that the causal field didn't have one)`);
  }
  if (ctx.siblingDanglingHooks.length) {
    lines.push(`DANGLING HOOKS ON THIS SAME SYSTEM (may be related, may be independent — check before assuming):`);
    for (const h of ctx.siblingDanglingHooks.slice(0, 10)) lines.push(`  - ${h.hookId} (${h.direction}): ${h.detail}`);
  }
  if (ctx.gatherError) lines.push(`(NOTE: context gathering hit an error and may be partial: ${ctx.gatherError})`);
  return lines.join('\n');
}

// ── Level 4 — failure mode, human action item ─────────────────────────────────
function _enterFailureMode(gapType, gapUuid, existing) {
  const entry = {
    uuid: uid(), faultClass: gapType, gapUuid, friction: existing?.friction ?? 1.0,
    enteredAt: Date.now(), source: MODULE_ID,
  };
  try { jaaDB.insert('failure_modes', entry); }
  catch (e) { console.warn(`[${MODULE_ID}] failure_modes write failed: ${e.message}`); }
  if (_bus) _bus.emit('cortex.self-heal.failure_mode', {
    gapType, gapUuid, level: 4,
    message: `'${gapType}' has exhausted all auto-attempt levels — human action required (docs/self-heal.spec level 4)`,
  });
  // §RAID-SOURCE 2026-08-29 — James: "hook... self-heal system into
  // raid." Real, honest wire: Level 4 already means "every automated
  // remediation attempt failed, this needs something NEW to happen" —
  // exactly what a RAID contract is for.
  //
  // §CONTEXT-WIRE 2026-09-02 — deliberately fire-and-forget, NOT awaited
  // here. _enterFailureMode stays synchronous (failure_modes write + bus
  // emit above happen immediately, exactly as before this change)
  // because that write is the one thing that must never be lost or
  // delayed — §0.3. The richer, async-gathered RAID contract goes out
  // right after, best-effort.
  (async () => {
    let content = `A real, automated self-heal remediation attempt has exhausted all 4 levels for a real fault. faultClass="${gapType}", gapUuid="${gapUuid}".`;
    let ctx = null;
    try {
      ctx = await _gatherFailureContext(gapType, gapUuid);
      content += `\n\n${_formatFailureContext(ctx)}`;
      // §INTENT-AND-AGENT — forAgent stays unset: fault_taxonomy's real
      // row shape has no per-fault-class "which agent fixes this" field
      // anywhere in this codebase — inventing one here would be exactly
      // the fabrication this codebase's own discipline avoids elsewhere.
      // RAID's real fitness-based router picks instead.
    } catch (e) {
      content += `\n\n(NOTE: context-gathering itself failed, contract submitted with faultClass only: ${e.message})`;
    }
    content += `\n\nRead the relevant real code and this codebase's own real gap/event-ledger data for this fault before proposing anything (bottom-up — do not guess at a fix without reading what actually failed). If you find and make a real, verified fix, report SEAM VERDICT: PASS. If you cannot resolve it, report SEAM VERDICT: FAIL with your real findings — this becomes the actual human action item, not a placeholder.`;
    try {
      require('../core/raid/contract-intake.js').submitContract({
        content, title: `self-heal level-4: ${gapType}`,
      }, { source: 'self-heal', intention: `heal:${gapType}`, onFail: { action: 'halt' } });
    } catch (e) {
      console.warn(`[${MODULE_ID}] could not submit level-4 fault as a real RAID contract (failure_modes row above is the real record either way): ${e.message}`);
    }
    // §ADDED 2026-09-12 — James: "each system needs .failure_mode nodes
    // that uses the intelligence system to map the events leading up to
    // a failure mode... delta and sigmas... make a .failure_mode and
    // .macro to replicate the bug." Same real ctx already gathered above
    // for the RAID contract text — reused, not re-derived — plus a real
    // sigma delta and a real .debug_macro when the causal chain has real
    // conditions to compose. Fire-and-forget, same §0.3 discipline as
    // the RAID submission above: the synchronous failure_modes write
    // already happened and is never delayed or risked by this.
    try {
      await require('./failure-mode-forensics.js').enrichFailureMode(
        gapType, gapUuid, entry.uuid, _gatherFailureContext,
      );
    } catch (e) {
      console.warn(`[${MODULE_ID}] failure-mode enrichment failed (failure_modes row above is the real record either way): ${e.message}`);
    }
  })();
  return { level: 4, outcome: 'failure_mode' };
}

// ── HEAL_REQUESTED handler ──────────────────────────────────────────────────────
function _onHealRequested(event) {
  const { gapType, gapUuid, body, modulePath } = event?.payload || {};
  if (!gapType) return;

  if (SEMANTIC_GAP_TYPES.includes(gapType)) {
    if (_bus) _bus.emit('cortex.self-heal.skipped', { gapType, gapUuid, reason: 'semantic_gap_excluded (§7.2)' });
    return;
  }

  const { level, existing, band } = _levelFor(gapType);

  if (band === 'FAILURE_MODE') {
    _enterFailureMode(gapType, gapUuid, existing);
    return;
  }

  switch (level) {
    case 0: return _attemptLevel0(gapType, gapUuid, body);
    case 1: return _attemptLevel1(gapType, gapUuid, modulePath);
    case 2: return _attemptLevel2(gapType, gapUuid, body);
    default: return _attemptLevel3(gapType, gapUuid);
  }
}

function health() {
  return { ok: true, module: MODULE_ID, version: VERSION, busWired: !!_bus, diagEnginesLoaded: !!_getDiagEngines() };
}

function init(cfg = {}) {
  _bus = cfg.bus || null;
  if (_bus) _bus.on('HEAL_REQUESTED', _onHealRequested);
  console.log(`[${MODULE_ID}] v${VERSION} — 5-level escalation ladder active${_bus ? ' (bus-wired)' : ' (no bus — test mode)'}`);
  return { ok: true };
}

function stop() {
  if (_bus) _bus.off('HEAL_REQUESTED', _onHealRequested);
  _bus = null;
}

module.exports = {
  MODULE_ID, VERSION, SEMANTIC_GAP_TYPES,
  init, stop, health,
  _onHealRequested, // exported for direct testing, §4.1
  _gatherFailureContext, _formatFailureContext, // exported for direct testing, §4.1
};

'use strict';
/**
 * loom/ingest/revisions.js — disk-first store for ingested revisions.
 * comp_id: nexus.loom.ingest.revisions
 * UUID: nexus-loom-revisions-v1-0000-2026-0702-jamesbrooks-001
 * Phase: 144 (this session — drag-and-drop-equivalent ingest, backend half)
 *
 * A revision is NOT a component/seam/hook/wire — forcing "nexus-consolidated
 * (23).zip" into that schema would be a category error (a zip snapshot
 * isn't a named wire between two surfaces). This is its own small store,
 * same disk-first discipline (§2.1/§2.2) as loom/schema/registry.js, kept
 * separate on purpose.
 *
 * One revision record:
 *   { id, sourceFileName, sha256, byteSize, fileCount, ingestedAt,
 *     parentId, diff: { added, removed, changed, unchanged } }
 *
 * Lineage is a simple parent pointer, same shape as idearium/repo/index.js's
 * fork(repoUuid) -> parent tracking — nothing here is a new lineage model,
 * it's the same one, ported to LOOM's own store.
 */
const fs = require('fs');
const path = require('path');

class RevisionRegistry {
  constructor({ dataDir = null } = {}) {
    this.dataDir = dataDir || path.join(__dirname, '..', 'data');
    this.file = path.join(this.dataDir, 'revisions.json');
    this._state = this._load();
  }

  _load() {
    try {
      const raw = JSON.parse(fs.readFileSync(this.file, 'utf8'));
      return raw.revisions || {};
    } catch (_) {
      return {};
    }
  }

  _persist() {
    if (!fs.existsSync(this.dataDir)) fs.mkdirSync(this.dataDir, { recursive: true });
    fs.writeFileSync(this.file, JSON.stringify({ revisions: this._state }, null, 2));
  }

  add(record) {
    if (this._state[record.id]) {
      throw new Error(`[loom/revisions] duplicate revision id: ${record.id}`);
    }
    this._state[record.id] = { ...record };
    this._persist();
    return this._state[record.id];
  }

  get(id) {
    return this._state[id] || null;
  }

  all() {
    return { ...this._state };
  }

  /** latest() — most recently ingested revision, by ingestedAt. Null if none. */
  latest() {
    const all = Object.values(this._state);
    if (!all.length) return null;
    return all.reduce((a, b) => (a.ingestedAt > b.ingestedAt ? a : b));
  }

  /** chain(id) — full lineage from root to id, oldest first. */
  chain(id) {
    const out = [];
    let cur = this.get(id);
    while (cur) {
      out.unshift(cur);
      cur = cur.parentId ? this.get(cur.parentId) : null;
    }
    return out;
  }
}

module.exports = { RevisionRegistry };

'use strict';
/**
 * lib/pulse.js — NEXUS Pulse System  v1.0.0
 * UUID: nexus-pulse-v1-0000-4000-0000-000000000001
 *
 * The pulse is the heartbeat made active. Every system that imports this
 * module sends a regular POST /api/heartbeat to the orchestrator and
 * receives an ACK with latency data. The orchestrator broadcasts each
 * ACK as an `orchestrator.pulse` SSE event to all connected UI clients,
 * who update health dots in real time instead of waiting for the 8s poll.
 *
 * Architecture (server-side, Node.js):
 *   createPulse(opts) → starts interval, returns { stop, latency, status }
 *
 * The browser-side equivalent lives in ui/pulse.js.
 *
 * §1.2  Nothing silently fails — every missed beat is logged.
 * §2.1  Persistence first — latency ring written to ledger every minute.
 * §5.1  UUID on everything — each pulse carries a pulsId for tracing.
 */

const http        = require('http');
const { randomUUID } = require('crypto');

// ── Ring buffer (inline — no external deps) ───────────────────────────────────
class _Ring {
  constructor(max) { this._max = max; this._buf = []; }
  push(v) { this._buf.push(v); if (this._buf.length > this._max) this._buf.shift(); }
  last(n)  { return this._buf.slice(-n); }
  all()    { return [...this._buf]; }
  avg()    {
    if (!this._buf.length) return null;
    return Math.round(this._buf.reduce((a,b)=>a+b,0) / this._buf.length);
  }
  p95() {
    if (!this._buf.length) return null;
    const sorted = [...this._buf].sort((a,b)=>a-b);
    return sorted[Math.floor(sorted.length * 0.95)];
  }
}

// ── createPulse ───────────────────────────────────────────────────────────────

/**
 * createPulse — register this system with the orchestrator and send a
 * periodic heartbeat.  Starts immediately; call stop() to cancel.
 *
 * @param {object} opts
 * @param {string}   opts.systemId        — e.g. 'guardian', 'cortex', 'idearium'
 * @param {number}   opts.port            — this system's port
 * @param {string}   [opts.orchHost]      — orchestrator host (default 127.0.0.1)
 * @param {number}   [opts.orchPort]      — orchestrator port (default 9000)
 * @param {number}   [opts.intervalMs]    — heartbeat interval (default 10000)
 * @param {number}   [opts.timeoutMs]     — request timeout (default 3000)
 * @param {number}   [opts.staleAfterMs]  — log warning if no ACK in N ms (default 35000)
 * @param {function} [opts.onBeat]        — called on every ACK: ({ latency, seq, ts })
 * @param {function} [opts.onMiss]        — called when a beat is missed: ({ seq, elapsed })
 * @param {function} [opts.onOnline]      — called when orchestrator comes back up
 * @param {function} [opts.onOffline]     — called when orchestrator goes down
 * @param {function} [opts.log]           — logger fn (default console.log)
 * @returns {{ stop, getStats, latency }}
 */
function createPulse({
  systemId,
  port,
  orchHost     = '127.0.0.1',
  orchPort     = 9000,
  intervalMs   = 10000,
  timeoutMs    = 3000,
  staleAfterMs = 35000,
  meta         = {},
  onBeat, onMiss, onOnline, onOffline,
  log          = (...a) => console.log('[pulse]', ...a),
} = {}) {
  if (!systemId) throw new Error('pulse: systemId required');
  if (!port)     throw new Error('pulse: port required');

  const _latency   = new _Ring(60);   // last 60 beat latencies (ms)
  let   _seq       = 0;
  let   _missed    = 0;
  let   _lastAck   = Date.now();
  let   _wasOnline = true;
  let   _timer     = null;
  let   _stopped   = false;

  // ── One heartbeat ──────────────────────────────────────────────────────────
  function _beat() {
    if (_stopped) return;
    _seq++;
    const seq    = _seq;
    const sentAt = Date.now();
    const pulseId = randomUUID();

    const body = JSON.stringify({
      systemId,
      port,
      status:   'online',
      seq,
      pulseId,
      ts:       sentAt,
      meta:     {
        ...meta,
        uptime: process.uptime(),
        memMB:  Math.round(process.memoryUsage().rss / 1024 / 1024),
      },
    });

    const req = http.request({
      hostname: orchHost,
      port:     orchPort,
      path:     '/api/heartbeat',
      method:   'POST',
      headers:  {
        'Content-Type':   'application/json',
        'Content-Length': Buffer.byteLength(body),
        'X-Pulse-Id':     pulseId,
        'X-System-Id':    systemId,
      },
    }, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const latency = Date.now() - sentAt;
        _latency.push(latency);
        _lastAck  = Date.now();
        _missed   = 0;

        // Transition: offline → online
        if (!_wasOnline) {
          _wasOnline = true;
          log(`orchestrator back online  latency=${latency}ms`);
          onOnline?.({ latency, seq, ts: Date.now() });
        }

        let ack = {};
        try { ack = JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch {}
        onBeat?.({ latency, seq, ts: Date.now(), pulseId, ack });
      });
    });

    req.setTimeout(timeoutMs, () => {
      req.destroy();
      _handleMiss(seq, sentAt);
    });
    req.on('error', () => _handleMiss(seq, sentAt));
    req.write(body);
    req.end();
  }

  function _handleMiss(seq, sentAt) {
    _missed++;
    const elapsed = Date.now() - _lastAck;

    // Transition: online → offline
    if (_wasOnline && elapsed > staleAfterMs) {
      _wasOnline = false;
      log(`orchestrator OFFLINE  missed=${_missed}  elapsed=${elapsed}ms`);
      onOffline?.({ missed: _missed, elapsed, seq, ts: Date.now() });
    }

    onMiss?.({ seq, elapsed, missed: _missed });
  }

  // ── Registration beat (announce on boot) ──────────────────────────────────
  function _register() {
    const body = JSON.stringify({
      systemId, port, meta,
      registeredAt: Date.now(),
    });
    const req = http.request({
      hostname: orchHost,
      port:     orchPort,
      path:     '/api/register',
      method:   'POST',
      headers:  {
        'Content-Type':   'application/json',
        'Content-Length': Buffer.byteLength(body),
      },
    }, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        let data = {};
        try { data = JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch {}
        if (data.ok) {
          log(`registered with orchestrator :${orchPort}  registry=${Object.keys(data.registry||{}).length} systems`);
        }
      });
    });
    req.setTimeout(5000, () => req.destroy());
    req.on('error', () => {
      // Orchestrator not up yet — will register on first successful heartbeat
    });
    req.write(body);
    req.end();
  }

  // ── Start ──────────────────────────────────────────────────────────────────
  _register();
  _beat(); // immediate first beat
  _timer = setInterval(_beat, intervalMs);
  if (_timer.unref) _timer.unref(); // don't keep process alive just for heartbeats

  // ── Public API ─────────────────────────────────────────────────────────────
  function stop() {
    _stopped = true;
    if (_timer) { clearInterval(_timer); _timer = null; }
    log(`stopped  seq=${_seq}`);
  }

  function getStats() {
    return {
      systemId,
      port,
      seq:       _seq,
      missed:    _missed,
      online:    _wasOnline,
      lastAckMs: Date.now() - _lastAck,
      latency: {
        avg:    _latency.avg(),
        p95:    _latency.p95(),
        recent: _latency.last(5),
      },
    };
  }

  return { stop, getStats };
}

// ── NCP client pulse (browser tab → Guardian NCP) ─────────────────────────────
// Used by the Tampermonkey userscript and any browser page that opens an NCP channel.
// In Node.js contexts this is the same pattern but via http.request instead of fetch.

/**
 * createNCPPulse — send periodic NCP heartbeat from a browser tab (or Node) to Guardian.
 * This is the client-side half of ncp.js handleHeartbeat.
 *
 * Only used in browser (fetch). For Node use createPulse.
 *
 * @param {object} opts
 * @param {string} opts.provider     — 'claude' | 'chatgpt' | etc.
 * @param {string} opts.tabId        — UUID assigned when channel was opened
 * @param {string} opts.guardianUrl  — base URL e.g. 'http://127.0.0.1:7820'
 * @param {number} [opts.intervalMs] — default 5000
 * @param {function} [opts.onAck]    — called with { latency, serverTs }
 * @param {function} [opts.onError]  — called with error message
 */
function createNCPPulse({
  provider, tabId, guardianUrl = 'http://127.0.0.1:7820',
  intervalMs = 5000,
  onAck, onError,
} = {}) {
  if (!provider || !tabId) throw new Error('ncpPulse: provider and tabId required');

  const _latency = new _Ring(20);
  let _timer     = null;
  let _stopped   = false;

  async function _beat() {
    if (_stopped) return;
    const sentAt = Date.now();
    try {
      const r = await fetch(`${guardianUrl}/heartbeat`, {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({ provider, tabId, ts: sentAt }),
        signal:  AbortSignal.timeout(3000),
      });
      const data = await r.json();
      const latency = Date.now() - sentAt;
      _latency.push(latency);
      onAck?.({ latency, serverTs: data.ts, seq: data.seq });
    } catch(e) {
      onError?.(e.message || 'heartbeat failed');
    }
  }

  _beat();
  _timer = setInterval(_beat, intervalMs);

  return {
    stop()     { _stopped = true; clearInterval(_timer); _timer = null; },
    latency()  { return { avg: _latency.avg(), p95: _latency.p95(), recent: _latency.last(3) }; },
  };
}

module.exports = { createPulse, createNCPPulse, _Ring };

'use strict';
/**
 * cortex/memory/table-compactor.js — generic hard-delete decay for
 * high-volume short-tier tables, generalizing orchestrator/lib/
 * sigma-compaction.js's own real, proven pattern (rollup/summary THEN
 * hard-delete, never a bare tombstone) beyond just sigma_records.
 *
 * §BUILT 2026-09-12 — James: "we need decay for tables." Traced, not
 * guessed: cortex/memory/decay.js's runDecaySweep() only ever tombstones
 * (_evicted:true), by deliberate design (§7.4 "nothing discarded,
 * archived instead") — but a tombstoned row "still lives in the file and
 * still gets parsed by every process" (sigma-compaction.js's own header,
 * confirmed directly by reading jaa-db.js's open(): it loads every row of
 * every real .jsonl table into memory unconditionally, tombstoned or
 * not). For a low-volume table that's the right, safe default. For a
 * real, high-volume, append-only table — event_log (71,765+ rows and
 * climbing in this session's own boot logs, already tiered 'short' but
 * never actually enforced this way), component_ledger (49,440+ rows,
 * the single biggest real table observed, previously undeclared in
 * tiers.js at all — not even tombstoned) — tombstone-only means the
 * table simply never shrinks, ever, and every one of the ~9 processes
 * that open the shared JAA store pays that growing cost forever.
 *
 * This is that missing real enforcement, built as one shared,
 * table-agnostic mechanism instead of a bespoke copy per table (§10.3).
 * sigma-compaction.js's own rollup/merge logic stays exactly as-is (it
 * has a genuinely bespoke statistical shape — avg/max sigma, warn/halt
 * counts — not worth generalizing away from); this module handles every
 * OTHER real, high-volume table with a simpler, still-real "compressed
 * count, not silently destroyed" summary.
 *
 * §0.3 — nothing lost silently. Every real deleted batch is accounted
 * for in a compaction_log summary row (table, deletedCount, oldestTs,
 * newestTs, cutoff) written BEFORE the delete — compressed history, not
 * destroyed history, same ordering sigma-compaction.js already proved,
 * generalized rather than duplicated per table.
 *
 * §HONEST SCOPE — this does NOT retroactively apply to every table
 * tiers.js declares. Only the tables explicitly passed to start()'s
 * real, explicit tables[] list get real hard-delete; every other
 * tiered table keeps decay.js's existing tombstone-only behavior as its
 * safe default. Adding a table here is a deliberate, separate choice
 * from declaring its tier — real data loss risk (even compressed) is
 * not something to opt a table into by default. Confirmed real,
 * high-volume, append-only tables wired at orchestrator boot: event_log,
 * component_ledger, cfr_tension_history, constitution_decisions,
 * chat_log, schema_drift.
 *
 * §RESOLVED 2026-09-12 — the remaining tables named in the prior version
 * of this comment (hooks, interstitial_spaces, memory_unified,
 * raid_contract_queue, tool_index, fault_taxonomy, forge_patches,
 * raid_tunables) have now been checked against their real writers (see
 * tiers.js's own per-entry comments) and confirmed genuinely long-tier —
 * living/structural state (registries, queues, permanent memory
 * structures), not historical logs — never wired here on purpose, not
 * an oversight.
 */

const { tierFor, tierConfig } = require('./tiers.js');

const MODULE_ID = 'cortex.memory.table-compactor';

/**
 * compactTable(jaa, table, now) — one real pass over one real table.
 * Deliberately per-table (not a bulk loop hidden inside start()), so a
 * caller can compact one table on demand (tests, a manual admin
 * trigger) without needing the whole periodic sweep.
 */
function compactTable(jaa, table, now = Date.now()) {
  const tier = tierFor(table);
  const cfg = tier && tierConfig(tier);
  if (!cfg || cfg.evictAfterMs == null) {
    return { table, deleted: 0, skipped: true, reason: tier ? `${tier} tier never expires` : 'table is not tier-managed' };
  }
  const cutoff = now - cfg.evictAfterMs;

  // §1.2 — same honest-undatable rule as decay.js's isExpired(): a row
  // with no real timestamp is never assumed old. Re-implemented directly
  // (not required from decay.js) to avoid a real circular require —
  // decay.js requires jaa-db.js, and this module is meant to be usable
  // from orchestrator (a different process) without pulling cortex's
  // whole decay ticker in — same three-field fallback either way.
  function rowTs(row) {
    const ts = row.ts ?? row.crystallisedAt ?? row.createdAt;
    return typeof ts === 'number' ? ts : null;
  }
  const isExpiredRow = (r) => !r._evicted && rowTs(r) !== null && rowTs(r) < cutoff;

  let expired;
  try { expired = jaa.query(table, isExpiredRow, 1000000) || []; }
  catch (e) { return { table, deleted: 0, skipped: true, reason: `query failed: ${e.message}` }; }
  if (!expired.length) return { table, deleted: 0, cutoff };

  let oldestTs = Infinity, newestTs = -Infinity;
  for (const r of expired) { const t = rowTs(r); if (t < oldestTs) oldestTs = t; if (t > newestTs) newestTs = t; }

  // §0.3 — the summary IS the compressed history for this batch, written
  // BEFORE the real delete, same ordering sigma-compaction.js uses.
  try {
    jaa.insert('compaction_log', {
      uuid: require('crypto').randomUUID(), table, deletedCount: expired.length,
      oldestTs, newestTs, cutoff, ts: now,
    });
  } catch (e) {
    console.warn(`[${MODULE_ID}] compaction_log write failed for ${table} (real delete below still proceeds — the delete itself is the more urgent real fix): ${e.message}`);
  }

  let deleted = 0;
  try { deleted = jaa.delete(table, isExpiredRow) || 0; }
  catch (e) { console.warn(`[${MODULE_ID}] delete failed for ${table}: ${e.message}`); return { table, deleted: 0, skipped: true, reason: `delete failed: ${e.message}` }; }

  console.log(`[${MODULE_ID}] ${table}: compacted ${deleted} expired row(s) older than ${(cfg.evictAfterMs / 3600000).toFixed(1)}h (cutoff ${new Date(cutoff).toISOString()})`);
  return { table, deleted, cutoff };
}

/**
 * capTable(jaa, table, keyFn, maxPerGroup, now) — count-based retention,
 * complementing compactTable's own age-based retention. James: "should be
 * able to clear sigmas. maybe delete after 100? per system."
 *
 * sigma_records has no literal `system` field (checked orchestrator/lib/
 * sigma-writer.js's real record shape directly before assuming one) — its
 * real per-source dimension is `type` (the originating bus event type,
 * e.g. 'cortex.boot', 'guardian.job.queued' — effectively "which system
 * produced the signal being scored"). Rather than hardcode `type` as a
 * special case, keyFn is a real, explicit, caller-supplied grouping
 * function — same "no default guessed" discipline as dedup's own
 * fingerprint — so this stays usable for any other table with a
 * different real grouping field, not just this one.
 *
 * Keeps the maxPerGroup MOST RECENT rows in each group (by rowTs, same
 * fallback chain as compactTable's own — ts ?? crystallisedAt ??
 * createdAt), removes the rest. A row with no real timestamp sorts as
 * oldest (never preferentially kept over a datable row) rather than
 * being silently excluded from consideration entirely — it still counts
 * toward the group and can still be removed, just never chosen ahead of
 * a row that has real evidence of recency.
 */
function capTable(jaa, table, keyFn, maxPerGroup, now = Date.now()) {
  if (typeof keyFn !== 'function') throw new Error(`[${MODULE_ID}] capTable() requires a real, explicit keyFn(row) — no default grouping is guessed`);
  if (!(maxPerGroup > 0)) throw new Error(`[${MODULE_ID}] capTable() requires a real maxPerGroup > 0`);

  function rowTs(row) {
    const ts = row.ts ?? row.crystallisedAt ?? row.createdAt;
    return typeof ts === 'number' ? ts : -Infinity; // undatable sorts oldest, never preferred over a datable row
  }

  let rows;
  try { rows = jaa.query(table, () => true, 10000000) || []; }
  catch (e) { return { table, removed: 0, skipped: true, reason: `query failed: ${e.message}` }; }
  if (!rows.length) return { table, removed: 0, groups: 0 };

  const groups = new Map();
  for (const r of rows) {
    let key;
    try { key = keyFn(r); } catch (_) { key = null; }
    if (key == null) continue; // keyFn declined to classify — never a guessed group
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }

  const toRemove = [];
  let groupsOverCap = 0;
  for (const [key, group] of groups) {
    if (group.length <= maxPerGroup) continue;
    groupsOverCap++;
    group.sort((a, b) => rowTs(b) - rowTs(a)); // newest first
    for (const r of group.slice(maxPerGroup)) toRemove.push(r);
  }

  if (!toRemove.length) return { table, removed: 0, groups: 0 };

  try {
    jaa.insert('compaction_log', {
      uuid: require('crypto').randomUUID(), table, deletedCount: toRemove.length,
      kind: 'count_cap', maxPerGroup, groupsOverCap, ts: now,
    });
  } catch (e) {
    console.warn(`[${MODULE_ID}] compaction_log write failed for ${table} count-cap (real delete below still proceeds): ${e.message}`);
  }

  // §FIXED 2026-09-12 — this used to be a Set of row object REFERENCES,
  // matched via removeRefs.has(r) inside delete()'s predicate. That only
  // ever worked against the mock in this module's own tests, which
  // reuses the same array/objects across query() and delete() calls.
  // The REAL store (guardian/jaa-store.js) returns a fresh {...row}
  // spread copy on every query() — confirmed directly, not assumed —
  // so a second query (or the live Map iteration delete() itself walks)
  // can never be reference-equal to what an earlier query() returned.
  // Found live, against James's real data: 7 real sigma_records groups
  // exceeded the cap by thousands of rows each, and the real delete()
  // call reported 0 removed regardless. Fixed by matching on the real,
  // stable uuid field every row has, not the transient object identity
  // of whichever copy happened to be in hand.
  const removeUuids = new Set(toRemove.map(r => r.uuid).filter(Boolean));
  let removed = 0;
  try { removed = jaa.delete(table, (r) => removeUuids.has(r.uuid)) || 0; }
  catch (e) { console.warn(`[${MODULE_ID}] delete failed for ${table}: ${e.message}`); return { table, removed: 0, skipped: true, reason: `delete failed: ${e.message}` }; }

  console.log(`[${MODULE_ID}] ${table}: capped ${groupsOverCap} group(s) to ${maxPerGroup} row(s) each, removed ${removed} total`);
  return { table, removed, groups: groupsOverCap };
}

let _timer = null;

/**
 * start(jaa, tables, intervalMs) — periodic sweep over a REAL, explicit
 * list of tables — deliberately not "every short-tier table in
 * TABLE_TIERS" by default (see §HONEST SCOPE above).
 */
function start(jaa, tables, intervalMs = 10 * 60 * 1000) {
  if (!Array.isArray(tables) || !tables.length) throw new Error(`[${MODULE_ID}] start() requires a real, explicit tables[] list`);
  function sweep() {
    for (const table of tables) {
      try { compactTable(jaa, table); }
      catch (e) { console.warn(`[${MODULE_ID}] compaction tick failed for ${table}: ${e.message}`); }
    }
  }
  sweep(); // boot compaction clears the accumulated backlog immediately, same as sigma-compaction.js
  _timer = setInterval(sweep, intervalMs);
  if (_timer.unref) _timer.unref();
  console.log(`[${MODULE_ID}] v1.0.0 — real hard-delete compaction for [${tables.join(', ')}], every ${intervalMs / 60000}min`);
  return { ok: true };
}

function stop() {
  if (_timer) { clearInterval(_timer); _timer = null; }
}

let _capTimer = null;

/**
 * startCaps(jaa, specs, intervalMs) — periodic count-based retention,
 * separate timer from age-based start() (different real operation, same
 * separation-of-concerns reasoning table-deduplicator.js's own start()
 * already uses against this same module). specs: [{ table, keyFn,
 * maxPerGroup }, ...] — real, explicit, no default table list guessed.
 */
function startCaps(jaa, specs, intervalMs = 30 * 60 * 1000) {
  if (!Array.isArray(specs) || !specs.length) throw new Error(`[${MODULE_ID}] startCaps() requires a real, explicit specs[] list`);
  function sweep() {
    for (const spec of specs) {
      try { capTable(jaa, spec.table, spec.keyFn, spec.maxPerGroup); }
      catch (e) { console.warn(`[${MODULE_ID}] cap tick failed for ${spec.table}: ${e.message}`); }
    }
  }
  sweep();
  _capTimer = setInterval(sweep, intervalMs);
  if (_capTimer.unref) _capTimer.unref();
  console.log(`[${MODULE_ID}] count-cap active for [${specs.map(s => `${s.table}:${s.maxPerGroup}/group`).join(', ')}]`);
  return { ok: true };
}

function stopCaps() {
  if (_capTimer) { clearInterval(_capTimer); _capTimer = null; }
}

module.exports = { MODULE_ID, compactTable, capTable, start, stop, startCaps, stopCaps };

#!/usr/bin/env node
/**
 * guardian/cli.js  (or: add `guardian` to your PATH)
 * ─────────────────────────────────────────────────────────────────────────────
 * Guardian CLI — sends commands to the bridge server
 *
 * Usage:
 *   guardian /code claude make me a hat
 *   guardian /spec chatgpt ./spec.md
 *   guardian /ask gemini "what is entropy"
 *   guardian /paste claude < ./file.txt
 *   guardian /multi claude chatgpt "explain recursion"
 *   guardian status
 *   guardian jobs
 *   guardian providers
 *   guardian watch <jobId>
 *
 * The server must be running:
 *   node server.js
 * ─────────────────────────────────────────────────────────────────────────────
 */

'use strict';

const http = require('http');
const fs   = require('fs');
const path = require('path');

const HOST = process.env.GUARDIAN_HOST || '127.0.0.1';
const PORT = process.env.GUARDIAN_HTTP_PORT || 7820;
const BASE = `http://${HOST}:${PORT}`;

// ── HTTP helpers ──────────────────────────────────────────────────────────────

function get(endpoint) {
  return new Promise((resolve, reject) => {
    http.get(`${BASE}${endpoint}`, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { reject(new Error('Bad JSON response')); }
      });
    }).on('error', () => reject(new Error(
      `Cannot reach guardian server at ${BASE}\nStart it: node server/server.js`
    )));
  });
}

function post(endpoint, body) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req  = http.request(`${BASE}${endpoint}`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
    }, res => {
      let out = '';
      res.on('data', c => out += c);
      res.on('end', () => {
        try { resolve(JSON.parse(out)); }
        catch { reject(new Error('Bad JSON response')); }
      });
    });
    req.on('error', () => reject(new Error(
      `Cannot reach guardian server at ${BASE}\nStart it: node server/server.js`
    )));
    req.write(data);
    req.end();
  });
}

// ── SSE stream watcher ────────────────────────────────────────────────────────

function watchJob(jobId) {
  return new Promise((resolve) => {
    console.log(`\n[watching ${jobId}]\n`);
    process.stdout.write('');

    const req = http.get(`${BASE}/stream/${jobId}`, res => {
      let buffer = '';
      res.on('data', chunk => {
        buffer += chunk.toString();
        const lines = buffer.split('\n');
        buffer = lines.pop(); // keep incomplete line

        for (const line of lines) {
          if (!line.startsWith('data: ')) continue;
          try {
            const msg = JSON.parse(line.slice(6));
            if (msg.text)   process.stdout.write(msg.text);
            if (msg.done) { process.stdout.write('\n'); resolve(); }
          } catch {}
        }
      });
      res.on('end', resolve);
    });

    req.on('error', () => {
      console.error('Stream error — polling instead');
      pollUntilDone(jobId).then(resolve);
    });
  });
}

// ── polling fallback (no SSE) ─────────────────────────────────────────────────

async function pollUntilDone(jobId, timeoutMs = 120_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await new Promise(r => setTimeout(r, 1500));
    const result = await get(`/response/${jobId}`).catch(() => null);
    if (!result) continue;
    if (result.status === 'complete') {
      console.log('\n' + result.response);
      return;
    }
    if (result.status === 'failed') {
      console.error('\nFailed:', result.error);
      return;
    }
    process.stdout.write('.');
  }
  console.error('\nTimed out waiting for response');
}

// ── watch a SEAM queue's chunk-by-chunk progress ──────────────────────────────
// §NOTE: GET /seam/queues/:id only checks the in-memory _activeQueues map —
// onComplete() deletes the queue from it, so a 404 here is ambiguous between
// "never existed" and "just finished." Treat a 404 *after* having seen the
// queue at least once as completion, not failure — querying too fast after
// the last chunk verifies will otherwise misreport a successful run as an error.
async function watchSeam(queueId, timeoutMs = 600_000) {
  console.log(`\n[watching SEAM queue ${queueId}]\n`);
  const deadline = Date.now() + timeoutMs;
  let sawQueue = false;
  let lastPct = -1;

  while (Date.now() < deadline) {
    const result = await get(`/seam/queues/${queueId}`).catch(() => null);

    if (!result || !result.ok) {
      if (sawQueue) {
        console.log(`\nQueue no longer active — treating as complete. Final state is in JAA: GET ${BASE}/seam/sessions (filter by uuid ${queueId}).`);
        return;
      }
      await new Promise(r => setTimeout(r, 1500));
      continue;
    }

    sawQueue = true;
    const q = result.queue;
    const pct = q.stats.pct;
    if (pct !== lastPct) {
      console.log(`[${pct}%] verified:${q.stats.verified} active:${q.stats.active} retrying:${q.stats.retrying} queued:${q.stats.queued} escalated:${q.stats.escalated}  (${q.stats.total} total)`);
      lastPct = pct;
    }

    if (q.completedAt) {
      console.log(`\nDone — ${q.stats.verified}/${q.stats.total} verified, ${q.stats.escalated} escalated.`);
      return;
    }

    await new Promise(r => setTimeout(r, 2000));
  }
  console.error('\nTimed out watching SEAM queue');
}

// ── command: send a job ───────────────────────────────────────────────────────

async function sendCommand(raw) {
  // Check if content is piped via stdin
  let stdinContent = null;
  if (!process.stdin.isTTY) {
    stdinContent = fs.readFileSync('/dev/stdin', 'utf8');
  }

  const body = stdinContent
    ? { raw, content: stdinContent }
    : { raw };

  const result = await post('/command', body);

  if (!result.ok) {
    console.error('Error:', result.error);
    process.exit(1);
  }

  console.log(`Job: ${result.jobId}  Status: ${result.status}`);

  // Auto-watch unless --no-watch flag
  if (!process.argv.includes('--no-watch')) {
    await watchJob(result.jobId);
  }
}

// ── command: send a file as content ──────────────────────────────────────────

async function sendFile(provider, filePath, extraPrompt) {
  const abs = path.resolve(filePath);
  if (!fs.existsSync(abs)) {
    console.error(`File not found: ${abs}`);
    process.exit(1);
  }

  const content = fs.readFileSync(abs, 'utf8');
  const prompt  = extraPrompt || `Here is the file: ${path.basename(abs)}`;

  const result = await post('/command', {
    command:  'spec',
    provider: provider,
    prompt,
    content,
    source: 'cli',
  });

  if (!result.ok) { console.error('Error:', result.error); process.exit(1); }
  console.log(`Job: ${result.jobId}  Status: ${result.status}`);
  await watchJob(result.jobId);
}

// §SEAM-GLUE-FIX: sendFile() above sends `content`, which guardian/server.js's
// /command handler never checks (it only checks body.spec/specText/specFile —
// see guardian/server.js ~2565) — so /spec was silently falling through to
// the same single-blob path as /file, never reaching the real parseSpec() +
// SEAMQueue pipeline that already exists and works. This is the actual SEAM
// entry point: real chunking, real retry state machine, real session.
async function sendSpec(provider, filePath, title) {
  const abs = path.resolve(filePath);
  if (!fs.existsSync(abs)) {
    console.error(`File not found: ${abs}`);
    process.exit(1);
  }

  const specText = fs.readFileSync(abs, 'utf8');

  const result = await post('/command', {
    command: 'spec',
    provider,
    specText,
    title: title || path.basename(abs),
    source: 'cli',
  });

  if (!result.ok) { console.error('Error:', result.error); process.exit(1); }
  console.log(`SEAM queue: ${result.queueId}`);
  console.log(`Title: ${result.title}   Provider: ${result.provider}   Chunks: ${result.total}`);
  if (result.meta?.name) console.log(`Spec: ${result.meta.name}`);
  console.log(`\nWatch progress:  guardian /seam ${result.queueId}`);
  console.log(`Or poll:         GET /seam/queues/${result.queueId}`);
}

// ── command: multi-provider ───────────────────────────────────────────────────

async function sendMulti(providers, prompt) {
  const jobIds = [];

  for (const provider of providers) {
    const result = await post('/command', {
      command: 'multi',
      provider,
      prompt,
    });
    if (result.ok) {
      console.log(`${provider}: ${result.jobId}`);
      jobIds.push({ provider, jobId: result.jobId });
    } else {
      console.error(`${provider}: ${result.error}`);
    }
  }

  // Watch all in parallel
  await Promise.all(jobIds.map(({ provider, jobId }) => {
    console.log(`\n── ${provider} ──`);
    return watchJob(jobId);
  }));
}

// ── display helpers ───────────────────────────────────────────────────────────

function statusIcon(s) {
  return { pending: '⏳', delivered: '📤', streaming: '⚡', complete: '✓', failed: '✗' }[s] || '?';
}

// ── main ──────────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
    console.log(`
Guardian CLI — route commands to AI tabs via browser userscript

Commands that go to AI:
  /code    <provider> <prompt>       Ask for code
  /spec    <provider> <file|prompt>  Send a spec file — real SEAM chunking, not a single blob
  /seam    <queueId>                 Watch a SEAM queue's chunk-by-chunk progress
  /seam    interrupted               List SEAM chunks in INTERRUPTED state (abrupt stop)
  /seam    resume <queueId>          Force-retry the active chunk in a stalled queue
  /ask     <provider> <prompt>       General question
  /paste   <provider>                Pipe content: echo "..." | guardian /paste claude
  /multi   <p1> <p2> <prompt>        Send to multiple providers at once
  /file    <provider> <path> [note]  Send a file's contents

Server info:
  status        Show server health + connected providers
  providers     List which userscripts are connected
  jobs [n]      Show recent jobs (default 20)
  watch <id>    Stream output of a job
  seam interrupted        List interrupted SEAM chunks needing attention
  seam resume <queueId>  Force-retry the active chunk in a stalled queue

Options:
  --no-watch    Don't wait for the response after sending

Providers: claude, chatgpt, gemini, ollama

Examples:
  guardian /code claude "make me a hat in Python"
  guardian /spec chatgpt ./NEXUS-SPEC-v7.md
  guardian /ask gemini "explain entropy"
  guardian /multi claude chatgpt "what is recursion"
  cat ./main.js | guardian /paste claude
  guardian /file claude ./src/app.js "what's wrong with this?"
`);
    return;
  }

  try {
    // ── /multi ──────────────────────────────────────────────────────────────
    if (args[0] === '/multi') {
      // /multi claude chatgpt "prompt here"
      const prompt    = args[args.length - 1];
      const providers = args.slice(1, -1);
      if (providers.length < 2) {
        console.error('Usage: guardian /multi <provider1> <provider2> "prompt"');
        process.exit(1);
      }
      await sendMulti(providers, prompt);
      return;
    }

    // ── /file ────────────────────────────────────────────────────────────────
    if (args[0] === '/file') {
      const [, provider, filePath, ...rest] = args;
      await sendFile(provider, filePath, rest.join(' ') || null);
      return;
    }

    // ── /spec with file path — real SEAM chunking, not a plain file send ──────
    if (args[0] === '/spec' && args[2] && fs.existsSync(path.resolve(args[2]))) {
      await sendSpec(args[1], args[2], args.slice(3).join(' ') || null);
      return;
    }

    // ── server info commands ─────────────────────────────────────────────────
    if (args[0] === 'status') {
      const h = await get('/health');
      console.log(`\nGuardian server — uptime: ${Math.round(h.uptime)}s`);
      console.log(`Jobs tracked: ${h.jobs}   WS clients: ${h.wsClients}`);
      console.log('\nProviders:');
      for (const [name, status] of Object.entries(h.providers)) {
        console.log(`  ${status === 'connected' ? '●' : '○'} ${name.padEnd(10)} ${status}`);
      }
      return;
    }

    if (args[0] === 'providers') {
      const r = await get('/providers');
      for (const [name, status] of Object.entries(r.providers)) {
        console.log(`${status === 'connected' ? '●' : '○'} ${name.padEnd(12)} ${status}`);
      }
      return;
    }

    if (args[0] === 'jobs') {
      const limit = parseInt(args[1] || '20');
      const r = await get(`/jobs?limit=${limit}`);
      if (!r.jobs.length) { console.log('No jobs yet'); return; }
      for (const job of r.jobs) {
        const age = Math.round((Date.now() - job.ts) / 1000);
        console.log(
          `${statusIcon(job.status)} ${job.id.slice(0, 8)}  ${job.provider.padEnd(10)}  /${job.command.padEnd(8)}  ${age}s ago  ${job.prompt.slice(0, 50)}`
        );
      }
      return;
    }

    if (args[0] === 'watch') {
      if (!args[1]) { console.error('Usage: guardian watch <jobId>'); process.exit(1); }
      await watchJob(args[1]);
      return;
    }

    // ── /seam <queueId> — watch a SEAM queue's chunk-by-chunk progress ─────────
    if (args[0] === '/seam') {
      if (!args[1]) { console.error('Usage: guardian /seam <queueId>'); process.exit(1); }

      // ── seam interrupted — list all INTERRUPTED chunks ────────────────────
      if (args[1] === 'interrupted') {
        const result = await get('/seam/queues').catch(e => { console.error(e.message); process.exit(1); });
        const queues = result.queues || [];
        const interrupted = [];
        for (const q of queues) {
          for (const c of (q.compartments || [])) {
            if (c.state === 'GENERATING' && c.updatedAt && (Date.now() - c.updatedAt) > 30000) {
              interrupted.push({ queueId: q.uuid, queueTitle: q.title, chunkIdx: c.chunkIdx,
                chunkTitle: c.chunkTitle, stuckSecs: Math.round((Date.now() - c.updatedAt)/1000),
                watchdogRetries: c.watchdogRetries });
            }
          }
        }
        if (!interrupted.length) {
          console.log('No interrupted SEAM chunks found (nothing stuck > 30s in GENERATING state).');
          process.exit(0);
        }
        console.log(`
${interrupted.length} interrupted chunk(s):
`);
        for (const c of interrupted) {
          console.log(`  Queue: ${c.queueId.slice(0,8)}  "${c.queueTitle}"`);
          console.log(`  Chunk ${c.chunkIdx + 1}: "${c.chunkTitle}"  stuck ${c.stuckSecs}s  watchdog:${c.watchdogRetries}`);
          console.log(`  Resume: guardian /seam resume ${c.queueId}
`);
        }
        process.exit(0);
      }

      // ── seam resume <queueId> — force-retry active chunk ─────────────────
      if (args[1] === 'resume') {
        const queueId = args[2];
        if (!queueId) { console.error('Usage: guardian /seam resume <queueId>'); process.exit(1); }
        const result = await post('/seam/retry', { queueId, reason: 'cli_resume' })
          .catch(e => { console.error(e.message); process.exit(1); });
        if (!result.ok) { console.error(`Resume failed: ${result.error || 'unknown'}`); process.exit(1); }
        if (result.escalated) {
          console.log(`⚠  Chunk escalated — watchdog budget exhausted. Chunk is now ESCALATED (gap logged).`);
        } else {
          console.log(`✓  Retry forced on queue ${queueId.slice(0,8)}.`);
          console.log(`   Watch progress: guardian /seam ${queueId}`);
        }
        process.exit(0);
      }
      await watchSeam(args[1]);
      return;
    }

    if (args[0] === 'log') {
      const r = await get('/log?limit=20');
      for (const entry of r.log) {
        console.log(`\n── ${entry.provider} / ${entry.command} ──`);
        console.log(`Prompt: ${entry.prompt.slice(0, 80)}`);
        console.log(`Response: ${entry.response.slice(0, 200)}...`);
      }
      return;
    }

    // ── /code /ask /paste /spec (raw command) ────────────────────────────────
    if (args[0].startsWith('/')) {
      await sendCommand(args.join(' '));
      return;
    }

    console.error(`Unknown command: ${args[0]}\nRun guardian --help for usage.`);
    process.exit(1);

  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}

main();

