    idea.phase = 'archived'; idea.archiveReason = reason; idea.archivedAt = Date.now(); idea.causedBy = causedBy;
    saveDB(this.os.db, ['ideas']);
    stream.emit(new Event('idearium.idea.archived', { uuid, reason }));
