    suite.declareViaAgent('hook', {
      id: 'test.hook.a', component_id: 'nexus.test.widget', name: 'a', type: 'direct', direction: 'out',
      uuid: 'nexus-test-hook-a-v1-0000-2026-0701-jamesbrooks-001',
