  constructor(opts = {}) {
    this.uuid    = MODULE_UUID;
    this.version = MODULE_VERSION;
    this._bus    = null;
    this._registry = REGISTRY;
    this._router   = ROUTER;
    this._stats  = { executed: 0, failed: 0 };
