 *   o.resolveJob         — Guardian's job resolver (poll to complete)
 *   o.provider           — which browser-tab provider (default claude)
 *   o.streamDigest       — live stream (P7 shares this across systems), optional
 *   o.maxIterations
 */
async function run(o = {}) {
