  async queryCortexMemory(query, limit = 5) {
    const r = await _http(CORTEX_PORT, 'POST', '/api/memory/query', { query, limit }, 8000);
    if (!r.ok) return { error: r.data?.error || 'cortex memory unavailable' };
    return r.data;
  }

