  console.log(`  uptime   ${Math.floor(h.uptime)}s`);

  if (h.jaa?.counts) {
    console.log(divider('JAA tables'));
    for (const [table, count] of Object.entries(h.jaa.counts)) {
      if (count > 0) console.log(`  ${pad(table, 28)} ${c('cyan', String(count))}`);
    }
