      system: 'guardian',
      tags: ['dom', 'response', ...(jobId ? ['job'] : []), ...(compartmentUuid ? ['compartment'] : [])],
      context: `live DOM mutation -> .response node (${domEventType})`,
      source: MODULE_ID,
