  if (_raid.lastDecision) {
    const d = _raid.lastDecision;
    const agentCol = { ollama:'#00ff88', claude:'#818cf8', chatgpt:'#34d399', gemini:'#ff6b35', perplexity:'#00d4ff' };
    const col = agentCol[d.agent] || '#b8cfe0';
