 * dispatcher.js's own queue-when-disconnected path). This file restores
 * a real static KNOWN_PROVIDERS list instead of relying on the
 * connection Proxy at all.
 */

const http = require('http');

// §RECONCILED 2026-09-02 — this package was decompiled from server.js
// before deepseek was added (server.js's own §ADDED 2026-09-02 comment
// on _dispatchToDeepseek). Wiring this package in unmodified would have
// silently dropped deepseek routing entirely. Added here, verbatim
// parity with the same-day server.js addition — not guessed.
const KNOWN_PROVIDERS = ['claude', 'chatgpt', 'gemini', 'perplexity', 'ollama', 'mistral', 'deepseek'];

const PROVIDER_ALIASES = {
  'claude.ai':           'claude',
  'chat.openai.com':     'chatgpt',
  'chatgpt.com':         'chatgpt',
  'gemini.google.com':   'gemini',
  'aistudio.google.com': 'gemini',
  'perplexity.ai':       'perplexity',
  'localhost':           'ollama',
  '127.0.0.1':           'ollama',
  'chat.mistral.ai':     'mistral',
  'chat.deepseek.com':   'deepseek',
};

const _RAID_AGENT_TO_PROVIDER = {
  'ollama':              'ollama',
  'guardian-claude':     'claude',
  'guardian-chatgpt':    'chatgpt',
  'guardian-gemini':     'gemini',
  'guardian-perplexity': 'perplexity',
  'claude':     'claude',
  'chatgpt':    'chatgpt',
  'gemini':     'gemini',
  'perplexity': 'perplexity',
};

/**
 * createProviderRouter(deps) — deps: updateJob, bus (both from
 * guardian/lib/jobs.js's store / server.js's bus), NEXUS_URL (cortex base
 * URL, config.NEXUS_URL in the original), and optional postEvent
 * (nc.postEvent wrapper — non-fatal if omitted, matches original's own
 * `if (nc)` guard). No isProviderConnected/PROVIDERS dependency — see
 * header, that Proxy was never safe for this function to use.
 */
function createProviderRouter(deps) {
  const { updateJob, bus, NEXUS_URL, postEvent } = deps;
  for (const [name, v] of Object.entries({ updateJob, bus, NEXUS_URL })) {
    if (!v) throw new Error(`[provider-routing] missing required dependency: ${name}`);
  }
  const _postEvent = postEvent || (() => {}); // §1.2 non-fatal — matches original's `if (nc)` guard

  function normaliseProvider(raw) {
    if (!raw) return null;
    const r = raw.toLowerCase().trim();
    if (PROVIDER_ALIASES[r]) return PROVIDER_ALIASES[r];
    if (KNOWN_PROVIDERS.includes(r)) return r; // fixed: was PROVIDERS.hasOwnProperty(r), always threw
    for (const key of KNOWN_PROVIDERS) {        // fixed: was Object.keys(PROVIDERS), always []
      if (r.includes(key)) return key;
    }
    return null;
  }

  function parseCommand(raw) {
    const str = (raw || '').trim();
    const match = str.match(/^\/(\w+)\s+(\w[\w.-]*)\s*([\s\S]*)$/);
    if (!match) return null;
    const [, command, providerRaw, rest] = match;
    const provider = normaliseProvider(providerRaw);
    const prompt = rest.trim().replace(/^["']|["']$/g, '');
    return { command: command.toLowerCase(), provider, prompt, raw: str };
  }

  // ── RAID routing seam ────────────────────────────────────────────────────
  // Guardian asks cortex's RAID which provider for this intent before
  // dispatch. Non-fatal: cortex unreachable -> fall back. LAW I lives in RAID.
  async function chooseProvider(intent, fallback = 'claude', preferred = '') {
    if (process.env.GUARDIAN_RAID_OFF === '1') return fallback;
    try {
      const u = new URL('/api/raid/decide', NEXUS_URL);
      u.searchParams.set('intent', (intent || '').slice(0, 300));
      if (preferred) u.searchParams.set('preferred', preferred);
      const decision = await new Promise((resolve, reject) => {
        const req = http.get(u, { timeout: 1500 }, res => {
          let raw = ''; res.on('data', d => raw += d);
          res.on('end', () => { try { resolve(JSON.parse(raw)); } catch (e) { reject(e); } });
        });
        req.on('timeout', () => req.destroy(new Error('raid timeout')));
        req.on('error', reject);
      });
      if (decision?.ok && decision.agent) {
        const provider = _RAID_AGENT_TO_PROVIDER[decision.agent.toLowerCase()] || fallback;
        _postEvent('guardian.route.decided', { agent: decision.agent, provider, reason: decision.reason, cluster: decision.cluster });
        return provider;
      }
      return fallback;
    } catch (e) {
      _postEvent('guardian.route.fallback', { reason: e.message, fallback });
      return fallback;
    }
  }

  // §fix 2026-07-04: /generate never existed on ollama-bridge. Real route
  // is POST /api/jobs + poll GET /api/jobs/:id
  async function _dispatchToMistral(job) {
    const BRIDGE_PORT = parseInt(process.env.OLLAMA_BRIDGE_PORT || '3749');
    const model = process.env.MISTRAL_MODEL || 'mistral:7b-instruct-q4_K_M';
    return new Promise(resolve => {
      const body = JSON.stringify({
        prompt: job.prompt || job.content || '',
        model,
        command: job.command || 'chat',
        jobId: job.id,
        meta: { source: 'guardian-mistral', jobId: job.id },
      });
      const req = http.request({
        hostname: '127.0.0.1', port: BRIDGE_PORT, path: '/api/jobs',
        method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
        timeout: 120000,
      }, res => {
        let raw = '';
        res.on('data', c => raw += c);
        res.on('end', () => {
          try {
            const d = JSON.parse(raw);
            const jobId = d.jobId || d.uuid;
            if (!jobId) { resolve({ ok: false, error: 'no jobId returned' }); return; }
            let polls = 0;
            const poll = () => {
              polls++;
              if (polls > 120) { resolve({ ok: false, error: 'poll timeout' }); return; }
              const pr = http.request({ hostname: '127.0.0.1', port: BRIDGE_PORT, path: `/api/jobs/${jobId}`, method: 'GET', timeout: 5000 }, rs => {
                let rb = ''; rs.on('data', c => rb += c);
                rs.on('end', () => {
                  try {
                    const pd = JSON.parse(rb);
                    if (pd.status === 'complete' || pd.progress === 'complete') {
                      updateJob(job.id, { status: 'complete', response: pd.result || pd.text || '', completedAt: Date.now() });
                      bus.emit('guardian.job.complete', { jobId: job.id, provider: 'mistral', chars: (pd.result || '').length });
                      resolve({ ok: true, text: pd.result || pd.text || '' });
                    } else if (pd.status === 'failed' || pd.progress === 'failed') {
                      resolve({ ok: false, error: pd.error || 'ollama job failed' });
                    } else {
                      setTimeout(poll, 1000);
                    }
                  } catch (_) { setTimeout(poll, 1000); }
                });
              });
              pr.on('error', () => setTimeout(poll, 1000));
              pr.end();
            };
            setTimeout(poll, 1000);
          } catch (e) {
            updateJob(job.id, { status: 'error', error: 'parse error: ' + e.message });
            resolve({ ok: false, error: e.message });
          }
        });
      });
      req.on('timeout', () => { req.destroy(); updateJob(job.id, { status: 'error', error: 'mistral timeout' }); resolve({ ok: false, error: 'timeout' }); });
      req.on('error', e => { updateJob(job.id, { status: 'error', error: e.message }); resolve({ ok: false, error: e.message }); });
      req.write(body); req.end();
    });
  }

  // §ADDED 2026-09-02 — James: "I want deepseek added as an agent." Moved
  // verbatim from server.js's own same-day addition — same real pattern
  // as _dispatchToMistral immediately above (mirrored, not reinvented):
  // DeepSeek's real, commonly-available local models (deepseek-coder-v2,
  // deepseek-r1) are served through Ollama, not a browser tab, so this
  // routes directly to the sovereign ollama-bridge HTTP service, exactly
  // like mistral does.
  async function _dispatchToDeepseek(job) {
    const BRIDGE_PORT = parseInt(process.env.OLLAMA_BRIDGE_PORT || '3749');
    const model = process.env.DEEPSEEK_MODEL || 'deepseek-coder-v2';
    return new Promise(resolve => {
      const body = JSON.stringify({
        prompt: job.prompt || job.content || '',
        model,
        command: job.command || 'chat',
        jobId: job.id,
        meta: { source: 'guardian-deepseek', jobId: job.id },
      });
      const req = http.request({
        hostname: '127.0.0.1', port: BRIDGE_PORT, path: '/api/jobs',
        method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
        timeout: 120000,
      }, res => {
        let raw = '';
        res.on('data', c => raw += c);
        res.on('end', () => {
          try {
            const d = JSON.parse(raw);
            const jobId = d.jobId || d.uuid;
            if (!jobId) { resolve({ ok: false, error: 'no jobId returned' }); return; }
            let polls = 0;
            const poll = () => {
              polls++;
              if (polls > 120) { resolve({ ok: false, error: 'poll timeout' }); return; }
              const pr = http.request({ hostname: '127.0.0.1', port: BRIDGE_PORT, path: `/api/jobs/${jobId}`, method: 'GET', timeout: 5000 }, rs => {
                let rb = ''; rs.on('data', c => rb += c);
                rs.on('end', () => {
                  try {
                    const pd = JSON.parse(rb);
                    if (pd.status === 'complete' || pd.progress === 'complete') {
                      updateJob(job.id, { status: 'complete', response: pd.result || pd.text || '', completedAt: Date.now() });
                      bus.emit('guardian.job.complete', { jobId: job.id, provider: 'deepseek', chars: (pd.result || '').length });
                      resolve({ ok: true, text: pd.result || pd.text || '' });
                    } else if (pd.status === 'failed' || pd.progress === 'failed') {
                      resolve({ ok: false, error: pd.error || 'ollama job failed' });
                    } else {
                      setTimeout(poll, 1000);
                    }
                  } catch (_) { setTimeout(poll, 1000); }
                });
              });
              pr.on('error', () => setTimeout(poll, 1000));
              pr.end();
            };
            setTimeout(poll, 1000);
          } catch (e) {
            updateJob(job.id, { status: 'error', error: 'parse error: ' + e.message });
            resolve({ ok: false, error: e.message });
          }
        });
      });
      req.on('timeout', () => { req.destroy(); updateJob(job.id, { status: 'error', error: 'deepseek timeout' }); resolve({ ok: false, error: 'timeout' }); });
      req.on('error', e => { updateJob(job.id, { status: 'error', error: e.message }); resolve({ ok: false, error: e.message }); });
      req.write(body); req.end();
    });
  }

  return { chooseProvider, normaliseProvider, parseCommand, _dispatchToMistral, _dispatchToDeepseek, PROVIDER_ALIASES };
}

module.exports = { createProviderRouter };

'use strict';
const assert = require('assert');
const { Event, Gate, Axiom, Stream, StreamLog } = require('../core');

let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log(`  ok — ${name}`); }
  catch (e) { fail++; console.log(`  FAIL — ${name}: ${e.message}`); }
}

console.log('WARP core tests');

test('Event is immutable', () => {
  const e = new Event('test.event', { value: 1 });
  assert.throws(() => { e.data.value = 2; }, /* frozen data */);
  assert.strictEqual(e.data.value, 1);
});

test('Event requires a non-empty type', () => {
  assert.throws(() => new Event(''), /type must be a non-empty string/);
});

test('Gate dispatches via signature match by default', () => {
  const g = new Gate('foo.bar', { transform: () => {} });
  assert.strictEqual(g.matches(new Event('foo.bar')), true);
  assert.strictEqual(g.matches(new Event('other')), false);
});

test('Gate.transform is pure — returns events, never touches a stream (testable in total isolation)', () => {
  const g = new Gate('double', { transform: (event) => new Event('doubled', { v: event.data.v * 2 }) });
  const result = g.transform(new Event('double', { v: 21 }));
  assert.strictEqual(result.type, 'doubled');
  assert.strictEqual(result.data.v, 42);
  // No stream object was ever created or passed — this is the whole point.
});

test('Stream signature collision is a hard error', () => {
  const s = new Stream();
  s.register(new Gate('x', { transform: () => {} }));
  assert.throws(() => s.register(new Gate('x', { transform: () => {} })), /Signature collision/);
});

test('Stream depth-first dispatch, matches SISO baseline behavior — gate returns the next event, Stream emits it', () => {
  const s = new Stream();
  const seen = [];
  s.register(new Gate('a', { transform: (e) => { seen.push('a'); return new Event('b'); } }));
  s.register(new Gate('b', { transform: () => { seen.push('b'); } }));
  s.emit(new Event('a'));
  assert.deepStrictEqual(seen, ['a', 'b']);
});

test('Gate returning an array of events emits all of them, depth-first', () => {
  const s = new Stream();
  const seen = [];
  s.register(new Gate('fanout', { transform: () => [new Event('x'), new Event('y')] }));
  s.register(new Gate('x', { transform: () => { seen.push('x'); } }));
  s.register(new Gate('y', { transform: () => { seen.push('y'); } }));
  s.emit(new Event('fanout'));
  assert.deepStrictEqual(seen, ['x', 'y']);
});

test('Unclaimed event lands in pending, same as SISO', () => {
  const s = new Stream();
  s.emit(new Event('unclaimed'));
  assert.strictEqual(s.pending.length, 1);
});

test('Axiom hard failure rejects the transform — never runs, never silent', () => {
  const s = new Stream();
  let ran = false;
  s.register(new Gate('risky', { transform: () => { ran = true; } }));
  s.registerAxiom(new Axiom('no-negative', {
    severity: 'hard',
    check: (event) => (event.data.value ?? 0) >= 0,
  }));
  s.emit(new Event('risky', { value: -5 }));
  assert.strictEqual(ran, false, 'gate must not run on hard axiom failure');
  assert.strictEqual(s.rejected.length, 1);
  assert.strictEqual(s.pending.length, 0, 'rejected is a distinct bucket from pending');
});

test('Axiom soft failure logs but does not block', () => {
  const s = new Stream();
  let ran = false;
  s.register(new Gate('ok', { transform: () => { ran = true; } }));
  s.registerAxiom(new Axiom('style-hint', { severity: 'soft', check: () => false }));
  s.emit(new Event('ok', {}));
  assert.strictEqual(ran, true, 'soft failure must not block execution');
  assert.strictEqual(s.rejected.length, 0);
});

test('StreamLog records every dispatch, including rejections', () => {
  const log = new StreamLog();
  const s = new Stream({ log });
  s.register(new Gate('a', { transform: () => {} }));
  s.registerAxiom(new Axiom('always-fail', { severity: 'hard', check: () => false }));
  s.emit(new Event('a'));
  s.emit(new Event('unclaimed'));
  assert.strictEqual(log.entries().length, 2);
});

test('hook() rejects unknown kinds and non-function plugins', () => {
  const s = new Stream();
  assert.throws(() => s.hook('nonsense', () => {}), /unknown hook kind/);
  assert.throws(() => s.hook('scorer', 'not-a-function'), /must be a function/);
});

console.log(`\n${pass} passed, ${fail} failed\n`);
process.exit(fail > 0 ? 1 : 0);

'use strict';
/**
 * cortex/memory/relevance.js — what a memory is WORTH keeping, measured.
 * comp_id: nexus.cortex.memory.relevance
 * UUID: nexus-memory-relevance-v1-0000-2026-0810-001
 * Version: 0.1.0
 *
 * WHY (James, 2026-08-10): "not just supposed to use a ticker. Could use sigmas
 * or deltas to measure the distance as a more quantifiable and measurable
 * method for decay."
 *
 * RELEVANCE IS NOT AGE. That is the whole idea and it is right. A 30-day-old
 * event that is the ROOT of a live causal chain matters more than a one-hour-old
 * heartbeat with no edges. Clock decay evicts the root and keeps the noise —
 * and then the chain that depended on it dangles, which is exactly the state
 * event_log is in today (see CAUSAL MEASUREMENT below).
 *
 * ── FOUR TERMS, EACH MEASURED FROM SOMETHING THAT ALREADY EXISTS ────────────
 *   causal      does anything descend from this? is it a chain root?
 *                 — meta/cfr/graph.js edges, meta/rfr2/causality traceToRoot
 *   sigma       was it anomalous? an anomaly is the memory worth keeping
 *                 — meta/cfr/sigma.js, sigma_rollups
 *   recurrence  is it part of a crystallised pattern?
 *                 — bep_patterns, crystals
 *   age         a TIEBREAKER between equals, never the criterion
 *
 * The ring buffer already proves the shape: meta/rfr2/kernel evicts by CAPACITY
 * and prunes edges on eviction (H-1), so its graph stays bounded and coherent.
 * What it does not do is choose WHICH event leaves — it takes the oldest. This
 * gives that choice a measurement.
 *
 * ── CAUSAL MEASUREMENT IS CURRENTLY BROKEN, AND THAT IS REPORTED, NOT FIXED ─
 * Measured 2026-08-10 against the live event_log: 11,393 events, 753 carry
 * `causedBy`, and those 753 point at exactly THREE distinct values —
 * "guardian" (188), "liminal" (564), "intelligence" (1). Those are SYSTEM
 * NAMES, not event ids. Not one resolves to a row.
 *
 * So `causedBy` is presently holding provenance-of-source in a field the causal
 * graph reads as causation. meta/cfr/graph.js turns each into a `causal` edge
 * and meta/cfr/kernel-surface.js asserts each as EDGE_CAUSAL_EXPLICIT. 753
 * declared causal edges refer to something that is not an event.
 *
 * This module therefore SEPARATES the two and refuses to score on the bad half:
 * a `causedBy` that is not a UUID is counted as `unresolvableRefs`, never as a
 * descendant. Scoring centrality on system-name edges would make heartbeats
 * from a chatty system look like causal hubs — and that is precisely the memory
 * you would then protect from decay.
 */

const path = require('path');
const ROOT = path.resolve(__dirname, '../..');
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{3,4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function _jaa() {
  try { return require(path.join(ROOT, 'cortex/memory/jaa-db.js')).jaaDB; }
  catch (_) { return null; }
}

/**
 * buildIndex(rows) — one pass, everything the scorer needs.
 * Separates resolvable causal edges from unresolvable references, loudly.
 */
function buildIndex(rows) {
  const byId = new Map();
  for (const r of rows) { const id = r.uuid || r.id; if (id) byId.set(id, r); }

  const children = new Map();          // parentId -> count, RESOLVABLE only
  const unresolvable = new Map();      // bad ref -> count
  let edges = 0;

  for (const r of rows) {
    const p = r.causedBy;
    if (!p) continue;
    if (!UUID_RE.test(String(p)) || !byId.has(String(p))) {
      unresolvable.set(String(p), (unresolvable.get(String(p)) || 0) + 1);
      continue;                        // §1.2 — counted, never treated as an edge
    }
    children.set(p, (children.get(p) || 0) + 1);
    edges++;
  }

  const typeCounts = new Map();
  for (const r of rows) { const t = r.type || '?'; typeCounts.set(t, (typeCounts.get(t) || 0) + 1); }

  return {
    byId, children, typeCounts, edges,
    unresolvableRefs: [...unresolvable.entries()].map(([ref, count]) => ({ ref, count }))
                        .sort((a, b) => b.count - a.count),
    unresolvableTotal: [...unresolvable.values()].reduce((a, b) => a + b, 0),
    total: rows.length,
  };
}

/** Patterns and crystals give the recurrence term real signatures to match. */
function loadRecurrence(jaa) {
  const sigs = new Set();
  if (!jaa) return { sigs, ok: false, reason: 'JAA unavailable — recurrence term will be 0 for every row, which is a BLIND term, not a zero one' };
  try {
    for (const p of jaa.query('bep_patterns', () => true, 10000) || []) {
      if (p.signature) sigs.add(String(p.signature));
      if (p.typeA) sigs.add(String(p.typeA));
      if (p.typeB) sigs.add(String(p.typeB));
    }
    for (const c of jaa.query('crystals', () => true, 1000) || []) {
      if (c.summary) for (const m of String(c.summary).matchAll(/"([a-z0-9._:-]+)"/gi)) sigs.add(m[1]);
    }
    return { sigs, ok: true };
  } catch (e) { return { sigs, ok: false, reason: `pattern tables unreadable: ${e.message}` }; }
}

/**
 * score(row, index, opts) -> { keep, terms, reasons }
 * keep is 0..1 — HIGHER MEANS KEEP. It is not a probability and is not
 * calibrated; it is an ordering. §17.11 — no benchmark is claimed.
 */
function score(row, index, opts = {}) {
  const now = opts.now || Date.now();
  const recurrence = opts.recurrence || { sigs: new Set(), ok: false };
  const id = row.uuid || row.id;
  const reasons = [];

  // ── CAUSAL — descendants, and being a chain root ────────────────────────
  let causal = 0;
  const kids = index.children.get(id) || 0;
  if (kids > 0) {
    causal += Math.min(0.7, 0.25 + Math.log2(kids + 1) * 0.15);
    reasons.push(`${kids} event(s) descend from this`);
    if (!row.causedBy) { causal += 0.3; reasons.push('causal ROOT — nothing above it to reconstruct it from'); }
  }
  causal = Math.min(1, causal);

  // ── SIGMA — anomaly is the memory worth keeping ─────────────────────────
  let sigma = 0;
  const s = Number.isFinite(row.sigma) ? row.sigma : (row.payload && Number.isFinite(row.payload.sigma) ? row.payload.sigma : null);
  if (s !== null) { sigma = Math.max(0, Math.min(1, s)); if (sigma > 0.3) reasons.push(`sigma ${sigma.toFixed(3)}`); }
  else if (/error|fail|violation|reject|halt|breach/i.test(String(row.type || ''))) {
    sigma = 0.6; reasons.push('failure-class event with no sigma recorded — treated as deviation');
  }

  // ── RECURRENCE — part of a crystallised pattern ─────────────────────────
  let recur = 0;
  if (recurrence.ok && row.type && recurrence.sigs.has(String(row.type))) {
    recur = 0.5; reasons.push(`type appears in a crystallised pattern`);
  }

  // ── RARITY — a type seen once is unreconstructable; one seen 5,000 times
  //    is reconstructable from any of its siblings.
  let rarity = 0;
  const seen = index.typeCounts.get(row.type || '?') || 1;
  if (seen <= 3) { rarity = 0.4; reasons.push(`type seen only ${seen}×`); }
  else if (seen > 1000) { rarity = -0.2; reasons.push(`type seen ${seen}× — highly reconstructable`); }

  // ── AGE — TIEBREAKER ONLY. Deliberately the smallest weight. Making age
  //    the criterion is the design being replaced.
  const ageH = (now - (row.ts || now)) / 3600000;
  const ageTerm = Math.max(0, 1 - ageH / (24 * 30));

  const keep = Math.max(0, Math.min(1,
    causal * 0.40 + sigma * 0.25 + recur * 0.15 + rarity * 0.10 + ageTerm * 0.10));

  return {
    id, keep: +keep.toFixed(4),
    terms: { causal: +causal.toFixed(3), sigma: +sigma.toFixed(3), recurrence: recur, rarity, age: +ageTerm.toFixed(3) },
    ageHours: +ageH.toFixed(1),
    reasons: reasons.length ? reasons : ['no retention signal — reconstructable, unreferenced, unremarkable'],
  };
}

/**
 * pressure(table, opts) — what a capacity-bounded eviction WOULD drop, ranked
 * by measured relevance instead of by clock.
 *
 * Reports, never evicts. The ring buffer takes the oldest; this says which the
 * oldest actually are in value terms.
 */
function pressure(table = 'event_log', opts = {}) {
  const jaa = _jaa();
  if (!jaa) return { ok: false, reason: 'JAA unavailable' };
  let rows;
  try { rows = jaa.query(table, () => true, 200000) || []; }
  catch (e) { return { ok: false, reason: `${table} unreadable: ${e.message}` }; }
  if (!rows.length) return { ok: true, table, rows: 0, note: 'table is empty' };

  const index = buildIndex(rows);
  const recurrence = loadRecurrence(jaa);
  const now = opts.now || Date.now();
  const scored = rows.map(r => score(r, index, { now, recurrence }));
  scored.sort((a, b) => a.keep - b.keep);

  const cap = opts.cap || Math.floor(rows.length * 0.8);
  const wouldDrop = Math.max(0, rows.length - cap);

  // The comparison that makes the case: how many rows would clock-decay drop
  // that measured relevance would KEEP?
  const evictAfterH = opts.evictAfterHours || 24;
  const clockDrops = scored.filter(s => s.ageHours > evictAfterH);
  const highValueClockDrops = clockDrops.filter(s => s.keep >= 0.35);

  return {
    ok: true, table, rows: rows.length,
    causal: {
      resolvableEdges: index.edges,
      unresolvableRefs: index.unresolvableTotal,
      offenders: index.unresolvableRefs.slice(0, 5),
      // §0.1 — the causal term cannot be trusted while this is non-zero.
      warning: index.unresolvableTotal
        ? `${index.unresolvableTotal} causedBy values do not resolve to an event (top: ${index.unresolvableRefs.slice(0, 3).map(o => `"${o.ref}"×${o.count}`).join(', ')}). These are counted, NOT scored as descendants — the causal term is measuring only ${index.edges} real edges.`
        : undefined,
    },
    recurrenceTerm: recurrence.ok ? `${recurrence.sigs.size} pattern signatures` : `BLIND — ${recurrence.reason}`,
    lowestValue: scored.slice(0, Math.min(8, wouldDrop || 8)),
    highestValue: scored.slice(-5).reverse(),
    clockComparison: {
      evictAfterHours: evictAfterH,
      clockWouldDrop: clockDrops.length,
      ofWhichHighValue: highValueClockDrops.length,
      verdict: highValueClockDrops.length
        ? `clock decay at ${evictAfterH}h would drop ${highValueClockDrops.length} rows that measure as WORTH KEEPING`
        : `clock decay at ${evictAfterH}h and measured relevance agree on this data`,
      examples: highValueClockDrops.slice(0, 3).map(s => ({ keep: s.keep, ageHours: s.ageHours, reasons: s.reasons })),
    },
  };
}

module.exports = { buildIndex, loadRecurrence, score, pressure, UUID_RE, VERSION: '0.1.0' };

