  AES_GCM: 'aes-256-gcm',
  HMAC:    'sha256',
  HASH256: 'sha256',
  HASH512: 'sha512',
};

const SIZES = {
  IV:       16,   // AES-GCM IV bytes
  TAG:      16,   // GCM auth tag bytes
  SALT:     32,   // scrypt salt bytes
  KEY:      32,   // AES-256 key bytes
  HKDF_OUT: 32,   // HKDF output bytes
  TOKEN:    32,   // random token bytes
};

// ─── Result helpers ───────────────────────────────────────────────────────────
