// ── §2.3 Log ──────────────────────────────────────────────────────────────────
function _log(type, msg, detail) {
  const T = { info:{c:'#94a3b8',i:'·'}, in:{c:'#60a5fa',i:'↓'}, out:{c:'#a78bfa',i:'↑'},
    ok:{c:'#34d399',i:'✓'}, err:{c:'#f87171',i:'✗'}, job:{c:'#fbbf24',i:'⚡'},
    gap:{c:'#f472b6',i:'△'}, sys:{c:'#818cf8',i:'◈'}, use:{c:'#2dd4bf',i:'~'},
