// ══ NEXUS MODULE ════════════════════════════════════════════════════════════
// Wires the chat tab into NEXUS:
//   1. MutationObserver watches conversation DOM — every new message is captured
//   2. BDA signal extraction on each message (via Cortex /api/meta/observe)
//   3. Gap scoring on AI responses (via Cortex /api/meta/gaps)
//   4. Semantic context pull (via /api/search) — surfaces relevant past work
//   5. Ollama fallback (GM_xmlhttpRequest to 127.0.0.1:11434) for offline use
//   6. Inline annotations added to AI messages in the chat DOM

const _nexus = {
  observer:    null,
  lastMsgCount:0,
  sessionId:   null,
  signals:     [],
  context:     '',
  ollamaOk:    null,
  pending:      false,
  wakeHandledIndex: -1,   // §2026-08-22 — dedup guard for streaming-message wake detection
};

// ── Extract all visible messages from the DOM ─────────────────────────────────
function _nexusGetMessages() {
  const msgs = [];
  // Claude message selectors
  const humanEls = document.querySelectorAll(
    '[data-testid="human-turn-content"], .human-turn, [class*="HumanMessage"]'
  );
  const aiEls = document.querySelectorAll(
    '[data-testid="assistant-turn-content"], .font-claude-message, [class*="AssistantMessage"]'
  );
  // Interleave by DOM order
  const all = [...document.querySelectorAll(
    '[data-testid="human-turn-content"], [data-testid="assistant-turn-content"], .font-claude-message, .human-turn'
  )];
  for (const el of all) {
    const text = (el.innerText || el.textContent || '').trim();
    if (!text || text.length < 5) continue;
    const isHuman = el.matches('[data-testid="human-turn-content"], .human-turn, [class*="HumanMessage"]');
    msgs.push({ role: isHuman ? 'user' : 'assistant', text: text.slice(0, 2000) });
  }
  return msgs;
}

// ── Post message to NEXUS (chat-logger + BDA) ─────────────────────────────────
function _nexusLogMessage(msg) {
  // POST to Cortex /api/meta/observe for BDA signal extraction
  GM_xmlhttpRequest({
    method: 'POST',
    url: CORTEX_URL + '/api/meta/observe',
    headers: { 'Content-Type': 'application/json' },
    data: JSON.stringify({
      role:      msg.role,
      text:      msg.text,
      sessionId: _nexus.sessionId,
      source:    PROVIDER,
      chatUrl:   location.href,
      account:   window.NexusWake?.detectAccount?.(PROVIDER) || null,
    }),
    onload: (r) => {
      try {
        const d = JSON.parse(r.responseText);
        if (d?.result?.signals) {
          _nexus.signals.push({ ...d.result.signals, role: msg.role, ts: Date.now() });
          // Update NEXUS tab if open
          if (activeTab === 'nexus') renderNexus();
          // Annotate the message in DOM if gap score is high
          if (d.result.pendulum?.regime && d.result.pendulum.regime !== 'STABLE') {
            _nexusAnnotate(msg.role, d.result.pendulum.regime, d.result.gaps?.length || 0);
          }
        }
      } catch(_) {}
    },
    onerror: () => {},
  });
}

// ── Pull semantic context from NEXUS memory ────────────────────────────────────
function _nexusPullContext(query) {
  if (!query || _nexus.pending) return;
  _nexus.pending = true;
  GM_xmlhttpRequest({
    method: 'GET',
    url: ORCH_URL + '/api/search?q=' + encodeURIComponent(query.slice(0, 200)) + '&k=5&threshold=0.68&table=artifacts',
    onload: (r) => {
      _nexus.pending = false;
      try {
        const d = JSON.parse(r.responseText);
        if (d?.results?.length) {
          _nexus.context = d.results;
          if (activeTab === 'nexus') renderNexus();
        }
      } catch(_) { _nexus.pending = false; }
    },
    onerror: () => { _nexus.pending = false; },
  });
}

// ── Ollama fallback via GM_xmlhttpRequest ─────────────────────────────────────
// When Ollama is running locally and Guardian's Node process can't reach it,
// the userscript can call it directly — browser has no CORS restrictions via GM.
// Deliberately talks to raw Ollama (:11434), not the bridge (:3749): this path
// exists specifically for when Node-side infrastructure, bridge included,
// might not be reachable — routing it through the bridge would defeat the one
// real reason it exists.
//
// §CONFIG 2026-08-23 — was a hardcoded 'qwen2.5-coder:1.5b', with no way to
// pick up ollama/config.js's real DEFAULT_MODEL (browser context, this file
// can't require() a Node module). Real fix, not a copied literal that will
// drift again the next time the model changes: _nexusCheckOllama already
// queries /api/tags for real, installed models — now remembers that real
// list, and this function picks from it using the same resilient preference
// chain cli/nexus-repl.js's own real 'chat' command uses (§FIXED 2026-08-23
// there too) — prefer any qwen2.5-coder-family model actually installed,
// then any qwen, then mistral, then whatever's first — rather than trust a
// hardcoded guess of what "the" model is.
//
// §BUILD 2026-08-30 — James, correcting an earlier misread this same day:
// "It's supposed to be able to toggle between ollama and guardian." An
// earlier version of this pass REMOVED this function believing "changing
// ollama to co-pilot" meant full replacement — wrong, and restored here
// verbatim. The real intent was always a toggle, not a replacement.
function _nexusPickOllamaModel() {
  const models = _nexus.ollamaModels || [];
  if (!models.length) return 'qwen2.5-coder:1.5b'; // §1.2 — honest last-resort guess, only when discovery itself has never succeeded
  return models.find(m => m.includes('qwen2.5-coder'))
      || models.find(m => m.startsWith('qwen'))
      || models.find(m => m.startsWith('mistral'))
      || models[0];
}

function _nexusOllamaQuery(prompt, cb) {
  GM_xmlhttpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:11434/api/generate',
    headers: { 'Content-Type': 'application/json' },
    data: JSON.stringify({
      model:  _nexusPickOllamaModel(),
      prompt,
      stream: false,
    }),
    timeout: 30000,
    onload: (r) => {
      try {
        const d = JSON.parse(r.responseText);
        _nexus.ollamaOk = true;
        cb(null, d.response || '');
      } catch(e) { cb(e.message, null); }
    },
    onerror: (e) => {
      _nexus.ollamaOk = false;
      cb('Ollama unreachable', null);
    },
    ontimeout: () => {
      _nexus.ollamaOk = false;
      cb('Ollama timeout', null);
    },
  });
}

// §BUILD 2026-08-30 — James: "changing ollama to co-pilot. hook it into
// the copilot cli or server.js." The REAL, corrected intent (see the
// note above _nexusPickOllamaModel): a second, genuinely NEXUS-aware
// backend a person can TOGGLE to, alongside Ollama, not instead of it.
// copilot's real POST /api/prompt (confirmed directly against copilot/
// server.js, the same route this session already wired guardian-
// picker.js's "Co-pilot CLI" link target to) does real context
// assembly (7 real context layers, per its own response shape), real
